import { Injectable, NotFoundException, BadRequestException, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/sequelize';
import { Op } from 'sequelize';
import { CcAiAgent } from './models/ai-agent.model';
import { CcAiProvider } from './models/ai-provider.model';
import { CcAiToolset } from './models/ai-toolset.model';
import { CreateAiAgentDto, UpdateAiAgentDto } from './dto/ai-agent.dto';

/**
 * AI Agents CRUD. Validates provider/toolset references against the
 * tenant's own rows + global templates (`user_uid = 0`), enforces unique
 * `unique_id` per tenant, and rejects cascade-mode agents that miss
 * STT/TTS profiles.
 */
@Injectable()
export class AiAgentsService {
  private readonly logger = new Logger(AiAgentsService.name);

  constructor(
    @InjectModel(CcAiAgent) private readonly agentModel: typeof CcAiAgent,
    @InjectModel(CcAiProvider) private readonly providerModel: typeof CcAiProvider,
    @InjectModel(CcAiToolset) private readonly toolsetModel: typeof CcAiToolset,
  ) {}

  findAll(userUid: number) {
    return this.agentModel.findAll({
      where: { user_uid: userUid },
      order: [['name', 'ASC']],
    });
  }

  async findOne(id: number, userUid: number) {
    const row = await this.agentModel.findOne({ where: { uid: id, user_uid: userUid } });
    if (!row) throw new NotFoundException('AI agent not found');
    return row;
  }

  async create(dto: CreateAiAgentDto, userUid: number) {
    await this.validateLinkedEntities(dto, userUid);
    await this.assertUniqueId(dto.unique_id, userUid, null);
    this.assertModeConsistency(dto);

    return this.agentModel.create({
      name: dto.name,
      unique_id: dto.unique_id,
      mode: dto.mode,
      voice: dto.voice || '',
      greeting: dto.greeting || '',
      instruction: dto.instruction || '',
      model_profile_id: dto.model_profile_id || null,
      stt_profile_id: dto.stt_profile_id || null,
      tts_profile_id: dto.tts_profile_id || null,
      vad_config: dto.vad_config || {},
      toolset_id: dto.toolset_id || null,
      channel_kind: dto.channel_kind || 'local',
      enabled: dto.enabled !== false,
      user_uid: userUid,
    });
  }

  async update(id: number, dto: UpdateAiAgentDto, userUid: number) {
    const row = await this.findOne(id, userUid);
    await this.validateLinkedEntities(dto, userUid);
    if (dto.unique_id && dto.unique_id !== row.unique_id) {
      await this.assertUniqueId(dto.unique_id, userUid, id);
    }
    const merged = { ...row.get(), ...dto } as any;
    this.assertModeConsistency(merged);
    await row.update(dto);
    return row;
  }

  async remove(id: number, userUid: number) {
    const row = await this.findOne(id, userUid);
    await row.destroy();
    return { success: true };
  }

  // тФАтФАтФА Validation helpers тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  private async assertUniqueId(unique_id: string, userUid: number, excludeId: number | null) {
    if (!/^[A-Za-z0-9_\-]+$/.test(unique_id)) {
      throw new BadRequestException('unique_id may only contain [A-Za-z0-9_-]');
    }
    const where: any = { unique_id, user_uid: userUid };
    if (excludeId) where.uid = { [Op.ne]: excludeId };
    const dup = await this.agentModel.findOne({ where });
    if (dup) throw new BadRequestException(`unique_id "${unique_id}" is already used`);
  }

  private assertModeConsistency(a: {
    mode?: 'realtime' | 'cascade';
    model_profile_id?: number | null;
    stt_profile_id?: number | null;
    tts_profile_id?: number | null;
  }) {
    if (a.mode === 'cascade') {
      if (!a.stt_profile_id) throw new BadRequestException('cascade mode requires STT profile');
      if (!a.tts_profile_id) throw new BadRequestException('cascade mode requires TTS profile');
    }
    if (!a.model_profile_id) {
      throw new BadRequestException('LLM/model profile is required');
    }
  }

  private async validateLinkedEntities(
    dto: { model_profile_id?: number; stt_profile_id?: number; tts_profile_id?: number; toolset_id?: number },
    userUid: number,
  ) {
    const providerIds = [dto.model_profile_id, dto.stt_profile_id, dto.tts_profile_id].filter(
      (v): v is number => typeof v === 'number' && v > 0,
    );
    if (providerIds.length > 0) {
      const found = await this.providerModel.findAll({
        where: { uid: { [Op.in]: providerIds }, user_uid: { [Op.in]: [0, userUid] } },
      });
      if (found.length !== new Set(providerIds).size) {
        throw new BadRequestException('Linked provider not accessible for this tenant');
      }
    }
    if (dto.toolset_id) {
      const ts = await this.toolsetModel.findOne({
        where: { uid: dto.toolset_id, user_uid: userUid },
      });
      if (!ts) throw new BadRequestException('Linked toolset not accessible for this tenant');
    }
  }
}

import {
  IsString, IsOptional, IsEnum, IsNumber, IsBoolean, IsObject,
  MaxLength, IsInt, Min,
} from 'class-validator';

export class CreateAiAgentDto {
  @IsString()
  @MaxLength(128)
  name: string;

  @IsString()
  @MaxLength(64)
  unique_id: string;

  @IsEnum(['realtime', 'cascade'])
  mode: 'realtime' | 'cascade';

  @IsOptional()
  @IsString()
  @MaxLength(64)
  voice?: string;

  @IsOptional()
  @IsString()
  greeting?: string;

  @IsOptional()
  @IsString()
  instruction?: string;

  @IsOptional()
  @IsInt()
  @Min(0)
  model_profile_id?: number;

  @IsOptional()
  @IsInt()
  @Min(0)
  stt_profile_id?: number;

  @IsOptional()
  @IsInt()
  @Min(0)
  tts_profile_id?: number;

  @IsOptional()
  @IsObject()
  vad_config?: Record<string, any>;

  @IsOptional()
  @IsInt()
  @Min(0)
  toolset_id?: number;

  @IsOptional()
  @IsEnum(['local', 'pjsip'])
  channel_kind?: 'local' | 'pjsip';

  @IsOptional()
  @IsBoolean()
  enabled?: boolean;
}

export class UpdateAiAgentDto {
  @IsOptional()
  @IsString()
  @MaxLength(128)
  name?: string;

  @IsOptional()
  @IsString()
  @MaxLength(64)
  unique_id?: string;

  @IsOptional()
  @IsEnum(['realtime', 'cascade'])
  mode?: 'realtime' | 'cascade';

  @IsOptional()
  @IsString()
  @MaxLength(64)
  voice?: string;

  @IsOptional()
  @IsString()
  greeting?: string;

  @IsOptional()
  @IsString()
  instruction?: string;

  @IsOptional()
  @IsInt()
  model_profile_id?: number;

  @IsOptional()
  @IsInt()
  stt_profile_id?: number;

  @IsOptional()
  @IsInt()
  tts_profile_id?: number;

  @IsOptional()
  @IsObject()
  vad_config?: Record<string, any>;

  @IsOptional()
  @IsInt()
  toolset_id?: number;

  @IsOptional()
  @IsEnum(['local', 'pjsip'])
  channel_kind?: 'local' | 'pjsip';

  @IsOptional()
  @IsBoolean()
  enabled?: boolean;
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import {
  looksLikeUserConfirm,
  scrubToolIdsFromPublicText,
  type AgentItemVisibility,
  type AgentTimelineStepItem,
  type AgentTurnCloseKind,
} from '@krasterisk/shared';
import { wrapUntrustedData } from '../../shared/utils/prompt-injection.util';
import { AiProvidersService } from '../ai-agents/ai-providers.service';
import { McpToolsService } from '../mcp/mcp-tools.service';
import { PbxAgentLlmClient } from './pbx-agent-llm.client';
import { PbxContextBuilderService } from './pbx-context-builder.service';
import { PbxAgentThreadService } from './pbx-agent-thread.service';
import { PbxConversationBriefService } from './pbx-conversation-brief.service';
import { AgentIntentClassifierService } from './agent-intent-classifier.service';
import { AgentSkillRegistryService } from '../ai-platform/agent-skill-registry.service';
import { renderBriefForPrompt } from './conversation-brief.types';
import { AiChatSettingsService } from './ai-chat-settings.service';
import { humanStepDetail, isToolErrorContent, progressLabelKey } from './agent-timeline.util';
import type { AgentSseEventName, AgentToolCall, AgentToolSpec, ChatMessage } from './pbx-agent.types';
import {
  classifyTurnClose,
  forcedTurnStatus,
  incompleteReminder,
  looksLikeMultiEntitySetup,
  looksLikeRouteSetup,
  looksLikePlanningNarration,
  looksTruncated,
} from './turn-outcome.util';
import { isWorkflowPlanView } from './dto/agent-diff.dto';
import { PbxWorkflowRunnerService } from './pbx-workflow-runner.service';
import { buildIvrSetupDraft } from './ivr-setup-draft';

export const DEFAULT_MAX_AGENT_STEPS = 12;
export const DEFAULT_TOOL_ARG_RETRIES = 1;
export const TOOL_RESULT_MAX_CHARS = 4000;
export const ASSISTANT_OUTPUT_BUDGET_CHARS = 8000;
const PLAN_CHECKLIST_TOOLS = new Set([
  'list_tts_engines',
  'list_endpoints',
  'list_call_groups',
  'list_ivrs',
  'list_dialplan_apps',
]);
export const PROMPT_TOTAL_BUDGET_CHARS = 48_000;

export const CONTINUE_AFTER_APPLY_PROMPT =
  '╨Ъ╨░╤А╤В╨╛╤З╨║╨░ ╤Г╨╢╨╡ ╨┐╤А╨╕╨╝╨╡╨╜╨╡╨╜╨░. ╨Э╨╡ ╤Б╨╛╨╖╨┤╨░╨▓╨░╨╣ ╤В╨╡ ╨╢╨╡ ╨░╨▒╨╛╨╜╨╡╨╜╤В╨╛╨▓, ╨│╤А╤Г╨┐╨┐╤Г ╨╕╨╗╨╕ ╨╝╨╡╨╜╤О ╤Б╨╜╨╛╨▓╨░. ' +
  '╨Ю╨┤╨╜╨╕╨╝-╨┤╨▓╤Г╨╝╤П ╨┐╤А╨╡╨┤╨╗╨╛╨╢╨╡╨╜╨╕╤П╨╝╨╕ ╤Б╨║╨░╨╢╨╕, ╤З╤В╨╛ ╨│╨╛╤В╨╛╨▓╨╛: ╨┐╤Г╨▒╨╗╨╕╤З╨╜╤Л╨╡ ╨╕╨╝╨╡╨╜╨░ ╨╕ ╨╜╨╛╨╝╨╡╤А╨░. ' +
  '╨Э╨╡ ╨╜╨░╨╖╤Л╨▓╨░╨╣ ╨╕╨╜╤Б╤В╤А╤Г╨╝╨╡╨╜╤В╤Л. ╨Э╨╡ ╨┐╤А╨╡╨┤╨╗╨░╨│╨░╨╣ ┬л╨┐╤А╨╛╨▓╨╡╤А╨╕╤В╤М ╤З╨╡╤А╨╡╨╖┬╗ ╤З╤В╨╛-╨╗╨╕╨▒╨╛. ╨в╨░╨╣╨╝╨░╤Г╤В ╨╜╨░╨╖╤Л╨▓╨░╨╣ ╤В╨░╨╣╨╝╨░╤Г╤В╨╛╨╝, ╨╜╨╡ ┬л╤Ж╨╕╤Д╤А╨░ t┬╗.';

export interface AgentTurnContext {
  tenantUid: number;
  authorUid: number;
  role: number;
  locale?: string;
  signal?: AbortSignal;
  userVisibility?: AgentItemVisibility;
}

export interface AgentStreamEvent {
  name: AgentSseEventName;
  data: unknown;
}

type LoopChatMessage = ChatMessage & {
  tool_call_id?: string;
  name?: string;
  tool_calls?: unknown;
};

interface RegisteredTool {
  spec: AgentToolSpec;
  required: string[];
}

@Injectable()
export class PbxAgentLoopService {
  constructor(
    private readonly llm: PbxAgentLlmClient,
    private readonly providers: AiProvidersService,
    private readonly contextBuilder: PbxContextBuilderService,
    private readonly threads: PbxAgentThreadService,
    private readonly mcpTools: McpToolsService,
    private readonly config: ConfigService,
    private readonly chatSettings: AiChatSettingsService,
    private readonly briefService: PbxConversationBriefService,
    private readonly intentClassifier: AgentIntentClassifierService,
    private readonly skillRegistry: AgentSkillRegistryService,
    private readonly workflows: PbxWorkflowRunnerService,
  ) {}

  /**
   * One user message тЖТ in-process model/tool cycle (D-06).
   * Persist as you go so a dropped connection still leaves a readable thread (D-26).
   */
  async *runTurn(
    message: string,
    conversation: { uid: number },
    ctx: AgentTurnContext,
  ): AsyncGenerator<AgentStreamEvent> {
    const threadUid = conversation.uid;
    const { tenantUid, authorUid, role } = ctx;
    const maxSteps = this.readInt('CC_AI_MAX_AGENT_STEPS', DEFAULT_MAX_AGENT_STEPS);
    const argRetries = this.readInt('CC_AI_TOOL_ARG_RETRIES', DEFAULT_TOOL_ARG_RETRIES);
    const argFailures = new Map<string, number>();

    const userVisibility = ctx.userVisibility ?? 'public';
    const userRow = await this.threads.appendMessage(threadUid, tenantUid, authorUid, {
      role: 'user',
      content: message,
      visibility: userVisibility,
    });
    yield { name: 'thread', data: { uid: threadUid } };
    if (userVisibility !== 'internal') {
      yield {
        name: 'item',
        data: {
          kind: 'user',
          id: `m${userRow.uid}`,
          text: message,
          createdAt: this.createdAtIso(userRow.created_at),
        },
      };
    }

    const preferredUid = await this.chatSettings.getDefaultProviderUid(tenantUid);
    const provider = await this.providers.findDefaultLlm(tenantUid, preferredUid);
    if (!provider) {
      yield { name: 'error', data: { code: 'missing_llm', message: 'No language-model provider is configured' } };
      return;
    }
    await this.threads.setProviderUid(threadUid, tenantUid, authorUid, provider.uid);

    const thread = await this.threads.getThread(threadUid, tenantUid, authorUid);
    const brief = this.briefService.compile(thread.brief_json, userRow.uid, message);
    await this.threads.saveBrief(threadUid, tenantUid, authorUid, brief);

    const classification = this.intentClassifier.classify({ message, brief });
    const selectedSkillBodies = this.skillRegistry.readSkillsForPrompt(classification.skillNames);

    const state = await this.contextBuilder.buildState(tenantUid);
    const systemPrompt = this.contextBuilder.buildSystemPrompt(state, {
      briefText: renderBriefForPrompt(brief),
      locale: ctx.locale,
      selectedSkillBodies,
    });
    const history = await this.threads.listMessagesForReplay(threadUid, tenantUid, authorUid);
    const messages: LoopChatMessage[] = [
      { role: 'system', content: systemPrompt },
      ...history
        .filter((row) => row.role !== 'system')
        .map((row) => this.toLoopMessage(row)),
    ];
    this.enforcePromptBudget(messages);

    const allTools = this.mcpTools.getToolsList(tenantUid);
    const allowedNames = new Set(
      this.intentClassifier.filterToolNames(
        allTools.map((tool) => tool.name),
        classification,
      ),
    );
    const registered = this.registerTools(allTools.filter((tool) => allowedNames.has(tool.name)));
    const tools = registered.map((tool) => tool.spec);
    let steps = 0;
    let incompleteContinues = 0;
    let forceToolChoice = false;
    let calledToolThisTurn = false;
    let checklistReads = 0;
    let proposePlanAttempts = 0;
    let providerTimeoutRetries = 0;
    let hadProposal = false;
    let mutationsThisTurn = 0;
    let lastAssistant = '';
    const providerModel =
      typeof (provider.defaults as Record<string, unknown> | null)?.model === 'string'
        ? String((provider.defaults as Record<string, unknown>).model)
        : provider.name;

    const proposalCtx = {
      vpbxUserUid: tenantUid,
      userUid: authorUid,
      role,
      threadUid,
    };
    const pendingWorkflow = await this.workflows.findLatestPendingForThread(threadUid, proposalCtx);

    if (looksLikeUserConfirm(message) && pendingWorkflow) {
      try {
        const applied = await this.workflows.apply(pendingWorkflow.workflowId, proposalCtx);
        const closing = applied.status === 'applied'
          ? '╨Я╨╗╨░╨╜ ╨┐╤А╨╕╨╝╨╡╨╜╤С╨╜. ╨б╤Г╤Й╨╜╨╛╤Б╤В╨╕ ╨╕╨╖ ╨║╨░╤А╤В╨╛╤З╨║╨╕ ╤Б╨╛╨╖╨┤╨░╨╜╤Л.'
          : applied.error
            ? `╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨┐╤А╨╕╨╝╨╡╨╜╨╕╤В╤М ╨┐╨╗╨░╨╜: ${scrubToolIdsFromPublicText(applied.error)}`
            : '╨Ъ╨░╤А╤В╨╛╤З╨║╨░ ╨╜╨╡ ╨┐╤А╨╕╨╝╨╡╨╜╨╡╨╜╨░.';
        const closeKind: AgentTurnCloseKind = applied.status === 'applied' ? 'complete' : 'question';
        const row = await this.threads.appendMessage(threadUid, tenantUid, authorUid, {
          role: 'assistant',
          content: closing,
          close_kind: closeKind,
          visibility: 'public',
        });
        yield {
          name: 'item',
          data: {
            kind: 'assistant',
            id: `m${row.uid}`,
            text: closing,
            closeKind,
            createdAt: this.createdAtIso(row.created_at),
          },
        };
        yield { name: 'done', data: { closeKind } };
        return;
      } catch (err) {
        const reason = err instanceof Error ? err.message : String(err);
        messages.push({
          role: 'system',
          content: `╨Я╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╤М ╨┐╨╛╨┤╤В╨▓╨╡╤А╨┤╨╕╨╗, ╨╜╨╛ ╨┐╤А╨╕╨╝╨╡╨╜╨╕╤В╤М ╨║╨░╤А╤В╨╛╤З╨║╤Г ╨╜╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М (${reason}). ╨Ю╨▒╨╜╨╛╨▓╨╕ ╨┐╨╗╨░╨╜ ╤З╨╡╤А╨╡╨╖ propose_plan ╨╕╨╗╨╕ ╤Б╨║╨░╨╢╨╕, ╤З╤В╨╛ ╤Б╨╗╨╛╨╝╨░╨╗╨╛╤Б╤М.`,
        });
        forceToolChoice = true;
      }
    } else if (looksLikeUserConfirm(message)) {
      messages.push({
        role: 'system',
        content:
          '╨Я╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╤М ╨┐╨╛╨┤╤В╨▓╨╡╤А╨┤╨╕╨╗. ╨Э╨╡ ╨▓╤Л╨╖╤Л╨▓╨░╨╣ create_call_group ╤Б╨╜╨╛╨▓╨░ ╨╕ ╨╜╨╡ ╨┐╨╡╤А╨╡╨┤╨░╨▓╨░╨╣ ╨┐╨╛╨╗╤П ╨╛╨┤╨╜╨╛╨│╨╛ ╤З╨╗╨╡╨╜╨░ (member_type/value) ╨║╨░╨║ ╨░╤А╨│╤Г╨╝╨╡╨╜╤В╤Л ╨│╤А╤Г╨┐╨┐╤Л. ' +
          '╨Х╤Б╨╗╨╕ ╨│╤А╤Г╨┐╨┐╨░ ╤В╨░╨╣╨╝╨░╤Г╤В╨░ ╤Г╨╢╨╡ ╨╡╤Б╤В╤М (╨╜╨░╨┐╤А╨╕╨╝╨╡╤А exten 9010), ╤Б╤А╨░╨╖╤Г ╨▓╤Л╨╖╨╛╨▓╨╕ create_ivr ╤Б ╨┐╨╛╨┤╤В╨▓╨╡╤А╨╢╨┤╤С╨╜╨╜╤Л╨╝╨╕ name/prompts/menu_items (t тЖТ kind group, target 9010). ' +
          '╨Ъ╨░╤А╤В╨╛╤З╨║╤Г ╨▓ UI ╨┐╨╛╨┤╤В╨▓╨╡╤А╨╢╨┤╨░╨╡╤В ╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╤М тАФ ╨╜╨╡ ╨┐╤А╨╕╨┤╤Г╨╝╤Л╨▓╨░╨╣ apply tool.',
      });
      forceToolChoice = true;
    } else {
      const compiled = yield* this.tryServerIvrPlan({
        message,
        threadUid,
        tenantUid,
        authorUid,
        role,
        locale: ctx.locale,
        providerModel,
      });
      if (compiled) return;
      if (pendingWorkflow) {
        messages.push({
          role: 'system',
          content:
