  /**
   * D-13: ownership folded into where (operator = own rows only; supervisor any tenant row).
   * Never a post-fetch ownership if тАФ NotFound when absent from filtered where.
   */
  async updateContact(
    id: number,
    dto: UpdateContactDto,
    userUid: number,
    userId: number,
    isSupervisor: boolean,
  ) {
    const where: Record<string, number> = { uid: id, user_uid: userUid };
    if (!isSupervisor) where.created_by = userId;
    const row = await this.contactModel.findOne({ where });
    if (!row) throw new NotFoundException('Contact not found');
    // Never trust client user_uid / created_by тАФ only whitelist fields from DTO.
    const patch: { name?: string; number?: string; note?: string | null } = {};
    if (dto.name !== undefined) patch.name = dto.name;
    if (dto.number !== undefined) patch.number = dto.number;
    if (dto.note !== undefined) patch.note = dto.note;
    return row.update(patch);
  }

  async deleteContact(
    id: number,
    userUid: number,
    userId: number,
    isSupervisor: boolean,
  ) {
    const where: Record<string, number> = { uid: id, user_uid: userUid };
    if (!isSupervisor) where.created_by = userId;
    const row = await this.contactModel.findOne({ where });
    if (!row) throw new NotFoundException('Contact not found');
    await row.destroy();
    return { success: true };
  }

  /**
   * SIP-mode in-call DTMF via AMI PlayDTMF (D-32).
   * Channel is resolved from the caller's own active call тАФ never client-supplied.
   * Digit must already be a single [0-9*#A-D] (DTO + defense-in-depth here).
   */
  async sendDtmf(userUid: number, userId: number, uniqueid: string, digit: string) {
    if (!/^[0-9*#A-D]$/.test(digit)) {
      throw new BadRequestException('Invalid DTMF digit');
    }

    userUid = this.resolveTenant(userUid, userId);
    const agentInterface = await this.resolveAgentInterface(userUid, userId);
    if (!agentInterface) throw new NotFoundException('Agent not logged in');

    const call = this.stateService.getCall(uniqueid);
    if (!call) throw new NotFoundException('Call not found');
    if (call.userUid !== userUid) {
      throw new BadRequestException('Call belongs to another tenant');
    }
    if (call.agent !== agentInterface) {
      throw new ForbiddenException("Only the operator's own call can receive DTMF");
    }

    const channel = call.agentChannel || call.callerChannel;
    if (!channel) {
      throw new BadRequestException('Call channel not available');
    }

    try {
      await this.amiService.playDtmf(channel, digit);
    } catch (err: any) {
      this.logger.warn(`PlayDTMF failed for ${channel} digit=${digit}: ${err?.message}`);
      throw new BadRequestException(`DTMF failed: ${err?.message}`);
    }

    return { success: true, uniqueid, digit };
  }

  /**
   * Operator's own endpoint online/offline for SIP softphone trigger (D-35).
   * Extension/mode re-derived server-side тАФ never trust client-supplied mode.
   *
   * Source of truth order:
   * 1. Live PJSIPShowEndpoint contact status (same as `pjsip show contacts` Avail)
   * 2. Presence cache from DeviceStateChange
   * 3. Live DeviceStateList seed when cache is empty
   *
   * DeviceState alone often stays UNAVAILABLE / never seeded without BLF hints,
   * while the handset contact is Reachable тАФ Recover must not stick on false.
   */
  async getMyRegistrationState(userUid: number, userId: number): Promise<{ online: boolean }> {
    userUid = this.resolveTenant(userUid, userId);
    const agentInterface = await this.resolveAgentInterface(userUid, userId);
    if (!agentInterface) {
      return { online: false };
    }

    const sipId = agentInterface.includes('/')
      ? agentInterface.slice(agentInterface.indexOf('/') + 1)
      : agentInterface;
    // WebRTC companion тЖТ look up primary SIP handset registration; else self.
    const endpointId = isWebrtcCompanion(sipId) ? (primaryIdOf(sipId) ?? sipId) : sipId;
    const extension = extractExtension(endpointId);

    try {
      const reachable = await this.amiService.isPjsipEndpointReachable(endpointId);
      if (reachable !== null) {
        this.presenceService.handleDeviceStateChange({
          device: `PJSIP/${endpointId}`,
          state: reachable ? 'NOT_INUSE' : 'UNAVAILABLE',
        });
        return { online: reachable };
      }
    } catch (err: any) {
      this.logger.warn(
        `getMyRegistrationState PJSIPShowEndpoint failed for ${endpointId}: ${err?.message || err}`,
      );
    }

    let state = this.presenceService.getPresence(userUid, extension);
    if (!state || /^(unavailable|invalid|unknown)$/i.test(String(state).trim())) {
      try {
        const { events } = await this.amiService.collectDeviceStateList();
        for (const evt of events) {
          this.presenceService.handleDeviceStateChange(evt);
        }
        state = this.presenceService.getPresence(userUid, extension);
      } catch (err: any) {
        this.logger.warn(`getMyRegistrationState DeviceStateList failed: ${err?.message || err}`);
      }
    }
    if (!state) {
      return { online: false };
    }
    // Offline DeviceState values; anything else (NOT_INUSE/INUSE/BUSY/RINGING/тАж) = online.
    const offline = /^(unavailable|invalid|unknown)$/i.test(String(state).trim());
    return { online: !offline };
  }

  /**
   * True when agent.name is a channel/extension placeholder, not a person name.
   * Mirrors CallCenterAmiService.isRawAgentName (Originate CID / QueueMember).
   */
  private isRawAgentDisplayName(iface: string, name?: string): boolean {
    if (!name) return true;
    if (name === iface) return true;
    if (/^(PJSIP|SIP)\//i.test(name)) return true;
    const ext = interfaceToExtension(iface);
    if (ext && name === ext) return true;
    if (/^e(w)?.+_\d+$/i.test(name)) return true;
    return false;
  }

  /**
   * Resolve AMI Redirect target for an agent interface.
   * Uses the endpoint's real dialplan context (tenant-suffixed, e.g. from-internal0)
   * and the numeric extension (ew112_0 тЖТ 112) тАФ never raw SIP id / bare from-internal.
   */
  private async resolveAgentRedirectTarget(
    userUid: number,
    agentInterface: string,
  ): Promise<{ exten: string; context: string }> {
    const exten = interfaceToExtension(agentInterface);
    const sipId = agentInterface.includes('/')
      ? agentInterface.slice(agentInterface.indexOf('/') + 1)
      : agentInterface;
    const primaryId = primaryIdOf(sipId) ?? sipId;

    try {
      const ep =
        (await this.endpointModel.findByPk(primaryId))
        ?? (await this.endpointModel.findByPk(sipId));
      const ctx =
        ep?.getDataValue?.('context')
        ?? (ep as { context?: string } | null)?.context;
      if (ctx && String(ctx).trim()) {
        return { exten, context: String(ctx).trim() };
      }
    } catch (err: any) {
      this.logger.warn(`resolveAgentRedirectTarget: endpoint lookup failed: ${err.message}`);
    }

    // Last resort: tenant-suffixed default (endpoints.service buildContext pattern)
    return { exten, context: `from-internal${userUid}` };
  }

  // тФАтФАтФА Pick Call тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА
  //
  // Pick Call: agent manually grabs a waiting caller from a queue.
  // AMI Redirect of the caller channel to the agent's dialplan extension
  // (endpoint context + numeric exten), bypassing queue strategy.

  async agentPickCall(uniqueid: string, userUid: number, userId: number) {
    userUid = this.resolveTenant(userUid, userId);
    const agentInterface = await this.resolveAgentInterface(userUid, userId);
    if (!agentInterface) throw new NotFoundException('Agent not logged in');

    const agent = this.stateService.getAgent(userUid, agentInterface);
    if (!agent) throw new NotFoundException('Agent state not found');
    if (agent.status !== 'READY') {
      throw new BadRequestException(`Agent must be READY to pick a call (current: ${agent.status})`);
    }

    const settings = await this.settingsService.getOperatorSettings(userUid, userId);
    if (!settings.pickup_enabled) {
      throw new ForbiddenException('Pickup not allowed for this operator');
    }

    const call = this.stateService.getCall(uniqueid);
    if (!call) throw new NotFoundException('Call not found');
    if (call.userUid !== userUid) {
      throw new BadRequestException('Call belongs to another tenant');
    }
    if (call.status !== 'WAITING' && call.status !== 'RINGING') {
      throw new BadRequestException(`Call is not pickable (status: ${call.status})`);
    }

    const callerChannel = call.callerChannel;
    if (!callerChannel) {
      throw new BadRequestException(
        'Caller channel not available yet тАФ try again in a moment',
      );
    }

    const { exten: agentExten, context } = await this.resolveAgentRedirectTarget(
      userUid,
      agentInterface,
    );

    try {
      await this.amiService.action({
        action: 'Redirect',
        channel: callerChannel,
        context,
        exten: agentExten,
        priority: '1',
      });
    } catch (err: any) {
      throw new BadRequestException(`Pick call failed: ${err.message}`);
    }

    this.logger.log(
      `Agent ${agentInterface} picked call ${uniqueid} from queue ${call.queue} тЖТ ${context},${agentExten}`,
    );

    return { success: true, uniqueid, target: agentExten, context };
  }

  // тФАтФАтФА Missed Calls тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  async logMissedCall(params: {
    uniqueid: string;
    queueName: string;
    callerIdNum: string;
    callerIdName?: string;
    holdTime?: number;
    position?: number;
    userUid: number;
  }): Promise<void> {
    try {
      const [, created] = await this.missedCallModel.findOrCreate({
        where: { call_uniqueid: params.uniqueid },
        defaults: {
          call_uniqueid: params.uniqueid,
          queue_name: params.queueName,
          caller_id_num: params.callerIdNum || '',
          caller_id_name: params.callerIdName || '',
          hold_time: params.holdTime || 0,
          position: params.position || 0,
          called_back: false,
          user_uid: params.userUid,
        },
      });
      if (!created) return;

      this.stateService.emitEvent('missedCallNew', params.userUid, {
        uniqueid: params.uniqueid,
        queue: params.queueName,
        callerIdNum: params.callerIdNum,
        holdTime: params.holdTime || 0,
      });
    } catch (err: any) {
      if (err?.name === 'SequelizeUniqueConstraintError') return;
      this.logger.warn(`Failed to log missed call: ${err.message}`);
    }
  }

  async getMissedCalls(userUid: number, includeHandled = false, userId?: number) {
    const tenant =
      userId != null
        ? (this.stateService.findTenantForOnlineUser(userId) ?? userUid)
        : userUid;
    const where: any = { user_uid: tenant };
    if (!includeHandled) where.called_back = false;
    const rows = await this.missedCallModel.findAll({
      where,
      order: [['created_at', 'DESC']],
      limit: 200,
    });
    // Defensive: collapse legacy duplicates that share the same Asterisk uniqueid
    const seen = new Set<string>();
    const unique = rows.filter((r) => {
      const id = r.call_uniqueid;
      if (!id || seen.has(id)) return false;
      seen.add(id);
      return true;
    });

    // Resolve operator display names for the resolved sub-view (called_back_by).
    const handlerIds = [
      ...new Set(
        unique
          .map((r) => r.called_back_by)
          .filter((id): id is number => id != null && id > 0),
      ),
    ];
    const nameById = new Map<number, string>();
    if (handlerIds.length > 0) {
      const users = await this.userModel.findAll({
        where: { uniqueid: { [Op.in]: handlerIds }, vpbx_user_uid: tenant },
        attributes: ['uniqueid', 'name', 'login'],
      });
      for (const u of users) {
        const id = u.getDataValue('uniqueid') as number;
        const label =
          (u.getDataValue('name') as string)
          || (u.getDataValue('login') as string)
          || `#${id}`;
        nameById.set(id, label);
      }
    }

    return unique.map((r) => {
      const json = r.toJSON() as Record<string, unknown>;
      const by = r.called_back_by;
      return {
        ...json,
        called_back_by_name:
          by != null && by > 0 ? (nameById.get(by) ?? `#${by}`) : null,
      };
    });
  }

  async markMissedCalled(id: number, note: string | undefined, userUid: number, userId: number) {
    const missed = await this.missedCallModel.findOne({
      where: { uid: id, user_uid: userUid },
    });
    if (!missed) throw new NotFoundException('Missed call not found');

    await missed.update({
      called_back: true,
      called_back_by: userId,
      called_back_at: new Date(),
      note: note || '',
    });

    this.stateService.emitEvent('missedCallUpdate', userUid, {
      id: missed.uid,
      called_back: true,
      called_back_by: userId,
    });

    return { success: true };
  }

  /**
   * Number-level worklist (D-16/D-19): groups the call-level cc_missed_calls
   * rows by caller_id_num + personal at the READ layer only тАФ the table
   * itself stays call-level (findOrCreate-by-uniqueid in persistMissedCall
   * keeps UNIQUE(call_uniqueid) intact, RESEARCH Pitfall 4). Excludes rows
   * already resolved (called_back) or self-resolved (client_called_back).
   */
  async getMissedCallsGrouped(userUid: number) {
    const rows = await this.missedCallModel.findAll({
      where: { user_uid: userUid, called_back: false, client_called_back: false },
      attributes: [
        'caller_id_num',
        'personal',
        [fn('COUNT', col('uid')), 'attemptCount'],
        [fn('MAX', col('created_at')), 'lastAttemptAt'],
        [fn('MAX', col('called_back_by')), 'claimedBy'],
        [fn('MAX', col('caller_id_name')), 'callerIdName'],
        // D-19 queue-name chip for queue-missed rows тАФ same MAX-aggregate
        // idiom as callerIdName/claimedBy above (09-10, Rule 2: the UI's
        // queue-missed chip has no data source without this).
        [fn('MAX', col('queue_name')), 'queueName'],
      ],
      group: ['caller_id_num', 'personal'],
      order: [[literal('lastAttemptAt'), 'DESC']],
      raw: true,
    });

    return (rows as any[]).map((r) => ({
      callerIdNum: r.caller_id_num,
      callerIdName: r.callerIdName || '',
      personal: !!r.personal,
      attemptCount: parseInt(r.attemptCount, 10) || 0,
      lastAttemptAt: r.lastAttemptAt,
      claimedBy: r.claimedBy ?? null,
      queueName: r.queueName || null,
    }));
  }

  /**
   * Claims a queue-missed (shared-pool) number group for the operator
   * (D-19). Personal misses are already owned by the agent whose channel
   * rang, so claim only ever targets personal=false rows. Idempotent тАФ
   * server is source of truth on conflict, last write wins (T-09-09-03).
   */
  async claimMissedCall(userUid: number, operatorUserId: number, callerIdNum: string) {
    if (!callerIdNum) throw new BadRequestException('callerIdNum is required');

    const [claimed] = await this.missedCallModel.update(
      { called_back_by: operatorUserId },
      {
        where: {
          user_uid: userUid,
          caller_id_num: callerIdNum,
          personal: false,
          called_back: false,
          client_called_back: false,
        },
      },
    );

    this.stateService.emitEvent('missedCallUpdate', userUid, {
      callerIdNum,
      claimedBy: operatorUserId,
    });

    return { success: true, claimed };
  }

  /**
   * D-17: when the client calls back on their own and the call connects,
   * tag every open (unresolved) missed row for that number as
   * client_called_back so it drops out of the active worklist.
   */
  async autoResolveOnAnswer(userUid: number, callerIdNum: string): Promise<void> {
    if (!callerIdNum) return;
    try {
      const [affected] = await this.missedCallModel.update(
        { client_called_back: true },
        {
          where: {
            user_uid: userUid,
            caller_id_num: callerIdNum,
            called_back: false,
            client_called_back: false,
          },
        },
      );
      if (affected > 0) {
        this.stateService.emitEvent('missedCallUpdate', userUid, {
          callerIdNum,
          clientCalledBack: true,
        });
      }
    } catch (err: any) {
      this.logger.warn(`autoResolveOnAnswer failed: ${err.message}`);
    }
  }

  /**
   * D-34/D-35: unified call history across all directions (queue inbound,
   * personal, outbound, internal) for a single operator, most-recent-first.
   * `period='shift'` looks back to the operator's current open login session
   * (falls back to start-of-day if none is open); `period='day'` always uses
   * start-of-day. Tenant-scoped by vpbx_user_uid (T-09-11-03).
   */
  async getOperatorCallHistory(userUid: number, operatorUserId: number, period: 'shift' | 'day' = 'day') {
    let since = this.startOfToday();

    if (period === 'shift') {
      const session = await this.sessionModel.findOne({
        where: { user_id: operatorUserId, user_uid: userUid, logout_time: null },
        order: [['login_time', 'DESC']],
      });
      const loginTime = session?.getDataValue('login_time') as Date | undefined;
      if (loginTime) since = loginTime;
    }

    const rows = await this.queueCallModel.findAll({
      where: {
        user_uid: userUid,
        agent_user_uid: operatorUserId,
        created_at: { [Op.gte]: since },
      },
      order: [['created_at', 'DESC']],
      limit: 200,
    });

    // Enrich missed rows with the operator who later handled the callback.
    const missedUniqueids = rows
      .filter((r) => {
        const d = r.getDataValue('disposition');
        return d === 'abandoned' || d === 'timeout';
      })
      .map((r) => r.getDataValue('call_uniqueid') as string)
      .filter(Boolean);

    const handledBy = new Map<string, { name: string; exten: string | null }>();
    if (missedUniqueids.length > 0) {
      const missed = await this.missedCallModel.findAll({
        where: {
          user_uid: userUid,
          call_uniqueid: { [Op.in]: missedUniqueids },
          called_back: true,
          called_back_by: { [Op.ne]: null },
        },
        attributes: ['call_uniqueid', 'called_back_by'],
      });
      const handlerIds = [
        ...new Set(
          missed
            .map((m) => m.called_back_by)
            .filter((id): id is number => id != null && id > 0),
        ),
      ];
      const nameById = new Map<number, { name: string; exten: string | null }>();
      if (handlerIds.length > 0) {
        const users = await this.userModel.findAll({
          where: { uniqueid: { [Op.in]: handlerIds }, vpbx_user_uid: userUid },
          attributes: ['uniqueid', 'name', 'login', 'exten'],
        });
        for (const u of users) {
          const id = u.getDataValue('uniqueid') as number;
          const name =
            (u.getDataValue('name') as string)
            || (u.getDataValue('login') as string)
            || `#${id}`;
          const exten = (u.getDataValue('exten') as string) || null;
          nameById.set(id, { name, exten });
        }
      }
      for (const m of missed) {
        const by = m.called_back_by;
        if (by == null || by <= 0) continue;
        const info = nameById.get(by) ?? { name: `#${by}`, exten: null };
        handledBy.set(m.call_uniqueid, info);
      }
    }

    return rows.map((r) => {
      const uniqueid = r.getDataValue('call_uniqueid') as string;
      const handler = handledBy.get(uniqueid);
      return {
        uid: r.getDataValue('uid'),
        callUniqueid: uniqueid,
        queueName: r.getDataValue('queue_name'),
        callerIdNum: r.getDataValue('caller_id_num'),
        callerIdName: r.getDataValue('caller_id_name'),
        direction: r.getDataValue('direction'),
        callType: r.getDataValue('call_type'),
        disposition: r.getDataValue('disposition'),
        transferDestination: (r.getDataValue('transfer_destination') as string) || null,
        handledByName: handler?.name ?? null,
        handledByExten: handler?.exten ?? null,
        enterTime: r.getDataValue('enter_time'),
        answerTime: r.getDataValue('answer_time'),
        endTime: r.getDataValue('end_time'),
        waitTime: r.getDataValue('wait_time'),
        talkTime: r.getDataValue('talk_time'),
      };
    });
  }

  // тФАтФАтФА Supervisor access scope / watchlist / multi-agent history тФАтФА

  async getSupervisorAccessScope(userUid: number, supervisorUserId: number) {
    const scope = await this.accessListService.resolveScope(userUid, supervisorUserId);
    const candidates = await this.accessListService.listCandidateOperators(userUid, scope);
    return {
      ...this.accessListService.serializeScope(scope),
      candidates,
    };
  }

  async getWatchedAgents(userUid: number, supervisorUserId: number): Promise<{ userIds: number[] }> {
    const row = await this.operatorSettingsModel.findOne({
      where: { user_uid: userUid, operator_user_id: supervisorUserId },
      attributes: ['supervised_agent_extens'],
    });
    const raw = row?.getDataValue('supervised_agent_extens');
    const userIds = await this.accessListService.mapWatchlistToUserIds(userUid, raw);
    return { userIds };
  }

  async setWatchedAgents(
    userUid: number,
    supervisorUserId: number,
    userIdsIn: number[],
    legacyExtens?: string[],
  ): Promise<{ userIds: number[] }> {
    const scope = await this.accessListService.resolveScope(userUid, supervisorUserId);
    let userIds = [...new Set((userIdsIn || []).map((id) => Number(id)).filter((id) => id > 0))];
    if (userIds.length === 0 && legacyExtens?.length) {
      userIds = await this.accessListService.mapWatchlistToUserIds(userUid, legacyExtens);
    }

    for (const id of userIds) {
      if (!this.accessListService.isOperatorUserAllowed(scope, id)) {
        throw new ForbiddenException(`Operator ${id} is outside supervisor access list`);
      }
    }

    const existing = await this.operatorSettingsModel.findOne({
      where: { user_uid: userUid, operator_user_id: supervisorUserId },
    });
    if (existing) {
      await existing.update({
        supervised_agent_extens: userIds.map(String),
        updated_at: new Date(),
      });
    } else {
      await this.operatorSettingsModel.create({
        ...DEFAULT_OPERATOR_SETTINGS,
        user_uid: userUid,
        operator_user_id: supervisorUserId,
        supervised_agent_extens: userIds.map(String),
        updated_at: new Date(),
      });
    }

    return { userIds };
  }

  /**
   * Call history for all watched agents (same row shape as getOperatorCallHistory).
   */
  async getSupervisorCallHistory(
    userUid: number,
    supervisorUserId: number,
    period: 'shift' | 'day' = 'day',
  ) {
    const { userIds } = await this.getWatchedAgents(userUid, supervisorUserId);
    if (userIds.length === 0) return [];

    const operatorIds = [...userIds];

    const since = this.startOfToday();
    // period=shift for supervisor aggregates to day (no single shared shift).
    void period;

    const rows = await this.queueCallModel.findAll({
      where: {
        user_uid: userUid,
        agent_user_uid: { [Op.in]: operatorIds },
        created_at: { [Op.gte]: since },
      },
      order: [['created_at', 'DESC']],
      limit: 500,
    });

    const missedUniqueids = rows
      .filter((r) => {
        const d = r.getDataValue('disposition');
        return d === 'abandoned' || d === 'timeout';
      })
      .map((r) => r.getDataValue('call_uniqueid') as string)
      .filter(Boolean);

    const handledBy = new Map<string, { name: string; exten: string | null }>();
    if (missedUniqueids.length > 0) {
      const missed = await this.missedCallModel.findAll({
        where: {
          user_uid: userUid,
          call_uniqueid: { [Op.in]: missedUniqueids },
          called_back: true,
          called_back_by: { [Op.ne]: null },
        },
        attributes: ['call_uniqueid', 'called_back_by'],
      });
      const handlerIds = [
        ...new Set(
          missed
            .map((m) => m.called_back_by)
            .filter((id): id is number => id != null && id > 0),
        ),
      ];
      const nameById = new Map<number, { name: string; exten: string | null }>();
      if (handlerIds.length > 0) {
        const handlerUsers = await this.userModel.findAll({
          where: { uniqueid: { [Op.in]: handlerIds }, vpbx_user_uid: userUid },
          attributes: ['uniqueid', 'name', 'login', 'exten'],
        });
        for (const u of handlerUsers) {
          const id = u.getDataValue('uniqueid') as number;
          const name =
            (u.getDataValue('name') as string)
            || (u.getDataValue('login') as string)
            || `#${id}`;
          const exten = (u.getDataValue('exten') as string) || null;
          nameById.set(id, { name, exten });
        }
      }
      for (const m of missed) {
        const by = m.called_back_by;
        if (by == null || by <= 0) continue;
        const info = nameById.get(by) ?? { name: `#${by}`, exten: null };
        handledBy.set(m.call_uniqueid, info);
      }
    }

    return rows.map((r) => {
      const uniqueid = r.getDataValue('call_uniqueid') as string;
      const handler = handledBy.get(uniqueid);
      return {
        uid: r.getDataValue('uid'),
        callUniqueid: uniqueid,
        queueName: r.getDataValue('queue_name'),
        callerIdNum: r.getDataValue('caller_id_num'),
        callerIdName: r.getDataValue('caller_id_name'),
        direction: r.getDataValue('direction'),
        callType: r.getDataValue('call_type'),
        disposition: r.getDataValue('disposition'),
        transferDestination: (r.getDataValue('transfer_destination') as string) || null,
        handledByName: handler?.name ?? null,
        handledByExten: handler?.exten ?? null,
        enterTime: r.getDataValue('enter_time'),
        answerTime: r.getDataValue('answer_time'),
        endTime: r.getDataValue('end_time'),
        waitTime: r.getDataValue('wait_time'),
        talkTime: r.getDataValue('talk_time'),
        agentUserId: r.getDataValue('agent_user_uid'),
      };
    });
  }

  private startOfToday(): Date {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }

  // тФАтФАтФА Client Card (lookup by callerIdNum) тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Look up a caller and pull the latest service-requests for that number.
   * Directory contacts replace the removed phonebook sidebar in a later task.
   */
  async lookupClient(rawNumber: string, userUid: number) {
    const digits = (rawNumber || '').replace(/\D/g, '');
    if (digits.length < 4) {
      return { number: rawNumber, matched: false, contacts: [], requests: [] };
    }
    const suffix = digits.slice(-10);

    const contacts: Array<{
      directory_uid: number;
      directory_name: string;
      number: string;
      comment: string;
      values: Record<string, string> | null;
    }> = [];

    // Recent service requests for this number
    const requests = await this.serviceRequestModel.findAll({
      where: {
        user_uid: userUid,
        phone: { [Op.like]: `%${suffix.slice(-7)}%` },
      },
      order: [['created_at', 'DESC']],
      limit: 10,
      attributes: [
        'uid', 'request_number', 'counterparty_name', 'phone',
        'topic', 'comment', 'address', 'request_status',
        'scheduled_date', 'created_at',
      ],
    });

    return {
      number: rawNumber,
      matched: contacts.length > 0 || requests.length > 0,
      contacts,
      requests: requests
        .map(r => r.get({ plain: true }))
        .filter((r: any) => (r.phone || '').replace(/\D/g, '').endsWith(suffix)),
    };
  }

  // тФАтФАтФА Transfer Directory (D-36) тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Unified transfer directory (D-36): internal endpoints (with extension +
   * live presence from the Task-2 CallCenterPresenceService, falling back to
   * CC agent status when the endpoint is a logged-in agent), queues (free
   * count reused from the existing CC-state aggregation тАФ recalcQueueStats'
   * agents.available), and call groups (free count derived by matching each
   * member extension against the live CC agent map). Tenant-scoped by
   * vpbx_user_uid throughout (T-09-11-01).
   */
  async getTransferDirectory(userUid: number, search?: string) {
    const agents = this.stateService.getAllAgents(userUid);
    const agentByExtension = new Map<string, (typeof agents)[number]>();
    for (const agent of agents) {
      agentByExtension.set(interfaceToExtension(agent.interface), agent);
    }

    const endpointRows = await this.endpointModel.findAll({
      where: { tenantid: String(userUid) },
      attributes: ['id', 'department'],
    });
    const endpoints = endpointRows
      .filter((ep) => !isWebrtcCompanion(ep.id))
      .map((ep) => {
        const extension = extractExtension(ep.id);
        const agent = agentByExtension.get(extension);
        return {
          type: 'endpoint' as const,
          id: ep.id,
          extension,
          label: ep.department || extension,
          presence: this.presenceService.getPresence(userUid, extension) || agent?.status || 'OFFLINE',
        };
      });

    const queueRows = await this.queueModel.findAll({
      where: { user_uid: userUid },
      attributes: ['name', 'display_name'],
    });
    const queues = queueRows.map((q) => {
      const name = q.getDataValue('name') as string;
      const liveQueue = this.stateService.getQueue(userUid, name);
      return {
        type: 'queue' as const,
        id: name,
        label: (q.getDataValue('display_name') as string) || name,
        freeOperators: liveQueue?.agents.available ?? 0,
        totalOperators: liveQueue?.agents.total ?? 0,
      };
    });

    const groupRows = await this.callGroupModel.findAll({
      where: { user_uid: userUid },
      attributes: ['uid', 'name'],
    });
    const groupIds = groupRows.map((g) => g.getDataValue('uid') as number);
    const members = groupIds.length
      ? await this.callGroupMemberModel.findAll({
          where: { call_group_uid: { [Op.in]: groupIds }, member_type: 'internal' },
          attributes: ['call_group_uid', 'value'],
        })
      : [];
    const membersByGroup = new Map<number, string[]>();
    for (const m of members) {
      const groupUid = m.getDataValue('call_group_uid') as number;
      const list = membersByGroup.get(groupUid) || [];
      list.push(m.getDataValue('value') as string);
      membersByGroup.set(groupUid, list);
    }

    const groups = groupRows.map((g) => {
      const uid = g.getDataValue('uid') as number;
      const extensions = membersByGroup.get(uid) || [];
      const freeOperators = extensions.filter((ext) => agentByExtension.get(ext)?.status === 'READY').length;
      return {
        type: 'group' as const,
        id: String(uid),
        label: g.getDataValue('name') as string,
        freeOperators,
        totalOperators: extensions.length,
      };
    });

    if (!search) return { endpoints, queues, groups };

    const term = search.toLowerCase();
    return {
      endpoints: endpoints.filter(
        (e) => e.extension.toLowerCase().includes(term) || e.label.toLowerCase().includes(term),
      ),
      queues: queues.filter((q) => q.id.toLowerCase().includes(term) || q.label.toLowerCase().includes(term)),
      groups: groups.filter((g) => g.label.toLowerCase().includes(term)),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { CallCenterReportsService } from './callcenter-reports.service';
import type { CcReportId } from './callcenter-reports.types';
import { buildReportCsv } from './exporters/csv-exporter';
import { buildReportXlsx } from './exporters/xlsx-exporter';
import { NotificationsService } from '../../notifications/notifications.service';
import { NotificationDispatcherService } from '../../notifications/notification-dispatcher.service';
import {
  trimNotificationMessage,
} from '../../notifications/providers/notification-provider.interface';
import { MailerService } from '../../mailer/mailer.service';
import { CcReportSchedule } from '../models/report-schedule.model';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export type PeriodPreset =
  | 'today'
  | 'yesterday'
  | 'last-7-days'
  | 'last-30-days'
  | 'previous-month';

/**
 * Generate a tenant-scoped CC report and deliver via notification_integration (D-35).
 * Email тЖТ file attachment (csv/xlsx). Messenger тЖТ text summary only (no file in v1).
 */
@Injectable()
export class CallCenterReportDeliveryService {
  private readonly logger = new Logger(CallCenterReportDeliveryService.name);

  constructor(
    private readonly reportsService: CallCenterReportsService,
    private readonly notificationsService: NotificationsService,
    private readonly dispatcherService: NotificationDispatcherService,
    private readonly mailerService: MailerService,
  ) {}

  /**
   * Resolve a sliding period window relative to now (bounded presets, T-07-15-03).
   * Public for unit tests.
   */
  resolvePeriod(preset: PeriodPreset, now = new Date()): { dateFrom: string; dateTo: string } {
    const startOfDay = (d: Date) => {
      const x = new Date(d);
      x.setHours(0, 0, 0, 0);
      return x;
    };
    const endOfDay = (d: Date) => {
      const x = new Date(d);
      x.setHours(23, 59, 59, 999);
      return x;
    };
    const toIso = (d: Date) => d.toISOString();

    switch (preset) {
      case 'today': {
        return { dateFrom: toIso(startOfDay(now)), dateTo: toIso(endOfDay(now)) };
      }
      case 'yesterday': {
        const y = new Date(now);
        y.setDate(y.getDate() - 1);
        return { dateFrom: toIso(startOfDay(y)), dateTo: toIso(endOfDay(y)) };
      }
      case 'last-7-days': {
        const from = startOfDay(now);
        from.setDate(from.getDate() - 6);
        return { dateFrom: toIso(from), dateTo: toIso(endOfDay(now)) };
      }
      case 'last-30-days': {
        const from = startOfDay(now);
        from.setDate(from.getDate() - 29);
        return { dateFrom: toIso(from), dateTo: toIso(endOfDay(now)) };
      }
      case 'previous-month': {
        const firstThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const lastPrev = new Date(firstThisMonth);
        lastPrev.setDate(0);
        const firstPrev = new Date(lastPrev.getFullYear(), lastPrev.getMonth(), 1);
        return { dateFrom: toIso(startOfDay(firstPrev)), dateTo: toIso(endOfDay(lastPrev)) };
      }
      default: {
        const y = new Date(now);
        y.setDate(y.getDate() - 1);
        return { dateFrom: toIso(startOfDay(y)), dateTo: toIso(endOfDay(y)) };
      }
    }
  }

  async deliverSchedule(
    schedule: CcReportSchedule,
  ): Promise<{ success: boolean; error?: string }> {
    try {
      // Delivery target authz (T-07-15-02): findByUidInternal has no tenant filter
      const integ = await this.notificationsService.findByUidInternal(
        schedule.integration_uid,
      );
      if (integ.user_uid !== schedule.user_uid) {
        this.logger.warn(
          `integration_tenant_mismatch schedule=${schedule.uid} integ=${schedule.integration_uid}`,
        );
        return { success: false, error: 'integration_tenant_mismatch' };
      }

      const resolvedPeriod = this.resolvePeriod(
        schedule.period_preset as PeriodPreset,
      );
      const filters = schedule.filters ?? {};
      const dto = {
        ...resolvedPeriod,
        queueName: filters.queueName,
        agentInterface: filters.agentInterface,
      };

      // runReport(reportId, vpbxUserUid, query) тАФ tenant-scoped via schedule.user_uid
      const result = await this.reportsService.runReport(
        schedule.report_id,
        schedule.user_uid,
        dto,
      );

      const periodLabel = `${resolvedPeriod.dateFrom.slice(0, 10)}тАж${resolvedPeriod.dateTo.slice(0, 10)}`;
      const vars: Record<string, string> = {
        report: schedule.report_id,
        period: periodLabel,
      };
      const subject = this.applyTemplate(
        schedule.subject_template || `CC report: {{report}} ({{period}})`,
        vars,
      );
      const text = this.applyTemplate(
        schedule.message_template ||
          `Call center report ┬л{{report}}┬╗ for {{period}}.`,
        vars,
      );

      if (integ.channel === 'email') {
        const to = (schedule.target || (integ.config as { to?: string } | null)?.to || '').trim();
        if (!to) {
          return { success: false, error: 'missing_target' };
        }
        if (!EMAIL_RE.test(to)) {
          return { success: false, error: 'invalid_email_target' };
        }

        const dateStamp = resolvedPeriod.dateTo.slice(0, 10);
        if (schedule.format === 'xlsx') {
          const content = await buildReportXlsx(
            schedule.report_id,
            result.columns,
            result.rows,
          );
          const mailRes = await this.mailerService.sendReportMail({
            to,
            subject,
            text,
            attachment: {
              filename: `cc_${schedule.report_id}_${dateStamp}.xlsx`,
              content,
              contentType:
                'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            },
          });
          return mailRes.success
            ? { success: true }
            : { success: false, error: 'mail_send_failed' };
        }

        const csv = buildReportCsv(result.columns, result.rows);
        const mailRes = await this.mailerService.sendReportMail({
          to,
          subject,
          text,
          attachment: {
            filename: `cc_${schedule.report_id}_${dateStamp}.csv`,
            content: csv,
            contentType: 'text/csv; charset=utf-8',
          },
        });
        return mailRes.success
          ? { success: true }
          : { success: false, error: 'mail_send_failed' };
      }

      // Messenger channels: text summary only (no file attachment in v1)
      const summary = trimNotificationMessage(
        [
          `CC report: ${schedule.report_id}`,
          `Period: ${periodLabel}`,
          `Rows: ${result.rows?.length ?? 0}`,
          result.rows?.[0]
            ? `Sample: ${JSON.stringify(result.rows[0]).slice(0, 200)}`
            : '',
        ]
          .filter(Boolean)
          .join('\n'),
      );
      await this.dispatcherService.dispatch({
        integration_uid: schedule.integration_uid,
        message: summary,
        target: schedule.target ?? undefined,
      });
      return { success: true };
    } catch (e) {
      const msg = (e as Error)?.message ?? String(e);
      this.logger.error(`deliverSchedule failed schedule=${schedule.uid}: ${msg}`);
      return { success: false, error: msg.slice(0, 512) };
    }
  }

  private applyTemplate(template: string, vars: Record<string, string>): string {
    return template.replace(/\{\{(\w+)\}\}/g, (_, key: string) =>
      vars[key] !== undefined ? vars[key] : '',
    );
  }
}

