@Injectable()
export class ContextsService {
  constructor(
    @InjectModel(Context) private contextModel: typeof Context,
    @Inject(forwardRef(() => AmiService)) private amiService: AmiService,
  ) {}

  private buildContextName(contextName: string, vpbxUserUid: number): string {
    const suffix = String(vpbxUserUid);
    return contextName.endsWith(suffix) ? contextName : `${contextName}${suffix}`;
  }

  async findAll(vpbxUserUid: number): Promise<Context[]> {
    return this.contextModel.findAll({
      where: { user_uid: vpbxUserUid },
      order: [['name', 'ASC']],
    });
  }

  async findOne(uid: number, vpbxUserUid: number): Promise<Context> {
    const context = await this.contextModel.findOne({
      where: { uid, user_uid: vpbxUserUid },
    });
    if (!context) throw new NotFoundException('Context not found');
    return context;
  }

  async create(data: Partial<Context>, vpbxUserUid: number): Promise<Context> {
    const ctx = await this.contextModel.create({
      ...data,
      user_uid: vpbxUserUid,
    } as any);
    return ctx;
  }

  async update(uid: number, data: Partial<Context>, vpbxUserUid: number): Promise<Context> {
    const context = await this.findOne(uid, vpbxUserUid);
    const oldName = context.name;
    await context.update(data);
    return context;
  }

  async remove(uid: number, vpbxUserUid: number): Promise<void> {
    const context = await this.findOne(uid, vpbxUserUid);
    await context.destroy();
  }

  /**
   * Ensure default contexts exist for a tenant.
   * Called when a new tenant subscribes or on first endpoint creation.
   */
  async ensureDefaults(vpbxUserUid: number): Promise<void> {
    const existing = await this.contextModel.count({ where: { user_uid: vpbxUserUid } });
    if (existing > 0) return;

    const defaults = [
      { name: `ctx-${vpbxUserUid}`, comment: '╨Т╨╜╤Г╤В╤А╨╡╨╜╨╜╨╕╨╣ ╨║╨╛╨╜╤В╨╡╨║╤Б╤В' },
      { name: `ctx-${vpbxUserUid}-ext`, comment: '╨Т╨╜╨╡╤И╨╜╨╕╨╣ ╨║╨╛╨╜╤В╨╡╨║╤Б╤В' },
    ];

    await this.contextModel.bulkCreate(
      defaults.map((d) => ({ ...d, user_uid: vpbxUserUid })) as any[],
      { ignoreDuplicates: true },
    );
  }
  async bulkRemove(uids: number[], vpbxUserUid: number): Promise<{ deleted: number }> {
    const deleted = await this.contextModel.destroy({
      where: {
        uid: uids,
        user_uid: vpbxUserUid,
      },
    });
    return { deleted };
  }
}

import {
  Controller, Get, Query, HttpCode, Logger, UnauthorizedException,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { timingSafeApiKeyEqual } from '../dialplan-bridge/dialplan-api-key';
import {
  DirectoriesService,
  type DirectoryLookupResult,
} from './directories.service';

@Controller('internal/dialplan')
export class DirectoryLookupController {
  private readonly logger = new Logger(DirectoryLookupController.name);
  private readonly apiKey: string;

  constructor(
    private readonly directoriesService: DirectoriesService,
    private readonly configService: ConfigService,
  ) {
    this.apiKey = this.configService.get<string>('DIALPLAN_API_KEY') || '';
  }

  @Get('directory-lookup')
  @HttpCode(200)
  async lookup(
    @Query('directory_uid') directoryUidRaw: string,
    @Query('user_uid') userUidRaw: string,
    @Query('key') key: string,
    @Query('field_uids') fieldUidsRaw: string,
    @Query('api_key') apiKey?: string,
  ): Promise<string> {
    this.assertKey(apiKey);

    const started = Date.now();
    let outcome = 'error';
    let matchKind: string | null = null;
    let directoryUid: number | null = parsePositiveInt(directoryUidRaw);
    let userUid: number | null = parsePositiveInt(userUidRaw);

    try {
      const fieldUids = parseFieldUids(fieldUidsRaw);
      if (directoryUid == null || userUid == null || fieldUids == null) {
        return 'KDL1|ERROR';
      }

      const result = await this.directoriesService.lookup({
        directoryUid,
        userUid,
        key,
        fieldUids,
      });
      outcome = result.status === 'FOUND'
        ? 'found'
        : result.status === 'NOT_FOUND'
          ? 'not_found'
          : 'error';
      matchKind = result.matchKind ?? null;
      return encodeLookupResponse(result);
    } catch (err) {
      this.logger.error(
        'Directory lookup failed',
        err instanceof Error ? err.stack : String(err),
      );
      return 'KDL1|ERROR';
    } finally {
      this.logger.log(JSON.stringify({
        duration_ms: Date.now() - started,
        outcome,
        user_uid: userUid,
        directory_uid: directoryUid,
        match_kind: matchKind,
      }));
    }
  }

  private assertKey(provided?: string): void {
    if (!timingSafeApiKeyEqual(this.apiKey, provided)) {
      this.logger.warn('Unauthorized internal directory lookup');
      throw new UnauthorizedException('Invalid API key');
    }
  }
}

function encodeLookupResponse(result: DirectoryLookupResult): string {
  if (result.status !== 'FOUND') return `KDL1|${result.status}`;
  return [
    'KDL1',
    'FOUND',
    ...result.values.map((value) => Buffer.from(String(value ?? ''), 'utf8').toString('base64')),
  ].join('|');
}

function parsePositiveInt(raw: string): number | null {
  if (typeof raw !== 'string' || raw.trim() === '') return null;
  const value = Number(raw);
  if (!Number.isInteger(value) || value < 1) return null;
  return value;
}

function parseFieldUids(raw: string): number[] | null {
  if (raw == null || String(raw).trim() === '') return [];
  const seen = new Set<number>();
  const result: number[] = [];
  for (const part of String(raw).split(',')) {
    const trimmed = part.trim();
    if (!trimmed) return null;
    const value = Number(trimmed);
    if (!Number.isInteger(value) || value < 1) return null;
    if (seen.has(value)) continue;
    seen.add(value);
    result.push(value);
  }
  return result;
}

/**
 * Asterisk dialplan pattern matching and specificity.
 *
 * Source: asterisk/main/pbx.c тАФ `_extension_match_core`, `ext_cmp`,
 * `ext_cmp_pattern`, `ext_cmp_pattern_pos`.
 *
 * A value that does not start with `_` is an exact exten. A leading `_`
 * starts a pattern. Among matching patterns Asterisk walks left to right
 * and picks the more specific token at the first difference:
 * a literal beats N/Z/X, a smaller character class beats a larger one,
 * and `.` / `!` are the least specific. `_1XXXXX` therefore beats
 * `_X11111` even though the latter has fewer wildcards overall.
 *
 *   X  тАФ digit 0-9
 *   Z  тАФ digit 1-9
 *   N  тАФ digit 2-9
 *   .  тАФ one or more of any character
 *   !  тАФ zero or more of any character
 */

export function isAsteriskPattern(value: string): boolean {
  return value.startsWith('_');
}

export function matchesAsteriskPattern(pattern: string, value: string): boolean {
  if (!isAsteriskPattern(pattern)) {
    return pattern === value;
  }

  const regex = asteriskPatternToRegex(pattern);
  if (!regex) return false;

  return regex.test(value);
}

/**
 * Sort key used by Asterisk when several extens could match.
 * Negative means `left` is more specific (or a non-pattern vs a pattern).
 */
export function compareAsteriskExten(left: string, right: string): number {
  if (!isAsteriskPattern(left)) {
    if (isAsteriskPattern(right)) return -1;
    return left < right ? -1 : left > right ? 1 : 0;
  }
  if (!isAsteriskPattern(right)) return 1;
  return compareAsteriskPattern(left.slice(1), right.slice(1));
}

export function pickBestAsteriskMatch<T>(
  items: T[],
  getPattern: (item: T) => string,
  value: string,
): T | undefined {
  const matched = items.filter((item) => matchesAsteriskPattern(getPattern(item), value));
  if (!matched.length) return undefined;
  matched.sort((a, b) => compareAsteriskExten(getPattern(a), getPattern(b)));
  return matched[0];
}

function asteriskPatternToRegex(pattern: string): RegExp | null {
  try {
    const body = pattern.substring(1);
    let regexStr = '^';
    let i = 0;

    while (i < body.length) {
      const ch = body[i];
      switch (ch) {
        case 'X':
        case 'x':
          regexStr += '[0-9]';
          break;
        case 'Z':
        case 'z':
          regexStr += '[1-9]';
          break;
        case 'N':
        case 'n':
          regexStr += '[2-9]';
          break;
        case '.':
          regexStr += '.+';
          break;
        case '!':
          regexStr += '.*';
          break;
        case '[': {
          const closeBracket = body.indexOf(']', i);
          if (closeBracket === -1) return null;
          regexStr += body.substring(i, closeBracket + 1);
          i = closeBracket;
          break;
        }
        default:
          regexStr += ch.replace(/[.*+?^${}()|\\]/g, '\\$&');
      }
      i++;
    }

    regexStr += '$';
    return new RegExp(regexStr);
  } catch {
    return null;
  }
}

const BITS_PER = 8;
const SCORE_END = 0x30000;

function compareAsteriskPattern(left: string, right: string): number {
  let leftIndex = 0;
  let rightIndex = 0;

  for (;;) {
    const leftPos = patternPos(left, leftIndex);
    const rightPos = patternPos(right, rightIndex);
    let cmp = leftPos.score - rightPos.score;
    if (!cmp) {
      // Asterisk memcmp's the right set against the left set when scores tie.
      cmp = compareBits(rightPos.bits, leftPos.bits);
    }
    if (cmp) return cmp < 0 ? -1 : 1;
    if (leftPos.next == null && rightPos.next == null) return 0;
    leftIndex = leftPos.next ?? left.length + 1;
    rightIndex = rightPos.next ?? right.length + 1;
  }
}

function patternPos(
  pattern: string,
  start: number,
): { score: number; bits: Uint8Array; next: number | null } {
  const bits = new Uint8Array(32);
  let i = start;

  for (;;) {
    while (i < pattern.length && pattern[i] === '-') i += 1;
    if (i >= pattern.length) {
      return { score: SCORE_END, bits, next: null };
    }

    const ch = pattern[i];
    i += 1;
    const upper = ch.toUpperCase();

    if (upper === 'N') {
      bits[6] = 0x3f;
      bits[7] = 0xc0;
      return { score: 0x0800 | '2'.charCodeAt(0), bits, next: i };
    }
    if (upper === 'X') {
      bits[6] = 0xff;
      bits[7] = 0xc0;
      return { score: 0x0a00 | '0'.charCodeAt(0), bits, next: i };
    }
    if (upper === 'Z') {
      bits[6] = 0x7f;
      bits[7] = 0xc0;
      return { score: 0x0900 | '1'.charCodeAt(0), bits, next: i };
    }
    if (ch === '.') return { score: 0x18000, bits, next: i };
    if (ch === '!') return { score: 0x28000, bits, next: i };

    if (ch === '[') {
      const end = pattern.indexOf(']', i);
      if (end === -1) return { score: 0x40000, bits, next: i };

      let count = 0;
      let cmin = 0xff;
      let cursor = i;
      while (cursor < end) {
        let from = pattern.charCodeAt(cursor);
        let to = from;
        if (cursor + 2 < end && pattern[cursor + 1] === '-') {
          to = pattern.charCodeAt(cursor + 2);
          cursor += 3;
        } else {
          cursor += 1;
        }
        if (from < cmin) cmin = from;
        for (let code = from; code <= to; code++) {
          const mask = 1 << ((BITS_PER - 1) - (code % BITS_PER));
          const bucket = Math.floor(code / BITS_PER);
          if (!(bits[bucket] & mask)) {
            bits[bucket] |= mask;
            count += 0x100;
          }
