export function toExtensionsPattern(extensions: string[]): string {
  const nums = [...new Set(extensions.map((value) => parseInt(value, 10)).filter((n) => !Number.isNaN(n)))]
    .sort((a, b) => a - b);
  if (nums.length === 0) return '';
  const parts: string[] = [];
  let start = nums[0];
  let prev = nums[0];
  for (let i = 1; i <= nums.length; i += 1) {
    const current = nums[i];
    if (current === prev + 1) {
      prev = current;
      continue;
    }
    parts.push(start === prev ? String(start) : `${start}-${prev}`);
    start = current;
    prev = current;
  }
  return parts.join(',');
}

export function parseBulkExtensions(pattern: string): string[] {
  const parsed = new Set<number>();
  const parts = (pattern || '').split(',').map((part) => part.trim());
  for (const part of parts) {
    if (!part) continue;
    if (part.includes('-')) {
      const [startStr, endStr] = part.split('-');
      const start = parseInt(startStr, 10);
      const end = parseInt(endStr, 10);
      if (!Number.isNaN(start) && !Number.isNaN(end) && start <= end) {
        for (let i = start; i <= end; i += 1) parsed.add(i);
      }
    } else {
      const num = parseInt(part, 10);
      if (!Number.isNaN(num)) parsed.add(num);
    }
  }
  return Array.from(parsed)
    .sort((a, b) => a - b)
    .map(String);
}

function displayNameFrom(current: {
  extension?: string;
  endpoint?: { callerid?: string };
  callerid?: string;
}): string {
  const callerid = current.endpoint?.callerid ?? current.callerid ?? '';
  const quoted = callerid.match(/"([^"]+)"/);
  if (quoted?.[1]) return quoted[1];
  return String(current.extension ?? '');
}

export interface IvrTimeoutFields {
  timeout?: string | null;
  timeout_response?: string | null;
  timeout_digit?: string | null;
}

export interface ResolvedIvrTimeouts {
  /** WaitExten тАФ seconds to wait for menu choice after prompts */
  waitExten: number;
  /** Asterisk TIMEOUT(response) тАФ first digit timeout */
  response: number;
  /** Asterisk TIMEOUT(digit) тАФ pause between digits */
  digit: number;
}

const DEFAULT_WAIT_EXTEN = 10;
const DEFAULT_RESPONSE = 10;
const DEFAULT_DIGIT = 5;

function parsePositiveSeconds(raw: string | null | undefined, fallback: number): number {
  if (raw == null || raw === '') return fallback;
  const n = parseInt(String(raw), 10);
  return Number.isFinite(n) && n > 0 ? n : fallback;
}

export function resolveIvrTimeouts(ivr: IvrTimeoutFields): ResolvedIvrTimeouts {
  const waitExten = parsePositiveSeconds(ivr.timeout, DEFAULT_WAIT_EXTEN);
  const response = ivr.timeout_response != null && ivr.timeout_response !== ''
    ? parsePositiveSeconds(ivr.timeout_response, waitExten)
    : waitExten;
  const digit = ivr.timeout_digit != null && ivr.timeout_digit !== ''
    ? parsePositiveSeconds(ivr.timeout_digit, DEFAULT_DIGIT)
    : DEFAULT_DIGIT;

  return { waitExten, response, digit };
}

import { Injectable, Logger } from '@nestjs/common';
import axios from 'axios';
import { pcm16ToWav } from './ivr-pcm-wav.util';

@Injectable()
export class IvrTtsCustomProvider {
  private readonly logger = new Logger(IvrTtsCustomProvider.name);

  async synthesize(
    url: string,
    text: string,
    token: string | null | undefined,
    authMode: string | null | undefined,
    customHeaders: Record<string, string> | null | undefined,
    settings: Record<string, any>,
  ): Promise<Buffer> {
    if (!url?.trim()) {
      throw new Error('Custom TTS URL is not configured');
    }

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      Accept: 'audio/*,application/octet-stream',
      ...(customHeaders || {}),
    };

    if (token) {
      if (authMode === 'bearer') {
        headers.Authorization = `Bearer ${token}`;
      }
    }

    const response = await axios.post(
      url,
      { text, settings: settings || {} },
      {
        headers,
        timeout: settings?.timeout_ms || 30000,
        responseType: 'arraybuffer',
        validateStatus: (s) => s >= 200 && s < 300,
      },
    );

    let audio = Buffer.from(response.data);
    const contentType = String(response.headers['content-type'] || '');

    if (contentType.includes('wav') || audio.slice(0, 4).toString() === 'RIFF') {
      return audio;
    }

    // Raw PCM16 8kHz mono
    if (contentType.includes('pcm') || settings?.format === 'pcm16') {
      return pcm16ToWav(audio, 8000, 1);
    }

    // MP3 or unknown тАФ return as-is (preview may still work in browser)
    return audio;
  }
}

