@ApiTags('MCP Server')
@ApiBearerAuth()
@Controller('mcp')
export class McpController {
    private readonly logger = new Logger(McpController.name);

    constructor(private readonly sessionService: McpSessionService) {}

    /**
     * ALL /api/mcp тАФ ╨╡╨┤╨╕╨╜╤Л╨╣ endpoint Streamable HTTP MCP ╤В╤А╨░╨╜╤Б╨┐╨╛╤А╤В╨░.
