     * Transport ╤Б╨░╨╝ ╨╛╨┐╤А╨╡╨┤╨╡╨╗╤П╨╡╤В ╤В╨╕╨┐ ╨┐╨╛ ╨╝╨╡╤В╨╛╨┤╤Г ╨╕ ╨╖╨░╨│╨╛╨╗╨╛╨▓╨║╨░╨╝.
     */
    @ApiOperation({ summary: 'MCP Streamable HTTP endpoint (GET/POST/DELETE)' })
    @UseGuards(JwtAuthGuard)
    @All()
    async handleMcp(
        @Req() req: Request & { user: any },
        @Res() res: Response,
    ): Promise<void> {
        const vpbxUserUid = req.user.vpbx_user_uid;
        this.logger.debug(`MCP ${req.method} from tenant ${vpbxUserUid}`);
        await this.sessionService.handleRequest(req, res, vpbxUserUid);
    }

    /**
     * GET /api/mcp/sessions тАФ ╤Б╨┐╨╕╤Б╨╛╨║ ╨░╨║╤В╨╕╨▓╨╜╤Л╤Е MCP ╤Б╨╡╤Б╤Б╨╕╨╣ (debug).
     */
    @ApiOperation({ summary: 'List active MCP sessions (debug)' })
    @UseGuards(JwtAuthGuard)
    @Get('sessions')
    getSessions(@Req() req: Request & { user: any }) {
        const sessions = this.sessionService.getActiveSessions();
        return { count: sessions.length, sessions };
    }
}

import { Injectable, NotFoundException, BadRequestException, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/sequelize';
import { MohClass } from './moh-class.model';
import { MohEntry } from './moh-entry.model';
import { AmiService } from '../ami/ami.service';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class MohService {
  private readonly logger = new Logger(MohService.name);
  private readonly soundsBasePath: string;

  constructor(
    @InjectModel(MohClass) private mohClassModel: typeof MohClass,
    @InjectModel(MohEntry) private mohEntryModel: typeof MohEntry,
    private readonly amiService: AmiService,
    private readonly configService: ConfigService,
  ) {
    this.soundsBasePath = this.configService.get<string>(
      'ASTERISK_SOUNDS_PATH',
      '/var/lib/asterisk/sounds/krasterisk',
    );
  }

  /**
   * Generate a safe Asterisk MOH class name from a display name.
   * Format: moh_{userUid}_{slug}
   * Only [a-z0-9_], max 80 chars (Asterisk limit).
   */
  generateClassName(displayName: string, userUid: number): string {
    const slug = displayName
      .toLowerCase()
      .replace(/[^a-z0-9╨░-╤П╤С]/gi, '_')
      // transliterate basic Cyrillic
      .replace(/[╨░-╤П╤С]/g, (c) => {
        const map: Record<string, string> = {
          ╨░: 'a', ╨▒: 'b', ╨▓: 'v', ╨│: 'g', ╨┤: 'd', ╨╡: 'e', ╤С: 'yo',
          ╨╢: 'zh', ╨╖: 'z', ╨╕: 'i', ╨╣: 'y', ╨║: 'k', ╨╗: 'l', ╨╝: 'm',
          ╨╜: 'n', ╨╛: 'o', ╨┐: 'p', ╤А: 'r', ╤Б: 's', ╤В: 't', ╤Г: 'u',
          ╤Д: 'f', ╤Е: 'h', ╤Ж: 'ts', ╤З: 'ch', ╤И: 'sh', ╤Й: 'sch',
          ╤К: '', ╤Л: 'y', ╤М: '', ╤Н: 'e', ╤О: 'yu', ╤П: 'ya',
        };
        return map[c] || c;
      })
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '');

    const prefix = `moh_${userUid}_`;
    const maxSlugLen = 80 - prefix.length;
    return prefix + slug.substring(0, maxSlugLen);
  }

  /**
   * Extract human-readable display name from the Asterisk class name.
   * moh_15_sales_hold тЖТ sales_hold
   */
  extractDisplayName(className: string): string {
    const parts = className.split('_');
    // Remove "moh" and user_uid prefix
    if (parts.length >= 3 && parts[0] === 'moh') {
      return parts.slice(2).join('_');
    }
    return className;
  }

  async findAll(userUid: number): Promise<any[]> {
    const classes = await this.mohClassModel.findAll({
      where: { user_uid: userUid },
      order: [['name', 'ASC']],
    });

    // Fetch entries for each class
    const result = [];
    for (const cls of classes) {
      const entries = await this.mohEntryModel.findAll({
        where: { name: cls.name },
        order: [['position', 'ASC']],
      });
      result.push({
        ...cls.toJSON(),
        displayName: this.extractDisplayName(cls.name),
        entries: entries.map((e) => e.toJSON()),
      });
    }
    return result;
  }

  async findOne(name: string, userUid: number): Promise<any> {
    const cls = await this.mohClassModel.findOne({
      where: { name, user_uid: userUid },
    });
    if (!cls) throw new NotFoundException('MOH class not found');

    const entries = await this.mohEntryModel.findAll({
      where: { name: cls.name },
      order: [['position', 'ASC']],
    });

    return {
      ...cls.toJSON(),
      displayName: this.extractDisplayName(cls.name),
      entries: entries.map((e) => e.toJSON()),
    };
  }

  async create(
    data: { displayName: string; sort?: string; entries?: { filename: string; position: number }[] },
    userUid: number,
  ): Promise<any> {
    if (!data.displayName) {
      throw new BadRequestException('displayName is required');
    }

    const className = this.generateClassName(data.displayName, userUid);

    // Check for name collision
    const existing = await this.mohClassModel.findByPk(className);
    if (existing) {
      throw new BadRequestException(`MOH class "${data.displayName}" already exists`);
    }

    const entryRows = data.entries || [];
    if (entryRows.length === 0) {
      throw new BadRequestException('At least one playlist entry is required');
    }

    // Create the MOH class (playlist mode тАФ entries drive playback, not directory)
    const cls = await this.mohClassModel.create({
      name: className,
      mode: 'playlist',
      directory: null,
      sort: data.sort || 'random',
      user_uid: userUid,
    } as any);

    // Create entries
    const entries = entryRows.map((e) => ({
      name: className,
      position: e.position,
      entry: `${this.soundsBasePath}/${e.filename}`,
    }));

    if (entries.length > 0) {
      await this.mohEntryModel.bulkCreate(entries as any[]);
    }

    // Reload MOH in Asterisk
    await this.reloadMoh();

    this.logger.log(`Created MOH class: ${className} with ${entries.length} entries`);

    return this.findOne(className, userUid);
  }

  async update(
    name: string,
    data: { displayName?: string; sort?: string; entries?: { filename: string; position: number }[] },
    userUid: number,
  ): Promise<any> {
    const cls = await this.mohClassModel.findOne({
      where: { name, user_uid: userUid },
    });
    if (!cls) throw new NotFoundException('MOH class not found');

    // Update class parameters
    if (data.sort) {
      await cls.update({ sort: data.sort });
    }

    // Atomically replace entries: delete all old тЖТ insert new
    if (data.entries !== undefined) {
      if (data.entries.length === 0) {
        throw new BadRequestException('At least one playlist entry is required');
      }

      await this.mohEntryModel.destroy({ where: { name } });

      const entries = data.entries.map((e) => ({
        name,
        position: e.position,
        entry: `${this.soundsBasePath}/${e.filename}`,
      }));

      await this.mohEntryModel.bulkCreate(entries as any[]);

      if (cls.mode !== 'playlist') {
        await cls.update({ mode: 'playlist', directory: null });
      }
    }

    // Reload MOH in Asterisk
    await this.reloadMoh();

    this.logger.log(`Updated MOH class: ${name}`);

    return this.findOne(name, userUid);
  }

  async remove(name: string, userUid: number): Promise<void> {
    const cls = await this.mohClassModel.findOne({
      where: { name, user_uid: userUid },
    });
    if (!cls) throw new NotFoundException('MOH class not found');

    // Delete entries first (cascade)
    await this.mohEntryModel.destroy({ where: { name } });
    // Delete the class
    await cls.destroy();

    // Reload MOH in Asterisk
    await this.reloadMoh();

    this.logger.log(`Deleted MOH class: ${name}`);
  }

  /**
   * Reload MOH module in Asterisk via AMI.
   */
  private async reloadMoh(): Promise<void> {
    try {
      if (this.amiService.isConnected()) {
        await this.amiService.command('moh reload');
        this.logger.log('AMI: moh reload sent');
      }
    } catch (err) {
      this.logger.warn(`AMI moh reload failed (non-critical): ${err}`);
    }
  }
}

import { Injectable, NotFoundException, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/sequelize';
import { NotificationIntegration } from './notification-integration.model';
import { RouteReferencesService } from '../route-references/route-references.service';
import {
  CreateNotificationIntegrationDto,
  UpdateNotificationIntegrationDto,
} from './dto/notification-integration.dto';
import { encryptSecret, decryptSecret } from '../ai-agents/util/secret-cipher.util';

@Injectable()
export class NotificationsService {
  private readonly logger = new Logger(NotificationsService.name);

  constructor(
    @InjectModel(NotificationIntegration)
    private readonly model: typeof NotificationIntegration,
    private readonly routeReferencesService: RouteReferencesService,
  ) {}

  /** Strip encrypted_credentials before returning to HTTP clients. */
  private toPublic(row: NotificationIntegration) {
    const json = row.toJSON ? row.toJSON() : row;
    const { encrypted_credentials, ...rest } = json as Record<string, unknown>;
    return rest;
  }

  async findAll(vpbx: number) {
    const rows = await this.model.findAll({
      where: { user_uid: vpbx },
      order: [['uid', 'DESC']],
    });
    return rows.map((r) => this.toPublic(r));
  }

  async findOne(uid: number, vpbx: number) {
    const row = await this.model.findOne({
      where: { uid, user_uid: vpbx },
    });
    if (!row) throw new NotFoundException('Notification integration not found');
    return this.toPublic(row);
  }

  async create(dto: CreateNotificationIntegrationDto, vpbx: number) {
    const { credentials, ...rest } = dto as CreateNotificationIntegrationDto & {
      user_uid?: number;
    };
    delete (rest as { user_uid?: number }).user_uid;

    const encrypted_credentials =
      credentials !== undefined
        ? encryptSecret(JSON.stringify(credentials))
        : null;

    const row = await this.model.create({
      ...rest,
      encrypted_credentials,
      user_uid: vpbx,
    } as Parameters<typeof this.model.create>[0]);

    return this.toPublic(row);
  }

  async update(uid: number, dto: UpdateNotificationIntegrationDto, vpbx: number) {
    const row = await this.model.findOne({ where: { uid, user_uid: vpbx } });
    if (!row) throw new NotFoundException('Notification integration not found');

    const { credentials, ...rest } = dto as UpdateNotificationIntegrationDto & {
      user_uid?: number;
    };
    delete (rest as { user_uid?: number }).user_uid;

    const patch: Record<string, unknown> = { ...rest };
    if (credentials !== undefined) {
      patch.encrypted_credentials = credentials
        ? encryptSecret(JSON.stringify(credentials))
        : null;
    }

    await row.update(patch);
    return this.toPublic(row);
  }

  async remove(uid: number, vpbx: number) {
    const row = await this.model.findOne({ where: { uid, user_uid: vpbx } });
    if (!row) throw new NotFoundException('Notification integration not found');
    await this.routeReferencesService.assertNotReferenced(
      'integration',
      uid,
      vpbx,
      'Notification integration is referenced and cannot be deleted',
    );
    await row.destroy();
    return { success: true };
  }

  /**
   * Internal lookup for the dispatcher тАФ decrypts credentials.
   *
   * No tenant filter: integration uid is globally unique and the dispatcher
   * resolves it from a route already scoped to the tenant.
   */
  async findByUidInternal(uid: number) {
    const row = await this.model.findOne({ where: { uid } });
    if (!row) throw new NotFoundException('Notification integration not found');

    const json = row.toJSON();
    let credentials: Record<string, unknown> = {};
    if (json.encrypted_credentials) {
      const plain = decryptSecret(json.encrypted_credentials);
      if (plain) {
        credentials = JSON.parse(plain) as Record<string, unknown>;
      }
    }

    return { ...json, credentials };
  }
}

import {
  Controller, Get, Post, Put, Delete,
  Param, Body, Req, Res, UploadedFile,
  UseInterceptors, ParseIntPipe, StreamableFile,
  BadRequestException,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { Response } from 'express';
import * as path from 'path';
import { PromptsService } from './prompts.service';
import { IvrTtsService } from '../ivrs/ivr-tts.service';
import type { IPromptTtsMeta } from '@krasterisk/shared';
import { PromptSynthesizeDto, PromptTtsPreviewDto } from './dto/prompt-tts.dto';
import { PromptUpdateDto } from './dto/prompt-update.dto';

@Controller('prompts')
export class PromptsController {
  constructor(
    private readonly promptsService: PromptsService,
    private readonly ivrTtsService: IvrTtsService,
  ) {}

  @Get()
  async findAll(@Req() req: any) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    return this.promptsService.findAll(userUid);
  }

  @Get(':id')
  async findOne(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    return this.promptsService.findOne(id, userUid);
  }

  /**
   * Upload a new audio prompt.
   * File is received via multipart form-data.
   * In production, this would:
   * 1. Convert to WAV 8kHz mono 16-bit via sox/ffmpeg
   * 2. Upload to Asterisk server via SFTP
   * 3. Save metadata to DB
   */
  @Post('upload')
  @UseInterceptors(FileInterceptor('file', {
    limits: { fileSize: 10 * 1024 * 1024 }, // 10MB
    fileFilter: (_req, file, cb) => {
      if (!file.mimetype.startsWith('audio/')) {
        cb(new BadRequestException('Only audio files are allowed'), false);
      } else {
        cb(null, true);
      }
    },
  }))
  async upload(
    @UploadedFile() file: Express.Multer.File,
    @Body('comment') comment: string,
    @Body('description') description: string,
    @Req() req: any,
  ) {
    if (!file) {
      throw new BadRequestException('No audio file provided');
    }

    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    const filename = this.promptsService.generateFilename(userUid);

    const ext = path.extname(file.originalname) || '.wav';
    await this.promptsService.savePromptAudio(userUid, filename, file.buffer, ext);

    const prompt = await this.promptsService.create(
      {
        filename,
        comment: comment || file.originalname,
        description: description || '',
      },
      userUid,
    );

    return prompt;
  }

  /**
   * Initiate a recording by calling an extension via AMI.
   */
  @Post('record')
  async record(
    @Body('exten') exten: string,
    @Body('comment') comment: string,
    @Body('description') description: string,
    @Req() req: any,
  ) {
    if (!exten) {
      throw new BadRequestException('Extension is required');
    }

    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    const filename = this.promptsService.generateFilename(userUid);

    // Initiate AMI originate
    await this.promptsService.recordByPhone(exten, filename, userUid);

    // Create DB record
    await this.promptsService.create(
      {
        filename,
        comment: comment || `Recording ${filename}`,
        description: description || '',
      },
      userUid,
    );

    return { message: 'Recording initiated', filename };
  }

  @Post('tts-preview')
  async ttsPreview(
    @Body() dto: PromptTtsPreviewDto,
    @Req() req: any,
    @Res() res: Response,
  ) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    try {
      const engine = await this.ivrTtsService.loadEngine(dto.engine_uid, userUid);
      const wav = await this.ivrTtsService.synthesizeToBuffer(engine, dto.text, dto.settings);
      res.setHeader('Content-Type', 'audio/wav');
      res.setHeader('Content-Length', String(wav.length));
      res.send(wav);
    } catch (err: any) {
      throw new BadRequestException(err.message || 'TTS preview failed');
    }
  }

  /**
   * Synthesize speech via a configured TTS engine and register a prompt record.
   * Audio file upload to Asterisk (SFTP) is deferred тАФ metadata is persisted now.
   */
  @Post('synthesize')
  async synthesize(@Body() dto: PromptSynthesizeDto, @Req() req: any) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    const comment = dto.comment?.trim();
    if (!comment) {
      throw new BadRequestException('Recording name is required');
    }

    let wav: Buffer;
    try {
      const engine = await this.ivrTtsService.loadEngine(dto.engine_uid, userUid);
      wav = await this.ivrTtsService.synthesizeToBuffer(engine, dto.text, dto.settings);
    } catch (err: any) {
      throw new BadRequestException(err.message || 'TTS synthesis failed');
    }

    const filename = this.promptsService.generateFilename(userUid);
    await this.promptsService.savePromptAudio(userUid, filename, wav, '.wav');

    const ttsMeta: IPromptTtsMeta = {
      text: dto.text.trim(),
      engine_uid: dto.engine_uid,
      settings: dto.settings,
    };

    return this.promptsService.create(
      {
        filename,
        comment,
        description: dto.description?.trim() || '',
        tts: ttsMeta,
      },
      userUid,
    );
  }

  /**
   * Stream audio file for browser playback.
   * TODO: Phase 3 тАФ download from Asterisk via SFTP and pipe to response.
   */
  @Get(':id/stream')
  async stream(
    @Param('id', ParseIntPipe) id: number,
    @Req() req: any,
    @Res() res: Response,
  ) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    const prompt = await this.promptsService.findOneRow(id, userUid);
    await this.promptsService.streamPromptAudio(userUid, prompt, res);
  }

  @Put(':id')
  async update(
    @Param('id', ParseIntPipe) id: number,
    @Body() body: PromptUpdateDto,
    @Req() req: any,
  ) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    return this.promptsService.update(
      id,
      {
        comment: body.comment,
        description: body.description,
        tts: body.tts,
      },
      userUid,
      async (filename, meta) => {
        const engine = await this.ivrTtsService.loadEngine(meta.engine_uid, userUid);
        const wav = await this.ivrTtsService.synthesizeToBuffer(engine, meta.text, meta.settings);
        await this.promptsService.savePromptAudio(userUid, filename, wav, '.wav');
      },
    );
  }

  @Delete(':id')
  async remove(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    const { filename } = await this.promptsService.remove(id, userUid);
    // audio file on disk left for manual cleanup until SFTP lifecycle is implemented

    // TODO: Phase 3 тАФ delete file from Asterisk via SFTP

    return { message: 'Prompt deleted', filename };
  }

  @Post('bulk/delete')
  async bulkDelete(@Body() body: { ids: number[] }, @Req() req: any) {
    const userUid = req.user?.vpbx_user_uid || req.user?.user_uid || 0;
    return this.promptsService.bulkRemove(body.ids, userUid);
  }
}

import { Injectable, NotFoundException, ConflictException, Logger } from '@nestjs/common';
import { InjectModel } from '@nestjs/sequelize';
import { Sequelize } from 'sequelize-typescript';
import { Queue } from './queue.model';
import { QueueMember } from './queue-member.model';
import { AmiService } from '../ami/ami.service';
import { buildSipId } from '../endpoints/endpoint-ids.util';
import { RouteReferencesService } from '../route-references/route-references.service';
import { AsteriskDialplanUtils } from '../../shared/utils/dialplan.util';
import {
  callbackDtmfContextName,
  wantsCallbackDtmf,
} from './queue-dialplan.util';

export interface CreateQueueDto {
  exten: string;
  display_name?: string;
  strategy?: string;
  timeout?: number;
  retry?: number;
  wrapuptime?: number;
  maxlen?: number;
  musiconhold?: string;
  context?: string;
  weight?: number;
  servicelevel?: number;
  joinempty?: string;
  leavewhenempty?: string;
  ringinuse?: boolean;
  autofill?: string | boolean;
  // Announcements
  announce?: string;
  announce_frequency?: number;
  announce_holdtime?: string;
  announce_round_seconds?: number;
  periodic_announce?: string;
  periodic_announce_frequency?: number;
  queue_youarenext?: string;
  queue_thereare?: string;
  queue_callswaiting?: string;
  queue_holdtime?: string;
  queue_minutes?: string;
  queue_seconds?: string;
  queue_lessthan?: string;
  queue_thankyou?: string;
  queue_reporthold?: string;
  // Advanced (dynamic key-value)
  advanced?: Record<string, any>;
  // Members
  members?: MemberDto[];
}

export interface UpdateQueueDto extends Partial<CreateQueueDto> {}

export interface MemberDto {
  interface: string;
  membername?: string;
  penalty?: number;
  paused?: number;
  wrapuptime?: number;
  state_interface?: string;
}

@Injectable()
export class QueuesService {
  private readonly logger = new Logger(QueuesService.name);

  constructor(
    @InjectModel(Queue) private queueModel: typeof Queue,
    @InjectModel(QueueMember) private memberModel: typeof QueueMember,
    private sequelize: Sequelize,
    private amiService: AmiService,
    private readonly routeReferencesService: RouteReferencesService,
  ) {}

  /** Build globally unique queue name: q{exten}_{vpbxUserUid} */
  private buildQueueName(vpbxUserUid: number, exten: string): string {
    return `q${exten}_${vpbxUserUid}`;
  }

  /** Extract user-facing extension number from queue name */
  private extractExten(queueName: string): string {
    // q700_42 тЖТ "700"
    const match = queueName.match(/^q(.+)_\d+$/);
    return match ? match[1] : queueName;
  }

  /**
   * Queue members must use tenant SIP ids (PJSIP/e101_0), not bare PJSIP/101.
   * Legacy bare extensions are rewritten on save.
   */
  private normalizeMemberInterface(iface: string, vpbxUserUid: number): string {
    const raw = String(iface || '').trim();
    if (!raw) return raw;
    if (/^Local\//i.test(raw)) return raw;
    const m = raw.match(/^(PJSIP|SIP)\/(.+)$/i);
    if (!m) return raw;
    const id = m[2].trim();
    if (/^e(w)?.+_\d+$/i.test(id)) return `PJSIP/${id}`;
    if (/^\d+$/.test(id)) return `PJSIP/${buildSipId(vpbxUserUid, id)}`;
    return `PJSIP/${id}`;
  }

  /** D-38: Queue.context breakout for DTMF-while-waiting when policy allows. */
  private applyCallbackBreakoutContext(data: Record<string, any>, vpbxUserUid: number): void {
    if (data.context) return;
    if (
      wantsCallbackDtmf(AsteriskDialplanUtils.callbackPolicy)
      && AsteriskDialplanUtils.hasCallbackStep
    ) {
      data.context = callbackDtmfContextName(vpbxUserUid);
    }
  }

  private mapMembersForSave(members: MemberDto[] | undefined, queueName: string, vpbxUserUid: number) {
    if (!members?.length) return [];
    return members.map((m) => ({
      ...m,
      interface: this.normalizeMemberInterface(m.interface, vpbxUserUid),
      queue_name: queueName,
      user_uid: vpbxUserUid,
    }));
  }

  async findAll(vpbxUserUid: number) {
    const queues = await this.queueModel.findAll({
      where: { user_uid: vpbxUserUid },
      order: [['name', 'ASC']],
    });

    // Attach member count for each queue
    const result = [];
    for (const q of queues) {
      const queueName = q.getDataValue('name');
      const memberCount = await this.memberModel.count({
        where: { queue_name: queueName, user_uid: vpbxUserUid },
      });
      result.push({
        ...q.toJSON(),
        exten: this.extractExten(queueName),
        memberCount,
      });
    }
    return result;
  }

  async findOne(name: string, vpbxUserUid: number) {
    const queue = await this.queueModel.findOne({
      where: { name, user_uid: vpbxUserUid },
    });
    if (!queue) throw new NotFoundException(`Queue "${name}" not found`);

    const members = await this.memberModel.findAll({
      where: { queue_name: name, user_uid: vpbxUserUid },
      order: [['penalty', 'ASC'], ['uniqueid', 'ASC']],
    });

    return {
      ...queue.toJSON(),
      exten: this.extractExten(queue.getDataValue('name')),
      members: members.map(m => m.toJSON()),
    };
  }

  async create(dto: CreateQueueDto, vpbxUserUid: number) {
    const queueName = this.buildQueueName(vpbxUserUid, dto.exten);

    // Check for duplicate name
    const existing = await this.queueModel.findOne({
      where: { name: queueName, user_uid: vpbxUserUid },
    });
    if (existing) throw new ConflictException(`Queue with extension "${dto.exten}" already exists`);

    const transaction = await this.sequelize.transaction();
    try {
      // Extract members and advanced before creating queue
      const { members, advanced, exten, ...queueData } = dto;

      // Merge advanced fields into queue data
      const fullData: any = {
        ...queueData,
        ...(advanced || {}),
        name: queueName,
        user_uid: vpbxUserUid,
      };
      this.applyCallbackBreakoutContext(fullData, vpbxUserUid);

      const queue = await this.queueModel.create(fullData, { transaction });

      // Create members
      if (members?.length) {
        await this.memberModel.bulkCreate(
          this.mapMembersForSave(members, queueName, vpbxUserUid),
          { transaction },
        );
      }

      await transaction.commit();
      await this.reloadQueues();
      this.logger.log(`Queue "${dto.exten}" (${queueName}) created with ${members?.length || 0} members`);
      return this.findOne(queueName, vpbxUserUid);
    } catch (e) {
      await transaction.rollback();
      throw e;
    }
  }

  async update(name: string, dto: UpdateQueueDto, vpbxUserUid: number) {
    const queue = await this.queueModel.findOne({
      where: { name, user_uid: vpbxUserUid },
    });
    if (!queue) throw new NotFoundException(`Queue "${name}" not found`);

    const transaction = await this.sequelize.transaction();
    try {
      const { members, advanced, exten, ...queueData } = dto;

      const newQueueName = exten ? this.buildQueueName(vpbxUserUid, exten) : name;
      const isRenaming = newQueueName !== name;

      if (isRenaming) {
        const existing = await this.queueModel.findOne({
          where: { name: newQueueName, user_uid: vpbxUserUid },
        });
        if (existing) {
          throw new ConflictException(`Queue with extension "${exten}" already exists`);
        }
      }

      // Merge advanced fields
      const updateData: any = {
        ...queueData,
        ...(advanced || {}),
        ...(isRenaming ? { name: newQueueName } : {}),
      };

      // Remove undefined values
      Object.keys(updateData).forEach(k => {
        if (updateData[k] === undefined) delete updateData[k];
      });
      this.applyCallbackBreakoutContext(updateData, vpbxUserUid);

      await queue.update(updateData, { transaction });

      // Sync members if provided
      if (members !== undefined) {
        await this.memberModel.destroy({
          where: { queue_name: name, user_uid: vpbxUserUid },
          transaction,
        });
        if (members.length) {
          await this.memberModel.bulkCreate(
            this.mapMembersForSave(members, newQueueName, vpbxUserUid),
            { transaction },
          );
        }
      } else if (isRenaming) {
        // If members weren't passed but queue was renamed, we must manually update queue_name on existing members
        await this.memberModel.update(
          { queue_name: newQueueName },
          { where: { queue_name: name, user_uid: vpbxUserUid }, transaction }
        );
      }

      await transaction.commit();
      await this.reloadQueues();
      this.logger.log(`Queue "${name}" updated${isRenaming ? ` and renamed to "${newQueueName}"` : ''}`);
      return this.findOne(newQueueName, vpbxUserUid);
    } catch (e) {
      await transaction.rollback();
      throw e;
    }
  }

  async remove(name: string, vpbxUserUid: number) {
    const queue = await this.queueModel.findOne({
      where: { name, user_uid: vpbxUserUid },
    });
    if (!queue) throw new NotFoundException(`Queue "${name}" not found`);
    const exten = this.extractExten(name);
    await this.routeReferencesService.assertNotReferenced(
      'queue',
      [name, exten, `q${exten}`],
      vpbxUserUid,
      'Queue is referenced and cannot be deleted',
    );

    const transaction = await this.sequelize.transaction();
    try {
      await this.memberModel.destroy({
        where: { queue_name: name, user_uid: vpbxUserUid },
        transaction,
      });
      await queue.destroy({ transaction });
      await transaction.commit();
      await this.reloadQueues();
      this.logger.log(`Queue "${name}" deleted`);
      return { success: true };
    } catch (e) {
      await transaction.rollback();
      throw e;
    }
  }

  private async reloadQueues() {
    try {
      await this.amiService.command('queue reload all');
    } catch (e) {
      this.logger.warn(`Queue reload failed: ${e}`);
    }
  }
}

import { Module, Global, Provider, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/** DI token for the shared Redis client */
export const REDIS_CLIENT = 'REDIS_CLIENT';

/**
 * A null-safe Redis client stub used when Redis is not configured.
 * All operations return safe no-op results so callers don't need
 * null-checks everywhere.
 */
const nullRedis = new Proxy({} as any, {
  get: (_target, prop) => {
    // Must NOT be thenable тАФ if .then is a function, `await nullRedis`
    // treats it as a Promise and calls .then(resolve, reject).
    // Our generic handler would return a function but never call resolve,
    // causing an infinite hang in NestJS's async provider resolution.
    if (prop === 'then' || prop === 'catch' || prop === 'finally') return undefined;
    if (prop === Symbol.toStringTag) return 'RedisNullStub';
    if (prop === 'status') return 'close';
    if (prop === 'isConnected') return false;
    return (..._args: any[]) => Promise.resolve(null);
  },
});

const redisClientProvider: Provider = {
  provide: REDIS_CLIENT,
  inject: [ConfigService],
  useFactory: async (config: ConfigService): Promise<any> => {
    const logger = new Logger('RedisModule');
    const host = config.get<string>('REDIS_HOST');
    const port = config.get<number>('REDIS_PORT') || 6379;

    if (!host) {
      logger.warn('REDIS_HOST not set тАФ Redis disabled. Features requiring Redis will use fallbacks.');
      return nullRedis;
    }

    // Lazy require тАФ only load ioredis when Redis is actually configured.
    // Top-level `import Redis from 'ioredis'` causes ioredis to register
    // Node.js async_hooks and trigger dns.lookup at module load time,
    // which blocks the NestJS IoC container's Promise.all() in
    // createInstances() on Windows, preventing the app from starting.
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const Redis = require('ioredis').default ?? require('ioredis');

    const client = new Redis({
      host,
      port,
      // Retry strategy: give up after 3 attempts (don't block startup)
      maxRetriesPerRequest: 3,
      enableOfflineQueue: false,
      lazyConnect: true,          // don't connect until first command
      connectTimeout: 5000,
      retryStrategy: (times: number) => {
        if (times > 3) return null; // stop retrying тЖТ throw error
        return Math.min(times * 500, 2000);
      },
    });

    try {
      await client.connect();
      await client.ping();
      logger.log(`Redis connected (${host}:${port})`);
      return client;
    } catch (err: any) {
      logger.warn(`Redis connection failed (${host}:${port}): ${err.message} тАФ using null stub`);
      client.disconnect();
      return nullRedis;
    }
  },
};

/**
 * Global Redis module тАФ provides a shared ioredis client via DI.
 *
 * Usage in any module:
 *   constructor(@Inject(REDIS_CLIENT) private readonly redis: Redis) {}
 *
 * The module is @Global() тАФ no need to import it in every module,
 * just ensure it is imported ONCE in AppModule.
 *
 * If REDIS_HOST is not set or Redis is unavailable, injects a null-safe
 * proxy stub тАФ callers receive null/resolved Promises instead of errors.
 */
@Global()
@Module({
  providers: [redisClientProvider],
  exports: [REDIS_CLIENT],
})
export class RedisModule {}

import { Injectable, NotFoundException } from '@nestjs/common';
import type { Request, Response } from 'express';
import { InjectModel } from '@nestjs/sequelize';
import { Sequelize } from 'sequelize-typescript';
import { QueryTypes } from 'sequelize';
import { Cdr } from './cdr.model';
import { CdrQueryDto } from './dto/cdr-query.dto';
import { User, UserLevel } from '../../users/user.model';
import { NumberList } from '../../numbers/number-list.model';
import {
  classifyDirection,
  extractExtension,
  extractTrunkSlug,
  isAnswered,
  shortenChannel,
  tenantLegFilter,
} from './cdr.utils';
import { SystemSettingsService } from '../../system-settings/system-settings.service';
import { PsEndpoint } from '../../endpoints/ps-endpoint.model';
import {
  buildCdrLinkedidAccessClause,
  parseCdrAccessBlob,
  type CdrAccessScope,
} from './cdr-access-scope';
import { normalizeAccessToken } from '../../callcenter/callcenter-access-list.util';
import * as fs from 'fs';
import * as path from 'path';

export interface CdrCallSummary {
  linkedid: string;
  uniqueid: string;
  calldate: string;
  clid: string;
  src: string;
  usrc: string;
  dst: string;
  dialednum: string | null;
  disposition: string;
  dstchannel: string;
  duration: number;
  billsec: number;
  record: string | null;
  transid: string | null;
  dcontext: string;
  legCount: number;
  answered: boolean;
  direction: string;
  srcDisplay: string;
  dstDisplay: string;
  recordingUrl: string | null;
  hasRecording: boolean;
}

export interface CdrFilters extends CdrQueryDto {}

interface SqlParts {
  where: string;
  replacements: Record<string, unknown>;
}

@Injectable()
export class CdrService {
  constructor(
    @InjectModel(Cdr) private readonly cdrModel: typeof Cdr,
    @InjectModel(PsEndpoint) private readonly endpointModel: typeof PsEndpoint,
    @InjectModel(User) private readonly userModel: typeof User,
    @InjectModel(NumberList) private readonly numberListModel: typeof NumberList,
    private readonly sequelize: Sequelize,
    private readonly systemSettings: SystemSettingsService,
  ) {}

  private legFilter(vpbxUserUid: number): SqlParts {
    const tenant = tenantLegFilter(vpbxUserUid);
    return {
      where: `${tenant.sql} AND c.lastapp <> 'Transferred Call'`,
      replacements: { ...tenant.replacements },
    };
  }

  private async resolveCdrAccess(
    viewerUserId?: number,
  ): Promise<CdrAccessScope | null> {
    if (!viewerUserId) return null;
    const user = await this.userModel.findOne({
      where: { uniqueid: viewerUserId },
      attributes: ['uniqueid', 'numbers_id', 'exten', 'login', 'level'],
    });
    if (!user) return null;

    const level = Number(user.getDataValue('level'));
    if (level === UserLevel.SUPERADMIN || level === UserLevel.ADMIN) return null;

    const numbersId = user.getDataValue('numbers_id') as number | null | undefined;
    if (!numbersId || numbersId <= 0) return null;

    const list = await this.numberListModel.findOne({
      where: { id: numbersId },
      attributes: ['numbers'],
    });
    let blob = list?.getDataValue('numbers') as unknown;
    if (typeof blob === 'string') {
      try {
        blob = JSON.parse(blob);
      } catch {
        blob = null;
      }
    }
    const parsed = parseCdrAccessBlob(
      blob && typeof blob === 'object' ? (blob as { cdr?: unknown }).cdr : undefined,
    );
    let operatorExtens = parsed.operators;
    if (parsed.operatorUserIds.length > 0) {
      const staff = await this.userModel.findAll({
        where: { uniqueid: parsed.operatorUserIds },
        attributes: ['uniqueid', 'exten', 'login'],
      });
      operatorExtens = staff
        .map((u) =>
          normalizeAccessToken(u.getDataValue('exten') as string)
          || (/^\d+$/.test(String(u.getDataValue('login') || ''))
            ? String(u.getDataValue('login'))
            : ''),
        )
        .filter(Boolean);
    }
    const ownExten =
      normalizeAccessToken(user.getDataValue('exten') as string)
      || (/^\d+$/.test(String(user.getDataValue('login') || ''))
        ? String(user.getDataValue('login'))
        : null);
    return { operators: operatorExtens, queues: parsed.queues, ownExten };
  }

  private async accessWhere(
    vpbxUserUid: number,
    viewerUserId?: number,
  ): Promise<SqlParts | null> {
    const scope = await this.resolveCdrAccess(viewerUserId);
    if (!scope) return null;
    const clause = buildCdrLinkedidAccessClause('c', vpbxUserUid, scope);
    if (!clause) return null;
    return { where: clause.sql, replacements: clause.replacements };
  }

  private viewerIdFromReq(req?: Request): number | undefined {
    const sub = (req as Request & { user?: { sub?: number } })?.user?.sub;
    const n = Number(sub);
    return Number.isFinite(n) && n > 0 ? n : undefined;
  }

  private async ensureCallVisible(
    vpbxUserUid: number,
    callId: string,
    viewerUserId?: number,
  ): Promise<void> {
    const access = await this.accessWhere(vpbxUserUid, viewerUserId);
    if (!access) return;
    const tenant = tenantLegFilter(vpbxUserUid);
    const sql = `
      SELECT 1 AS ok
      FROM cdr c
      WHERE ${tenant.sql}
        AND (c.uniqueid = :callId OR c.linkedid = :callId OR c.transid = :callId)
        AND ${access.where}
      LIMIT 1
    `;
    const [row] = await this.sequelize.query(sql, {
      replacements: { ...tenant.replacements, ...access.replacements, callId },
      type: QueryTypes.SELECT,
    }) as any[];
    if (!row) {
      throw new NotFoundException('CDR record not found');
    }
  }

  private async applyFilters(
    vpbxUserUid: number,
    filters: CdrFilters,
    viewerUserId?: number,
  ): Promise<SqlParts> {
    const parts = this.legFilter(vpbxUserUid);
    const clauses: string[] = [parts.where];
    const replacements = { ...parts.replacements };

    if (filters.dateFrom) {
      clauses.push('c.calldate >= :dateFrom');
      replacements.dateFrom = filters.dateFrom.length <= 10 ? `${filters.dateFrom} 00:00:00` : filters.dateFrom;
    }
    if (filters.dateTo) {
      clauses.push('c.calldate <= :dateTo');
      replacements.dateTo = filters.dateTo.length <= 10 ? `${filters.dateTo} 23:59:59` : filters.dateTo;
    }

    if (filters.direction === 'in') {
      clauses.push(`(c.dialednum IS NOT NULL AND c.dialednum <> '')`);
    } else if (filters.direction === 'out') {
      clauses.push(`c.dcontext LIKE :outCtx`);
      replacements.outCtx = `sip-out${vpbxUserUid}%`;
    } else if (filters.direction === 'int') {
      clauses.push(`(CHAR_LENGTH(c.usrc) <= 4 AND CHAR_LENGTH(c.dst) <= 4)`);
    } else if (filters.direction === 'external') {
      clauses.push(
        `(CHAR_LENGTH(c.usrc) > 4 OR CHAR_LENGTH(c.dst) > 4) AND c.lastapp <> 'Queue'`,
      );
    }

    if (filters.disposition === 'answered') {
      clauses.push(`(c.disposition = 'ANSWERED' AND c.dstchannel <> '')`);
    } else if (filters.disposition === 'missed') {
      clauses.push(`(c.disposition <> 'ANSWERED' OR c.dstchannel = '')`);
    } else if (filters.disposition) {
      clauses.push(`c.disposition = :disposition`);
      replacements.disposition = filters.disposition;
    }

    if (filters.search?.trim()) {
      clauses.push(
        `(c.usrc LIKE :search OR c.dst LIKE :search OR c.dialednum LIKE :search OR c.channel LIKE :search OR c.dstchannel LIKE :search OR c.disposition LIKE :search)`,
      );
      replacements.search = `%${filters.search.trim()}%`;
    }

    if (filters.extension?.trim()) {
      const ext = filters.extension.trim();
      clauses.push(
        `(c.usrc = :ext OR c.dst = :ext OR c.channel LIKE :extPat OR c.dstchannel LIKE :extPat)`,
      );
      replacements.ext = ext;
      replacements.extPat = `%e${ext}_${vpbxUserUid}%`;
    }

    if (filters.trunk?.trim()) {
      const trunk = filters.trunk.trim();
      clauses.push(`(c.dialednum = :trunk OR c.channel LIKE :trunkPat OR c.dstchannel LIKE :trunkPat)`);
      replacements.trunk = trunk;
      replacements.trunkPat = `%t_${trunk}_${vpbxUserUid}%`;
    }

    const access = await this.accessWhere(vpbxUserUid, viewerUserId);
    if (access) {
      clauses.push(access.where);
      Object.assign(replacements, access.replacements);
    }

    return { where: clauses.join(' AND '), replacements };
  }

  private summarySelect(): string {
    return `
      c.linkedid AS linkedid,
      SUBSTRING_INDEX(GROUP_CONCAT(c.uniqueid ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS uniqueid,
      MIN(c.calldate) AS calldate,
      SUBSTRING_INDEX(GROUP_CONCAT(c.clid ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS clid,
      SUBSTRING_INDEX(GROUP_CONCAT(c.src ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS src,
      SUBSTRING_INDEX(GROUP_CONCAT(c.usrc ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS usrc,
      SUBSTRING_INDEX(GROUP_CONCAT(c.channel ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS channel,
      SUBSTRING_INDEX(GROUP_CONCAT(c.dst ORDER BY c.calldate DESC SEPARATOR '||'), '||', 1) AS dst,
      MAX(c.dialednum) AS dialednum,
      SUBSTRING_INDEX(GROUP_CONCAT(c.disposition ORDER BY c.calldate DESC SEPARATOR '||'), '||', 1) AS disposition,
      SUBSTRING_INDEX(GROUP_CONCAT(c.dstchannel ORDER BY c.calldate DESC SEPARATOR '||'), '||', 1) AS dstchannel,
      SUM(c.duration) AS duration,
      MAX(c.billsec) AS billsec,
      MAX(c.record) AS record,
      MAX(c.transid) AS transid,
      SUBSTRING_INDEX(GROUP_CONCAT(c.dcontext ORDER BY c.calldate SEPARATOR '||'), '||', 1) AS dcontext,
      COUNT(*) AS leg_count,
      MAX(CASE WHEN c.disposition = 'ANSWERED' AND c.dstchannel <> '' THEN 1 ELSE 0 END) AS answered_flag
    `;
  }

  private bucketHaving(filters: CdrFilters): { having: string; replacements: Record<string, unknown> } {
    if (!filters.bucket || filters.bucketValue === undefined || filters.bucketValue === '') {
      return { having: '', replacements: {} };
    }
    const v = filters.bucketValue;
    switch (filters.bucket) {
      case 'hour':
        return { having: 'HOUR(MIN(c.calldate)) = :bucketVal', replacements: { bucketVal: parseInt(v, 10) } };
      case 'day':
        return { having: 'DATE(MIN(c.calldate)) = :bucketVal', replacements: { bucketVal: v } };
      case 'disposition':
        return {
          having: `SUBSTRING_INDEX(GROUP_CONCAT(c.disposition ORDER BY c.calldate DESC SEPARATOR '||'), '||', 1) = :bucketVal`,
          replacements: { bucketVal: v },
        };
      default:
        return { having: '', replacements: {} };
    }
  }

  private async getRecordingBaseUrl(): Promise<{ url: string; path: string }> {
    const cfg = await this.systemSettings.getServerConfigRaw();
    const baseUrl = (cfg.records_base_url || '').replace(/\/$/, '');
    const basePath = cfg.records_base_path || '/usr/records';
    return { url: baseUrl, path: basePath };
  }

  /** Same-origin stream path (v3 play.php тАФ file served via API, not RECORDS_BASE_URL). */
  recordingStreamPath(uniqueid: string): string {
    return `/reports/cdr/recording/${encodeURIComponent(uniqueid)}/play`;
  }

  private safeRecordFilePath(basePath: string, record: string): string | null {
    const rel = record.replace(/^\/+/, '').replace(/\\/g, '/');
    if (!rel || rel.includes('..')) return null;
    const baseResolved = path.resolve(basePath);
    const fileResolved = path.resolve(baseResolved, `${rel}.mp3`);
    if (!fileResolved.startsWith(baseResolved)) return null;
    return fs.existsSync(fileResolved) ? fileResolved : null;
  }

  async resolveRecordingFile(
    vpbxUserUid: number,
    uniqueid: string,
    viewerUserId?: number,
  ): Promise<{
    filePath: string;
    uniqueid: string;
    record: string;
  }> {
    await this.ensureCallVisible(vpbxUserUid, uniqueid, viewerUserId);
    const tenant = tenantLegFilter(vpbxUserUid);
    const sql = `
      SELECT record, uniqueid
      FROM cdr c
      WHERE ${tenant.sql}
        AND (c.uniqueid = :uniqueid OR c.linkedid = :uniqueid)
      ORDER BY STR_TO_DATE(c.calldate, '%Y-%m-%d %H:%i:%s') DESC
      LIMIT 1
    `;
    const [row] = await this.sequelize.query(sql, {
      replacements: { ...tenant.replacements, uniqueid },
      type: QueryTypes.SELECT,
    }) as any[];

    if (!row?.record) {
      throw new NotFoundException('Recording not found');
    }

    const { path: basePath } = await this.getRecordingBaseUrl();
    const filePath = this.safeRecordFilePath(basePath, row.record as string);
    if (!filePath) {
      throw new NotFoundException('Recording file not found');
    }

    return {
      filePath,
      uniqueid: row.uniqueid as string,
      record: row.record as string,
    };
  }

  /** Absolute stream URL (uniqueid often contains ".", so relative "play" breaks). */
  recordingPlayStreamPath(uniqueid: string, variant: 'public' | 'auth'): string {
    const id = encodeURIComponent(String(uniqueid));
    const prefix =
      variant === 'public' ? '/api/public/reports/cdr/recording' : '/api/reports/cdr/recording';
    return `${prefix}/${id}/play`;
  }

