  async streamRecording(
    vpbxUserUid: number,
    uniqueid: string,
    res: Response,
    req?: Request,
  ): Promise<void> {
    const { filePath } = await this.resolveRecordingFile(
      vpbxUserUid,
      uniqueid,
      this.viewerIdFromReq(req),
    );
    let fileSize: number;
    try {
      fileSize = (await fs.promises.stat(filePath)).size;
    } catch {
      throw new NotFoundException('Recording file not found');
    }

    const download = req?.query?.download === '1' || req?.query?.download === 'true';
    const safeName = String(uniqueid).replace(/[^\w.-]+/g, '_');
    const disposition = download
      ? `attachment; filename="${safeName}.mp3"`
      : 'inline';

    res.setHeader('Content-Type', 'audio/mpeg');
    res.setHeader('Content-Disposition', disposition);
    res.setHeader('Accept-Ranges', 'bytes');

    const rangeHeader = req?.headers?.range;
    if (rangeHeader) {
      const match = /^bytes=(\d*)-(\d*)$/i.exec(rangeHeader.trim());
      if (!match) {
        res.status(416).setHeader('Content-Range', `bytes */${fileSize}`);
        res.end();
        return;
      }

      let start: number;
      let end: number;

      if (match[1] === '' && match[2]) {
        const suffix = parseInt(match[2], 10);
        start = Math.max(fileSize - suffix, 0);
        end = fileSize - 1;
      } else {
        start = match[1] ? parseInt(match[1], 10) : 0;
        end = match[2] ? parseInt(match[2], 10) : fileSize - 1;
      }

      if (Number.isNaN(start) || Number.isNaN(end) || start > end || start >= fileSize) {
        res.status(416).setHeader('Content-Range', `bytes */${fileSize}`);
        res.end();
        return;
      }

      end = Math.min(end, fileSize - 1);
      const chunkSize = end - start + 1;

      res.status(206);
      res.setHeader('Content-Range', `bytes ${start}-${end}/${fileSize}`);
      res.setHeader('Content-Length', chunkSize);

      const stream = fs.createReadStream(filePath, { start, end });
      stream.on('error', () => {
        if (!res.headersSent) res.status(404).end();
      });
      stream.pipe(res);
      return;
    }

    res.setHeader('Content-Length', fileSize);
    const stream = fs.createReadStream(filePath);
    stream.on('error', () => {
      if (!res.headersSent) res.status(404).end();
    });
    stream.pipe(res);
  }

  private async enrichRows(rows: any[], vpbxUserUid: number): Promise<CdrCallSummary[]> {
    const { path: basePath } = await this.getRecordingBaseUrl();

    return rows.map((row) => {
      const direction = classifyDirection(row, vpbxUserUid);
      const srcExt =
        extractExtension(row.channel, vpbxUserUid) ||
        extractExtension(row.usrc, vpbxUserUid) ||
        row.usrc;
      const dstExt =
        extractExtension(row.dstchannel, vpbxUserUid) ||
        extractExtension(row.dst, vpbxUserUid) ||
        row.dst;
      const trunkSlug =
        extractTrunkSlug(row.channel, vpbxUserUid) ||
        extractTrunkSlug(row.dstchannel, vpbxUserUid);

      let srcDisplay = srcExt || row.usrc || row.src || '';
      let dstDisplay = dstExt || row.dst || '';
      if (trunkSlug && direction === 'out') {
        dstDisplay = trunkSlug;
      }
      if (row.dialednum && direction === 'in') {
        dstDisplay = dstDisplay || row.dialednum;
      }

      const record = row.record as string | null;
      let recordingUrl: string | null = null;
      let hasRecording = false;
      if (record) {
        const filePath = this.safeRecordFilePath(basePath, record);
        if (filePath) {
          hasRecording = true;
          recordingUrl = this.recordingStreamPath(row.uniqueid as string);
        }
      }

      return {
        linkedid: row.linkedid,
        uniqueid: row.uniqueid,
        calldate: row.calldate,
        clid: row.clid,
        src: row.src || row.usrc,
        usrc: row.usrc,
        dst: row.dst,
        dialednum: row.dialednum,
        disposition: row.disposition,
        dstchannel: shortenChannel(row.dstchannel),
        duration: Number(row.duration) || 0,
        billsec: Number(row.billsec) || 0,
        record,
        transid: row.transid,
        dcontext: row.dcontext,
        legCount: Number(row.leg_count) || 1,
        answered: Number(row.answered_flag) === 1 || isAnswered(row.disposition, row.dstchannel),
        direction,
        srcDisplay,
        dstDisplay,
        recordingUrl,
        hasRecording,
      };
    });
  }

  async findCalls(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const { having, replacements: havingRepl } = this.bucketHaving(filters);
    const limit = filters.limit ?? 50;
    const offset = filters.offset ?? 0;

    const havingClause = having ? `HAVING ${having}` : '';

    const countSql = `
      SELECT COUNT(*) AS cnt FROM (
        SELECT c.linkedid
        FROM cdr c
        WHERE ${where}
        GROUP BY c.linkedid
        ${havingClause}
      ) AS grouped
    `;

    const countRows = await this.sequelize.query(countSql, {
      replacements: { ...replacements, ...havingRepl },
      type: QueryTypes.SELECT,
    });
    const count = Number((countRows[0] as any)?.cnt) || 0;

    const listSql = `
      SELECT ${this.summarySelect()}
      FROM cdr c
      WHERE ${where}
      GROUP BY c.linkedid
      ${havingClause}
      ORDER BY STR_TO_DATE(MIN(c.calldate), '%Y-%m-%d %H:%i:%s') DESC
      LIMIT :limit OFFSET :offset
    `;

    const rows = await this.sequelize.query(listSql, {
      replacements: { ...replacements, ...havingRepl, limit, offset },
      type: QueryTypes.SELECT,
    });

    const enriched = await this.enrichRows(rows as any[], vpbxUserUid);
    return { rows: enriched, count };
  }

  async findLegs(vpbxUserUid: number, linkedid: string, viewerUserId?: number) {
    await this.ensureCallVisible(vpbxUserUid, linkedid, viewerUserId);
    const tenant = tenantLegFilter(vpbxUserUid);
    const sql = `
      SELECT calldate, usrc, src, clid, dst, channel, dstchannel, disposition,
             duration, billsec, uniqueid, transid, record, dcontext, lastapp
      FROM cdr c
      WHERE ${tenant.sql}
        AND c.lastapp <> 'Transferred Call'
        AND (c.linkedid = :linkedid OR c.uniqueid = :linkedid OR c.transid = :linkedid)
      ORDER BY STR_TO_DATE(c.calldate, '%Y-%m-%d %H:%i:%s') ASC
    `;
    const rows = await this.sequelize.query(sql, {
      replacements: { ...tenant.replacements, linkedid },
      type: QueryTypes.SELECT,
    });
    return (rows as any[]).map((row) => ({
      ...row,
      dstchannel: shortenChannel(row.dstchannel),
      srcDisplay:
        extractExtension(row.channel, vpbxUserUid) ||
        extractExtension(row.usrc, vpbxUserUid) ||
        row.usrc,
      dstDisplay:
        extractExtension(row.dstchannel, vpbxUserUid) ||
        extractExtension(row.dst, vpbxUserUid) ||
        row.dst,
      answered: isAnswered(row.disposition, row.dstchannel),
    }));
  }

  async getStats(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const sql = `
      SELECT
        COUNT(DISTINCT c.linkedid) AS totalCalls,
        SUM(CASE WHEN c.disposition = 'ANSWERED' AND c.dstchannel <> '' THEN 1 ELSE 0 END) AS answeredLegs,
        COUNT(*) AS totalLegs,
        AVG(c.billsec) AS avgBillsec,
        AVG(CASE WHEN c.disposition = 'ANSWERED' AND c.billsec > 0 THEN c.duration - c.billsec ELSE NULL END) AS avgPdd
      FROM cdr c
      WHERE ${where}
    `;
    const [row] = await this.sequelize.query(sql, {
      replacements,
      type: QueryTypes.SELECT,
    }) as any[];

    const totalCalls = Number(row?.totalCalls) || 0;
    const answeredLegs = Number(row?.answeredLegs) || 0;
    const totalLegs = Number(row?.totalLegs) || 0;

    const dispSql = `
      SELECT disposition, COUNT(DISTINCT linkedid) AS cnt
      FROM (
        SELECT c.linkedid,
          SUBSTRING_INDEX(GROUP_CONCAT(c.disposition ORDER BY c.calldate DESC SEPARATOR '||'), '||', 1) AS disposition
        FROM cdr c
        WHERE ${where}
        GROUP BY c.linkedid
      ) t
      GROUP BY disposition
    `;
    const dispRows = await this.sequelize.query(dispSql, {
      replacements,
      type: QueryTypes.SELECT,
    }) as any[];

    const byDisposition: Record<string, number> = {};
    for (const d of dispRows) {
      byDisposition[d.disposition] = Number(d.cnt);
    }

    return {
      totalCalls,
      asr: totalLegs > 0 ? Math.round((answeredLegs / totalLegs) * 100) : 0,
      avgBillsec: Math.round(Number(row?.avgBillsec) || 0),
      avgPdd: Math.round(Number(row?.avgPdd) || 0),
      byDisposition,
    };
  }

  async getByHour(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const rows = await this.sequelize.query(`
      SELECT hr AS hour, COUNT(*) AS calls,
        SUM(ans) AS answered,
        COUNT(*) - SUM(ans) AS missed
      FROM (
        SELECT c.linkedid, HOUR(MIN(c.calldate)) AS hr,
          MAX(CASE WHEN c.disposition='ANSWERED' AND c.dstchannel<>'' THEN 1 ELSE 0 END) AS ans
        FROM cdr c
        WHERE ${where}
        GROUP BY c.linkedid, HOUR(c.calldate)
      ) t
      GROUP BY hr
      ORDER BY hr
    `, { replacements, type: QueryTypes.SELECT });
    return rows;
  }

  async getByDay(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const sql = `
      SELECT DATE(MIN(c.calldate)) AS day,
        COUNT(DISTINCT c.linkedid) AS calls,
        SUM(c.billsec) AS totalBillsec,
        AVG(c.billsec) AS avgBillsec,
        MAX(CASE WHEN c.disposition='ANSWERED' AND c.dstchannel<>'' THEN 1 ELSE 0 END) AS ans_flag
      FROM cdr c
      WHERE ${where}
      GROUP BY c.linkedid, DATE(c.calldate)
    `;
    const rows = await this.sequelize.query(`
      SELECT day, COUNT(*) AS calls,
        SUM(totalBillsec) AS totalBillsec,
        ROUND(AVG(avgBillsec)) AS avgBillsec,
        SUM(ans_flag) AS answered,
        COUNT(*) - SUM(ans_flag) AS missed,
        ROUND(SUM(ans_flag) / COUNT(*) * 100) AS asr
      FROM (
        SELECT DATE(MIN(c.calldate)) AS day, c.linkedid,
          MAX(c.billsec) AS totalBillsec,
          AVG(c.billsec) AS avgBillsec,
          MAX(CASE WHEN c.disposition='ANSWERED' AND c.dstchannel<>'' THEN 1 ELSE 0 END) AS ans_flag
        FROM cdr c
        WHERE ${where}
        GROUP BY c.linkedid, DATE(c.calldate)
      ) t
      GROUP BY day
      ORDER BY day
    `, { replacements, type: QueryTypes.SELECT });
    return rows;
  }

  async getByExtension(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const endpoints = await this.endpointModel.findAll({
      where: { tenantid: String(vpbxUserUid) },
      attributes: ['id', 'callerid'],
    });
    const extMap = new Map<string, string>();
    for (const ep of endpoints) {
      if (ep.id.startsWith('e')) {
        const m = ep.id.match(/^e(.+)_\d+$/);
        if (m) extMap.set(m[1], ep.callerid || m[1]);
      }
    }

    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const extLikeSuffix = `_%_${vpbxUserUid}`;
    const rows = await this.sequelize.query(`
      SELECT ext, COUNT(*) AS total,
        SUM(inbound) AS inbound,
        SUM(outbound) AS outbound,
        SUM(answered) AS answered
      FROM (
        SELECT
          CASE
            WHEN CHAR_LENGTH(c.usrc) <= 4 THEN c.usrc
            WHEN c.usrc LIKE CONCAT('e%', :extLikeSuffix) THEN SUBSTRING(c.usrc, 2, LOCATE('_', c.usrc) - 2)
            ELSE NULL
          END AS ext,
          CASE WHEN c.dialednum <> '' AND c.dialednum IS NOT NULL THEN 1 ELSE 0 END AS inbound,
          CASE WHEN c.dcontext LIKE :outCtx THEN 1 ELSE 0 END AS outbound,
          CASE WHEN c.disposition='ANSWERED' AND c.dstchannel<>'' THEN 1 ELSE 0 END AS answered
        FROM cdr c
        WHERE ${where}
      ) legs
      WHERE ext IS NOT NULL
      GROUP BY ext
      ORDER BY total DESC
      LIMIT 20
    `, {
      replacements: { ...replacements, outCtx: `sip-out${vpbxUserUid}%`, extLikeSuffix },
      type: QueryTypes.SELECT,
    }) as any[];

    return rows.map((r) => ({
      extension: r.ext,
      displayName: extMap.get(r.ext) || r.ext,
      total: Number(r.total),
      inbound: Number(r.inbound),
      outbound: Number(r.outbound),
      answered: Number(r.answered),
      asr: Number(r.total) > 0 ? Math.round((Number(r.answered) / Number(r.total)) * 100) : 0,
    }));
  }

  async getByTrunk(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const rows = await this.sequelize.query(`
      SELECT COALESCE(dialednum, 'unknown') AS trunk,
        COUNT(DISTINCT linkedid) AS calls,
        SUM(billsec) AS totalBillsec
      FROM (
        SELECT c.linkedid, MAX(c.dialednum) AS dialednum, MAX(c.billsec) AS billsec
        FROM cdr c
        WHERE ${where} AND c.dialednum IS NOT NULL AND c.dialednum <> ''
        GROUP BY c.linkedid
      ) t
      GROUP BY trunk
      ORDER BY calls DESC
      LIMIT 20
    `, { replacements, type: QueryTypes.SELECT });
    return rows;
  }

  async getByDisposition(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const stats = await this.getStats(vpbxUserUid, filters, viewerUserId);
    return Object.entries(stats.byDisposition).map(([disposition, count]) => ({
      disposition,
      count,
    }));
  }

  async getHeatmap(vpbxUserUid: number, filters: CdrFilters, viewerUserId?: number) {
    const { where, replacements } = await this.applyFilters(vpbxUserUid, filters, viewerUserId);
    const rows = await this.sequelize.query(`
      SELECT DAYOFWEEK(MIN(c.calldate)) AS dow, HOUR(MIN(c.calldate)) AS hour,
        COUNT(DISTINCT c.linkedid) AS calls
      FROM cdr c
      WHERE ${where}
      GROUP BY c.linkedid, DAYOFWEEK(c.calldate), HOUR(c.calldate)
    `, { replacements, type: QueryTypes.SELECT }) as any[];

    const matrix: Record<string, number> = {};
    for (const r of rows) {
      const key = `${r.dow}-${r.hour}`;
      matrix[key] = (matrix[key] || 0) + Number(r.calls);
    }
    const result: { dow: number; hour: number; calls: number }[] = [];
    for (const [key, calls] of Object.entries(matrix)) {
      const [dow, hour] = key.split('-').map(Number);
      result.push({ dow, hour, calls });
    }
    return result;
  }

  async findByUniqueid(vpbxUserUid: number, uniqueid: string, viewerUserId?: number) {
    await this.ensureCallVisible(vpbxUserUid, uniqueid, viewerUserId);
    const tenant = tenantLegFilter(vpbxUserUid);
    const sql = `
      SELECT record, uniqueid, linkedid, userfield
      FROM cdr c
      WHERE ${tenant.sql}
        AND (c.uniqueid = :uniqueid OR c.linkedid = :uniqueid)
      ORDER BY STR_TO_DATE(c.calldate, '%Y-%m-%d %H:%i:%s') DESC
      LIMIT 1
    `;
    const [row] = await this.sequelize.query(sql, {
      replacements: { ...tenant.replacements, uniqueid },
      type: QueryTypes.SELECT,
    }) as any[];

    if (!row) {
      throw new NotFoundException('CDR record not found');
    }

    const { path: basePath } = await this.getRecordingBaseUrl();
    const record = row.record as string | null;
    let recordingUrl: string | null = null;
    let exists = false;

    if (record) {
      const filePath = this.safeRecordFilePath(basePath, record);
      exists = Boolean(filePath);
      if (exists) {
        recordingUrl = this.recordingStreamPath(row.uniqueid as string);
      }
    }

    return { record, uniqueid: row.uniqueid, linkedid: row.linkedid, recordingUrl, exists };
  }

  async exportCalls(
    vpbxUserUid: number,
    filters: CdrFilters,
    viewerUserId?: number,
  ): Promise<CdrCallSummary[]> {
    const result = await this.findCalls(vpbxUserUid, {
      ...filters,
      limit: 10000,
      offset: 0,
    }, viewerUserId);
    return result.rows;
  }
}

import { liftDialTargetRewrite } from '@krasterisk/shared';

/**
 * Pure Phase-12 dialplan action rewrite (D-12 / D-20 / D-28 / D-51 / D-29).
 * No Sequelize, no I/O тАФ the standalone script walks rows and calls this.
 */

export const USE_EXTEN_SENTINEL = '__USE_EXTEN__';

/**
 * `sendmail` / `sendmailpeer` / `telegram` are here because notify now routes
 * through a notification integration: there is no integration uid to infer from
 * a bare address, so folding them would produce rows that fail validation.
 */
export const UNMAPPED_HARD_REMOVE = new Set([
  'tofax', 'asr', 'keywords',
  'sendmail', 'sendmailpeer', 'telegram',
]);

const KNOWN_TYPES = new Set([
  'totrunk', 'toexten', 'toqueue', 'togroup', 'tolist',
  'toivr', 'toroute', 'playprompt', 'playback', 'background',
  'setclid_custom', 'setclid_list',
  'notify', 'callerid',
  'voicemail', 'text2speech', 'voicerobot',
  'webhook', 'confbridge', 'cmd',
  'label', 'busy', 'hangup', 'congestion',
  'goto', 'branch', 'schedule', 'http_request', 'collect_input',
]);

const ADDRESS_STRING_FIELDS: Record<string, { from: string; to: string; useExtenField?: string }> = {
  toqueue: { from: 'queue', to: 'target' },
  toexten: { from: 'exten', to: 'target', useExtenField: 'useExten' },
  togroup: { from: 'group', to: 'target' },
  voicemail: { from: 'exten', to: 'target' },
  totrunk: { from: 'dest', to: 'dest' },
  toroute: { from: 'context', to: 'context' },
  confbridge: { from: 'room', to: 'room' },
};

export interface MigrateActionResult {
  action: unknown;
  changed: boolean;
  unmapped?: string;
}

/** D-54 default Record() max seconds when a stored voicemail step has no duration. */
export const VOICEMAIL_DEFAULT_MAX_DURATION = 120;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isValueSource(value: unknown): boolean {
  return isPlainObject(value) && typeof value.source === 'string';
}

function isRoutePatternToken(value: string): boolean {
  return value === USE_EXTEN_SENTINEL || value === '' || value === '${EXTEN}';
}

function toValueSource(raw: unknown, useExten?: unknown): { source: string; value?: string } {
  if (useExten) return { source: 'route_pattern' };
  if (typeof raw === 'string') {
    return isRoutePatternToken(raw) ? { source: 'route_pattern' } : { source: 'fixed', value: raw };
  }
  return { source: 'route_pattern' };
}

function liftAddressFields(
  type: string,
  params: Record<string, unknown>,
): { params: Record<string, unknown>; changed: boolean } {
  const spec = ADDRESS_STRING_FIELDS[type];
  if (!spec) return { params, changed: false };

  const current = params[spec.to];
  if (isValueSource(current)) {
    const next = { ...params };
    let changed = false;
    if (spec.from !== spec.to && spec.from in next) {
      delete next[spec.from];
      changed = true;
    }
    if (spec.useExtenField && spec.useExtenField in next) {
      delete next[spec.useExtenField];
      changed = true;
    }
    return { params: next, changed };
  }

  const fromVal = spec.from in params ? params[spec.from] : current;
  const useExten = spec.useExtenField ? params[spec.useExtenField] : undefined;
  const hasLegacy =
    spec.from in params
    || (typeof current === 'string')
    || Boolean(useExten);

  if (!hasLegacy && current !== undefined && current !== null) {
    return { params, changed: false };
  }

  if (!hasLegacy && current === undefined) {
    return { params, changed: false };
  }

  const next = { ...params };
  next[spec.to] = toValueSource(fromVal ?? current, useExten);
  if (spec.from !== spec.to) delete next[spec.from];
  if (spec.useExtenField) delete next[spec.useExtenField];
  return { params: next, changed: true };
}

/**
 * Types merged into a single app with a discriminator param: busy/congestion
 * into hangup(signal), branch into goto(condition), setclid_* into
 * callerid(mode).
 */
function foldMergedTypes(
  type: string,
  params: Record<string, unknown>,
): { type: string; params: Record<string, unknown>; changed: boolean } | null {
  if (type === 'busy' || type === 'congestion') {
    return { type: 'hangup', params: { ...params, signal: type }, changed: true };
  }
  if (type === 'hangup' && params.signal == null) {
    return { type: 'hangup', params: { ...params, signal: 'hangup' }, changed: true };
  }
  if (type === 'branch') {
    const { true_label, ...rest } = params;
    return {
      type: 'goto',
      params: { ...rest, label_name: true_label ?? params.label_name ?? '' },
      changed: true,
    };
  }
  if (type === 'setclid_custom') {
    const { mode, ...rest } = params;
    return { type: 'callerid', params: { ...rest, mode: 'static' }, changed: true };
  }
  if (type === 'setclid_list') {
    const { mode, ...rest } = params;
    return { type: 'callerid', params: { ...rest, mode: 'number_list' }, changed: true };
  }
  if (type === 'callerid' && params.mode === 'setclid_list') {
    return { type: 'callerid', params: { ...params, mode: 'number_list' }, changed: true };
  }
  return null;
}

function foldPlayback(
  type: string,
  params: Record<string, unknown>,
): { type: string; params: Record<string, unknown>; changed: boolean } | null {
  if (type === 'playprompt') {
    return { type: 'playback', params: { ...params, mode: params.mode ?? 'plain' }, changed: true };
  }
  if (type === 'background') {
    return { type: 'playback', params: { ...params, mode: params.mode ?? 'menu' }, changed: true };
  }
  if (type === 'playback' && params.mode == null) {
    return { type: 'playback', params: { ...params, mode: 'control' }, changed: true };
  }
  return null;
}

function liftQueuePriority(
  type: string,
  params: Record<string, unknown>,
): { params: Record<string, unknown>; changed: boolean } {
  if (type !== 'toqueue') return { params, changed: false };
  const raw = params.priority;
  if (raw == null || raw === '') return { params, changed: false };
  if (isValueSource(raw)) return { params, changed: false };
  if (typeof raw === 'number' && Number.isFinite(raw)) {
    return {
      params: { ...params, priority: { source: 'fixed', value: String(Math.trunc(raw)) } },
      changed: true,
    };
  }
  if (typeof raw === 'string' && raw.trim() !== '') {
    const n = parseInt(raw, 10);
    if (!Number.isFinite(n)) return { params, changed: false };
    return {
      params: { ...params, priority: { source: 'fixed', value: String(n) } },
      changed: true,
    };
  }
  return { params, changed: false };
}

/**
 * D-54: expand stored `type: 'voicemail'` params without renaming the ActionType.
 * Reuses the existing extenтЖТtarget lift. Non-voicemail actions pass through.
 * Leftover keys (including a telegram channel string) are kept.
 */
export function migrateVoicemailParams(action: unknown): MigrateActionResult {
  if (!isPlainObject(action) || action.type !== 'voicemail') {
    return { action, changed: false };
  }

  const params = isPlainObject(action.params) ? { ...action.params } : {};
  const lifted = liftAddressFields('voicemail', params);
  let nextParams = lifted.params;
  let changed = lifted.changed;

  if (nextParams.max_duration == null) {
    nextParams = { ...nextParams, max_duration: VOICEMAIL_DEFAULT_MAX_DURATION };
    changed = true;
  }

  if (!changed) {
    return { action, changed: false };
  }

  return { action: { ...action, type: 'voicemail', params: nextParams }, changed: true };
}

/**
 * Rewrite one stored action onto the Phase-12 params model.
 * Unmapped hard-remove types (asr/tofax/keywords) and unknown types stay as-is.
 */
export function migrateAction(action: unknown): MigrateActionResult {
  if (!isPlainObject(action) || typeof action.type !== 'string') {
    return { action, changed: false };
  }

  const type = action.type;
  const params = isPlainObject(action.params) ? { ...action.params } : {};

  if (UNMAPPED_HARD_REMOVE.has(type)) {
    return { action, changed: false, unmapped: type };
  }

  const playback = foldPlayback(type, params);
  const merged = playback ? null : foldMergedTypes(type, params);

  let nextType = playback?.type ?? merged?.type ?? type;
  let nextParams = playback?.params ?? merged?.params ?? params;
  let changed = Boolean(playback?.changed || merged?.changed);

  const lifted = liftAddressFields(nextType, nextParams);
  nextParams = lifted.params;
  if (lifted.changed) changed = true;

  const prioLift = liftQueuePriority(nextType, nextParams);
  nextParams = prioLift.params;
  if (prioLift.changed) changed = true;

  if (nextType === 'trunk_carousel') {
    nextType = 'totrunk';
    nextParams = {
      trunkMode: 'carousel',
      ...nextParams,
    };
    changed = true;
  }

  if (['totrunk', 'toexten', 'tolist', 'toroute'].includes(nextType)) {
    const rewriteLift = liftDialTargetRewrite(nextParams);
    nextParams = rewriteLift.params;
    if (rewriteLift.changed) changed = true;
  }

  if (!changed) {
    if (!KNOWN_TYPES.has(type)) {
      return { action, changed: false, unmapped: type };
    }
    return { action, changed: false };
  }

  const nextAction = { ...action, type: nextType, params: nextParams };
  return { action: nextAction, changed: true };
}

export interface ChainMigrationResult {
  value: unknown;
  changed: boolean;
  converted: number;
  unmapped: Array<{ type: string; index: number }>;
}

/** Apply `migrateAction` to every element of an action chain (or a lone action). */
export function migrateActionChain(
  value: unknown,
  migrate: typeof migrateAction = migrateAction,
): ChainMigrationResult {
  if (value == null) {
    return { value, changed: false, converted: 0, unmapped: [] };
  }
  const items = Array.isArray(value) ? value : [value];
  const unmapped: Array<{ type: string; index: number }> = [];
  let converted = 0;
  let changed = false;
  const next = items.map((item, index) => {
    const result = migrate(item);
    if (result.unmapped) unmapped.push({ type: result.unmapped, index });
    if (result.changed) {
      converted += 1;
      changed = true;
    }
    return result.action;
  });
  return {
    value: Array.isArray(value) ? next : next[0],
    changed,
    converted,
    unmapped,
  };
}

import { Controller, Post, Body, Query, Get, HttpCode, Logger, UnauthorizedException, Headers } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { DialplanWebhooksService } from './dialplan-webhooks.service';

/**
 * Internal endpoints for Asterisk dialplan webhook integration.
 * Called via CURL() from Asterisk dialplan тАФ no JWT auth.
 * Uses shared API key (DIALPLAN_API_KEY env) for basic authentication.
 *
 * All endpoints live under /api/internal/dialplan/
 *
 * Asterisk dialplan usage examples:
 *
 *   Custom webhook (DIALTO):
 *     Set(__DIALTO=${CURL(http://127.0.0.1:5010/api/internal/dialplan/custom-webhook,
 *       route_uid=${HH_ROUTE_UID}&uniqueid=${UNIQUEID}&clid=${CALLERID(num)}&user_uid=42)})
 *
 *   Before dial:
 *     Set(WH_BD_RESULT=${CURL(http://127.0.0.1:5010/api/internal/dialplan/before-dial,
 *       route_uid=${HH_ROUTE_UID}&uniqueid=${UNIQUEID}&clid=${CALLERID(num)}&exten=${EXTEN}&user_uid=42)})
 *
 *   On answer (via [krsk-on-answer] subroutine):
 *     Set(CURL_OA=${CURL(http://127.0.0.1:5010/api/internal/dialplan/on-answer,
 *       route_uid=${HH_ROUTE_UID}&uniqueid=${UNIQUEID}&clid=${CALLERID(num)}&member=${DIALEDPEERNUMBER}&source=dial&user_uid=42)})
 *
 *   On hangup (via [krsk-hangup-handler] subroutine):
 *     Set(CURL_HH=${CURL(http://127.0.0.1:5010/api/internal/dialplan/on-hangup,
 *       route_uid=${HH_ROUTE_UID}&uniqueid=${UNIQUEID}&clid=${CALLERID(num)}&duration=${CDR(billsec)}&disposition=${CDR(disposition)}&record_path=${CDR(record)}&user_uid=42)})
 */
@Controller('internal/dialplan')
export class DialplanWebhooksController {
  private readonly logger = new Logger(DialplanWebhooksController.name);
  private readonly apiKey: string;

  constructor(
    private readonly webhooksService: DialplanWebhooksService,
    private readonly config: ConfigService,
  ) {
    this.apiKey = this.config.get<string>('DIALPLAN_API_KEY') || '';
  }

  // ---------------------------------------------------------------------------
  // Custom webhook тАФ synchronous, returns responsible extension (plain text)
  // Asterisk: Set(__DIALTO=${CURL(...)})
  // ---------------------------------------------------------------------------
  @Post('custom-webhook')
  @HttpCode(200)
  async customWebhook(
    @Headers('x-api-key') headerKey: string,
    @Body() body: Record<string, string>,
  ): Promise<string> {
    this.validateKey(headerKey || body.api_key);
    const { route_uid, uniqueid, clid, user_uid } = body;
    if (!route_uid || !user_uid) return '';

    return this.webhooksService.handleCustomWebhook({ route_uid, uniqueid, clid, user_uid });
  }

  // ---------------------------------------------------------------------------
  // Before dial тАФ synchronous, CRM registers incoming call
  // ---------------------------------------------------------------------------
  @Post('before-dial')
  @HttpCode(200)
  async beforeDial(
    @Headers('x-api-key') headerKey: string,
    @Body() body: Record<string, string>,
  ): Promise<string> {
    this.validateKey(headerKey || body.api_key);
    const { route_uid, uniqueid, clid, exten, user_uid } = body;
    if (!route_uid || !user_uid) return 'ok';

    await this.webhooksService.handleBeforeDial({ route_uid, uniqueid, clid, exten: exten || '', user_uid });
    return 'ok';
  }

  // ---------------------------------------------------------------------------
  // On answer тАФ Asterisk gets "ok" immediately, CRM delivery is async with retry
  // Called from [krsk-on-answer] subroutine (Dial U() option)
  // ---------------------------------------------------------------------------
  @Post('on-answer')
  @HttpCode(200)
  async onAnswer(
    @Headers('x-api-key') headerKey: string,
    @Body() body: Record<string, string>,
  ): Promise<string> {
    this.validateKey(headerKey || body.api_key);
    const { route_uid, uniqueid, clid, member, source, user_uid } = body;
    if (!route_uid || !user_uid) return 'ok';

    // Do not await тАФ fire and forget, Asterisk must not be blocked
    void this.webhooksService.handleOnAnswer({ route_uid, uniqueid, clid, member: member || '', source: source || 'dial', user_uid });
    return 'ok';
  }

  // ---------------------------------------------------------------------------
  // On hangup тАФ Asterisk gets "ok" immediately, delivery is async with retry
  // Called from [krsk-hangup-handler] тАФ MP3 is guaranteed ready at this point
  // ---------------------------------------------------------------------------
  @Post('on-hangup')
  @HttpCode(200)
  async onHangup(
    @Headers('x-api-key') headerKey: string,
    @Body() body: Record<string, string>,
  ): Promise<string> {
    this.validateKey(headerKey || body.api_key);
    const { route_uid, uniqueid, clid, duration, disposition, record_path, user_uid } = body;
    if (!route_uid || !user_uid) return 'ok';

    void this.webhooksService.handleOnHangup({
      route_uid, uniqueid, clid,
      duration: duration || '0',
      disposition: disposition || 'UNKNOWN',
      record_path: record_path || '',
      user_uid,
    });
    return 'ok';
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------
  private validateKey(provided?: string): void {
    if (this.apiKey && provided !== this.apiKey) {
      this.logger.warn('Unauthorized internal dialplan request');
      throw new UnauthorizedException('Invalid API key');
    }
  }
}

import {
  IsArray,
  IsBoolean,
  IsDefined,
  IsIn,
  IsInt,
  IsOptional,
  IsString,
  Matches,
  Max,
  Min,
  MinLength,
  Validate,
  ValidateIf,
  ValidateNested,
} from 'class-validator';
import { Transform, Type } from 'class-transformer';
import type {
  IToIvrParams,
  IToListParams,
} from '@krasterisk/shared';
import { coerceDestValueSource } from '@krasterisk/shared';
import { IsValueSourceConstraint, IsQueuePrioritySourceConstraint, ValueSourceDto } from './value-source.dto';
import { NotifyParamsDto } from './integration.params.dto';

const SAFE_DIAL = /^[^(),?\[\]{}$\\";\n\r]*$/;
const PREPEND_DIGITS = /^[0-9+]*$/;
/** Prompt identifier only тАФ no path, no absolute file (T-13-09). */
const SAFE_GREETING = /^[A-Za-z0-9._-]*$/;

export class NumberManipulationDto {
  @IsOptional()
  @IsInt()
  @Min(0)
  strip?: number;

  @IsOptional()
  @IsString()
  @Matches(PREPEND_DIGITS)
  prepend?: string;
}

const REWRITE_KINDS = ['eq', 'startsWith', 'endsWith', 'length', 'digitMask', 'regex'] as const;

export class DialRewriteConditionDto {
  @IsIn(REWRITE_KINDS)
  kind: (typeof REWRITE_KINDS)[number];

  @IsOptional()
  @IsString()
  value?: string;

  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(64)
  min?: number;

  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(64)
  max?: number;
}

export class DialRewriteTransformDto {
  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  replaceAll?: string;

  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(32)
  stripStartCount?: number;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  stripStartText?: string;

  @IsOptional()
  @IsInt()
  @Min(0)
  @Max(32)
  stripEndCount?: number;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  stripEndText?: string;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  replaceFind?: string;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  replaceWith?: string;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  prefix?: string;

  @IsOptional()
  @IsString()
  @Matches(/^[0-9A-Za-z+*#]*$/)
  postfix?: string;
}

export class DialRewriteRuleDto {
  @IsString()
  @MinLength(1)
  id: string;

  @IsOptional()
  @IsBoolean()
  enabled?: boolean;

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => DialRewriteConditionDto)
  conditions?: DialRewriteConditionDto[];

  @ValidateNested()
  @Type(() => DialRewriteTransformDto)
  transform: DialRewriteTransformDto;
}

export class DialTargetRewriteDto {
  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => DialRewriteRuleDto)
  rules?: DialRewriteRuleDto[];

  @IsOptional()
  @IsIn(['passthrough', 'reject'])
  noMatch?: 'passthrough' | 'reject';
}

/**
 * ConfBridge params: the room is chosen from tenant conference rooms.
 * The bridge-profile name lives in the conferences module, not in step params.
 */
export class ConfBridgeParamsDto {
  @IsDefined()
  @ValidateNested()
  @Type(() => ValueSourceDto)
  room: ValueSourceDto;
}

export class ToExtenParamsDto {
  @IsDefined()
  @ValidateNested()
  @Type(() => ValueSourceDto)
  target: ValueSourceDto;

  /** Read by the generator; selects transport in pjsipDialTarget. Revived, not removed (D-39). */
  @IsOptional()
  @IsBoolean()
  webrtc?: boolean;

  @IsOptional()
  @Transform(({ value }) => (value === '' || value == null ? undefined : Number(value)))
  @IsInt()
  @Min(1)
  timeout?: number;

  @IsOptional()
  @IsString()
  @Matches(SAFE_DIAL)
  options?: string;

  @IsOptional()
  @IsString()
  exten?: string;

  @IsOptional()
  @IsBoolean()
  useExten?: boolean;

  @IsOptional()
  @ValidateNested()
  @Type(() => NumberManipulationDto)
  numberManipulation?: NumberManipulationDto;

  @IsOptional()
  @ValidateNested()
  @Type(() => DialTargetRewriteDto)
  rewrite?: DialTargetRewriteDto;
}

export class ToQueueParamsDto {
  @IsOptional()
  @ValidateNested()
  @Type(() => ValueSourceDto)
  @Validate(IsValueSourceConstraint)
  target?: ValueSourceDto;

  @IsOptional()
  @Transform(({ value }) => (value === '' || value == null ? undefined : Number(value)))
  @IsInt()
  @Min(1)
  timeout?: number;

  @IsOptional()
  @IsString()
  options?: string;

  /** @deprecated Wave 0 field тАФ accepted when `target` is absent */
  @IsOptional()
  @IsString()
  queue?: string;

  /** VIP skip of the queue tail тАФ Set(QUEUE_PRIO=тАж) before Queue() (D-32). ValueSource or legacy number. */
  @IsOptional()
  @Transform(({ value }) => {
    if (value === '' || value == null) return undefined;
    if (typeof value === 'number' && Number.isFinite(value)) {
      return { source: 'fixed', value: String(Math.trunc(value)) };
    }
    if (typeof value === 'string' && value.trim() !== '') {
      const n = parseInt(value, 10);
      if (!Number.isFinite(n)) return value;
      return { source: 'fixed', value: String(n) };
    }
    return value;
  })
  @Validate(IsQueuePrioritySourceConstraint)
  priority?: ValueSourceDto;

  /** 4th Queue() argument; prompt id only, never a path (T-12-13-02). */
  @IsOptional()
  @IsString()
  @Matches(/^(?!.*\.\.)[^\\/]*$/)
  announceoverride?: string;
}

export class ToGroupParamsDto {
  @IsOptional()
  @ValidateNested()
  @Type(() => ValueSourceDto)
  target?: ValueSourceDto;

  @IsOptional()
  @IsString()
  @Matches(SAFE_DIAL)
  group?: string;

  @IsOptional()
  @ValidateNested()
  @Type(() => NumberManipulationDto)
  numberManipulation?: NumberManipulationDto;
}

export class ToListParamsDto implements IToListParams {
  @IsOptional()
  @IsString()
  @Matches(/^[^()?\[\]{}$\\";\n\r]*$/)
  numbers?: string;

