const SAFE_DIAL = /^[^(),?\[\]{}$\\";\n\r]*$/;
const SAFE_TEXT = /^[^\n\r;]*$/;
const CALLERID_MODES: CallerIdMode[] = ['static', 'directory', 'number_list', 'carousel'];
const HANGUP_SIGNALS: HangupSignal[] = ['busy', 'congestion', 'hangup'];
