@Injectable()
export class TrunksService {
  private readonly logger = new Logger(TrunksService.name);

  constructor(
    @InjectModel(PsEndpoint) private endpointModel: typeof PsEndpoint,
    @InjectModel(PsAuth) private authModel: typeof PsAuth,
    @InjectModel(PsAor) private aorModel: typeof PsAor,
    @InjectModel(PsRegistration) private registrationModel: typeof PsRegistration,
    @InjectModel(PsEndpointIdIp) private endpointIdIpModel: typeof PsEndpointIdIp,
    private sequelize: Sequelize,
    private amiService: AmiService,
    private loggerService: LoggerService,
  ) {}

  /** Build a unique trunk ID: t_{name}_{tenantId} */
  private buildTrunkId(name: string, vpbxUserUid: number): string {
    const slug = name.toLowerCase().replace(/[^a-z0-9_-]/g, '_');
    return `t_${slug}_${vpbxUserUid}`;
  }

  /** Build default context for incoming trunk calls */
  private buildContext(context: string | undefined, vpbxUserUid: number): string {
    const base = context || 'from-trunk';
    const suffix = String(vpbxUserUid);
    if (base.endsWith(suffix)) return base;
    return `${base}${suffix}`;
  }

  /**
   * Get all trunks for a tenant.
   * Trunks are identified by tenantid prefix in the endpoint id.
   */
  async findAll(vpbxUserUid: number) {
    const tenantStr = String(vpbxUserUid);

    // Get all endpoints that are trunks (prefixed with 't_')
    const endpoints = await this.endpointModel.findAll({
      where: { tenantid: tenantStr },
      order: [['id', 'ASC']],
    });

    // Filter only trunk endpoints (id starts with 't_')
    const trunkEndpoints = endpoints.filter((ep) => ep.id.startsWith('t_'));
    const trunkIds = trunkEndpoints.map((ep) => ep.id);

    // Load related data in parallel
    const [auths, registrations, idIps, aors] = await Promise.all([
      trunkIds.length
        ? this.authModel.findAll({ where: { id: trunkIds } })
        : [],
      trunkIds.length
        ? this.registrationModel.findAll({ where: { id: trunkIds } })
        : [],
      trunkIds.length
        ? this.endpointIdIpModel.findAll({ where: { endpoint: trunkIds } })
        : [],
      trunkIds.length
        ? this.aorModel.findAll({ where: { id: trunkIds } })
        : [],
    ]);

    const authMap = new Map(auths.map((a) => [a.id, a]));
    const regMap = new Map(registrations.map((r) => [r.id, r]));
    const aorMap = new Map(aors.map((a) => [a.id, a]));
    const ipMap = new Map<string, string[]>();
    for (const ip of idIps) {
      if (!ip.endpoint || !ip.match) continue;
      const list = ipMap.get(ip.endpoint) ?? [];
      list.push(ip.match);
      ipMap.set(ip.endpoint, list);
    }

    // Try to get live registration statuses from AMI
    let regStatuses = new Map<string, string>();
    try {
      if (this.amiService.isConnected()) {
        const result = await this.amiService.pjsipShowRegistrations();
        if (result && Array.isArray(result.events)) {
          result.events.forEach((evt: any) => {
            if (evt.event === 'OutboundRegistrationDetail') {
              regStatuses.set(evt.objectname || '', evt.status || '');
            }
          });
        }
      }
    } catch (e) {
      this.logger.warn('Could not fetch registration statuses from AMI');
    }

    return trunkEndpoints.map((ep) => {
      const auth = authMap.get(ep.id);
      const reg = regMap.get(ep.id);
      const trunkType = reg ? 'auth' : 'ip';
      const liveStatus = regStatuses.get(ep.id) || null;

      return {
        id: ep.id,
        name: this.extractTrunkName(ep.id, vpbxUserUid),
        trunkType,
        host: reg?.server_uri?.replace('sip:', '').split('@').pop() || ipMap.get(ep.id)?.[0] || '',
        context: this.stripContext(ep.context, vpbxUserUid),
        transport: ep.transport || '',
        codecs: ep.allow || '',
        username: auth?.username || '',
        fromUser: ep.from_user || '',
        fromDomain: ep.from_domain || '',
        contactUser: reg?.contact_user || '',
        matchIp: (ipMap.get(ep.id) ?? []).join(', '),
        qualifyFrequency: aorMap.get(ep.id)?.qualify_frequency ?? DEFAULT_QUALIFY_FREQUENCY,
        registrationExpiration: reg?.expiration ?? null,
        registrationStatus: trunkType === 'auth' ? (liveStatus || 'unknown') : null,
        serverUri: reg?.server_uri || '',
        clientUri: reg?.client_uri || '',
      };
    });
  }

  /**
   * Get a single trunk by its trunk ID.
   */
  async findOne(trunkId: string, vpbxUserUid: number) {
    const endpoint = await this.endpointModel.findOne({
      where: { id: trunkId, tenantid: String(vpbxUserUid) },
    });
    if (!endpoint || !trunkId.startsWith('t_')) {
      throw new NotFoundException('Trunk not found');
    }

    const [auth, aor, reg, idIp] = await Promise.all([
      this.authModel.findByPk(trunkId),
      this.aorModel.findByPk(trunkId),
      this.registrationModel.findByPk(trunkId),
      this.endpointIdIpModel.findOne({ where: { endpoint: trunkId } }),
    ]);

    const trunkType = reg ? 'auth' : 'ip';

    return {
      id: endpoint.id,
      name: this.extractTrunkName(trunkId, vpbxUserUid),
      trunkType,
      endpoint: endpoint.toJSON(),
      auth: auth ? { ...auth.toJSON(), password: '********' } : null,
      aor: aor?.toJSON() || null,
      registration: reg?.toJSON() || null,
      identify: idIp?.toJSON() || null,
    };
  }

  /**
   * Create an Auth-type trunk.
   * Creates: ps_auths, ps_aors, ps_endpoints, ps_registrations.
   * Then triggers AMI PJSIPRegister to initiate outbound registration.
   */
  async createAuthTrunk(dto: CreateTrunkDto, vpbxUserUid: number, userId?: number) {
    const trunkId = this.buildTrunkId(dto.name, vpbxUserUid);
    await this.ensureUnique(trunkId);

    const context = this.buildContext(dto.context, vpbxUserUid);
    const serverUri = `sip:${dto.host}${dto.port ? `:${dto.port}` : ''}`;
    const clientUriDomain = dto.fromDomain || `${dto.host}${dto.port ? `:${dto.port}` : ''}`;
    const clientUri = `sip:${dto.username || trunkId}@${clientUriDomain}`;

    await this.sequelize.transaction(async (t) => {
      // 1. Auth
      await this.authModel.create(
        {
          id: trunkId,
          auth_type: 'userpass',
          username: dto.username || trunkId,
          password: dto.password || '',
        },
        { transaction: t },
      );

      // 2. AoR
      await this.aorModel.create(
        {
          id: trunkId,
          contact: this.buildAorContact(dto.host, dto.port),
          qualify_frequency: resolveQualifyFrequency(dto.qualifyFrequency),
        },
        { transaction: t },
      );

      // 3. Registration (outbound)
      await this.registrationModel.create(
        {
          id: trunkId,
          server_uri: serverUri,
          client_uri: clientUri,
          outbound_auth: trunkId,
          contact_user: dto.contactUser || dto.username || trunkId,
          transport: dto.transport || null,
          endpoint: trunkId,
          retry_interval: 60,
          forbidden_retry_interval: 300,
          expiration: resolveRegistrationExpiration(dto.registrationExpiration),
          line: 'yes',
          type: 'registration',
        },
        { transaction: t },
      );

      // 4. Endpoint тАФ outbound_auth for REGISTER; inbound identify is by IP (not InAuth)
      await this.endpointModel.create(
        {
          id: trunkId,
          tenantid: String(vpbxUserUid),
          auth: null,
          outbound_auth: trunkId,
          aors: trunkId,
          context,
          disallow: 'all',
          allow: dto.codecs || 'ulaw,alaw,g722',
          transport: dto.transport || null,
          from_user: dto.fromUser || dto.username || '',
          from_domain: dto.fromDomain || dto.host || '',
          identify_by: 'ip,username',
          direct_media: 'no',
          force_rport: 'yes',
          rewrite_contact: 'yes',
          rtp_symmetric: 'yes',
          ice_support: 'no',
          webrtc: 'no',
          dtmf_mode: 'auto',
          language: 'ru',
          ...(dto.advanced || {}),
        },
        { transaction: t },
      );

      await this.replaceIdentifyRows(trunkId, dto.matchIp || dto.host, t);
    });

    // Trigger AMI registration + IP identifier (inbound match)
    try {
      if (this.amiService.isConnected()) {
        await this.amiService.moduleReload('res_pjsip_outbound_registration.so');
        await this.amiService.moduleReload('res_pjsip_endpoint_identifier_ip.so');
        await this.amiService.pjsipRegister(trunkId);
        this.logger.log(`тЬЕ AMI PJSIPRegister sent for ${trunkId}`);
      }
    } catch (e: any) {
      this.logger.warn(`AMI PJSIPRegister failed for ${trunkId}: ${e.message}`);
    }

    if (userId) {
      await this.loggerService.logAction(
        userId, 'create', 'trunk', null, vpbxUserUid,
        `Created auth trunk "${dto.name}" (${trunkId})`,
      );
    }

    return { id: trunkId, name: dto.name, trunkType: 'auth' as const };
  }

  /**
   * Create an IP-type trunk.
   * Creates: ps_aors, ps_endpoints, ps_endpoint_id_ips.
   * Then reloads the IP identifier module via AMI.
   */
  async createIpTrunk(dto: CreateTrunkDto, vpbxUserUid: number, userId?: number) {
    const trunkId = this.buildTrunkId(dto.name, vpbxUserUid);
    await this.ensureUnique(trunkId);

    const context = this.buildContext(dto.context, vpbxUserUid);
    const matchIp = dto.matchIp || dto.host;

    await this.sequelize.transaction(async (t) => {
      // 1. AoR
      await this.aorModel.create(
        {
          id: trunkId,
          contact: this.buildAorContact(dto.host, dto.port),
          qualify_frequency: resolveQualifyFrequency(dto.qualifyFrequency),
        },
        { transaction: t },
      );

      // 2. Endpoint
      await this.endpointModel.create(
        {
          id: trunkId,
          tenantid: String(vpbxUserUid),
          aors: trunkId,
          context,
          disallow: 'all',
          allow: dto.codecs || 'ulaw,alaw,g722',
          transport: dto.transport || null,
          from_user: dto.fromUser || '',
          from_domain: dto.fromDomain || dto.host || '',
          direct_media: 'no',
          dtmf_mode: 'auto',
          language: 'ru',
          ...(dto.advanced || {}),
        },
        { transaction: t },
      );

      await this.replaceIdentifyRows(trunkId, matchIp, t);
    });

    // Reload IP identifier module so Asterisk picks up changes
    try {
      if (this.amiService.isConnected()) {
        await this.amiService.moduleReload('res_pjsip_endpoint_identifier_ip.so');
        this.logger.log(`тЬЕ AMI ModuleLoad reload sent for IP trunk ${trunkId}`);
      }
    } catch (e: any) {
      this.logger.warn(`AMI ModuleLoad reload failed for ${trunkId}: ${e.message}`);
    }

    if (userId) {
      await this.loggerService.logAction(
        userId, 'create', 'trunk', null, vpbxUserUid,
        `Created IP trunk "${dto.name}" (${trunkId})`,
      );
    }

    return { id: trunkId, name: dto.name, trunkType: 'ip' as const };
  }

  /**
   * Create a trunk (dispatches to Auth or IP creation).
   */
  async create(dto: CreateTrunkDto, vpbxUserUid: number, userId?: number) {
    if (dto.trunkType === 'auth') {
      return this.createAuthTrunk(dto, vpbxUserUid, userId);
    } else {
      return this.createIpTrunk(dto, vpbxUserUid, userId);
    }
  }

  /**
   * Update a trunk's configuration.
   */
  async update(trunkId: string, dto: UpdateTrunkDto, vpbxUserUid: number, userId?: number) {
    const existing = await this.endpointModel.findOne({
      where: { id: trunkId, tenantid: String(vpbxUserUid) },
    });
    if (!existing || !trunkId.startsWith('t_')) {
      throw new NotFoundException('Trunk not found');
    }

    const reg = await this.registrationModel.findByPk(trunkId);
    const isAuth = !!reg;

    await this.sequelize.transaction(async (t) => {
      // Update endpoint
      const endpointUpdate: any = {};
      if (dto.context) endpointUpdate.context = this.buildContext(dto.context, vpbxUserUid);
      if (dto.transport !== undefined) endpointUpdate.transport = dto.transport || null;
      if (dto.codecs) endpointUpdate.allow = dto.codecs;
      if (dto.fromUser !== undefined) endpointUpdate.from_user = dto.fromUser;
      if (dto.fromDomain !== undefined) endpointUpdate.from_domain = dto.fromDomain;
      if (dto.advanced) Object.assign(endpointUpdate, dto.advanced);
      if (isAuth) {
        endpointUpdate.outbound_auth = trunkId;
        endpointUpdate.auth = null;
        if (endpointUpdate.identify_by === undefined) {
          endpointUpdate.identify_by = 'ip,username';
        }
      }

      if (Object.keys(endpointUpdate).length) {
        await this.endpointModel.update(endpointUpdate, {
          where: { id: trunkId },
          transaction: t,
        });
      }

      if (isAuth) {
        const authUpdate: any = {};
        if (dto.username) authUpdate.username = dto.username;
        if (dto.password) authUpdate.password = dto.password;
        if (Object.keys(authUpdate).length) {
          await this.authModel.update(authUpdate, {
            where: { id: trunkId },
            transaction: t,
          });
        }

        const regUpdate: any = {};

        const shouldUpdateUri = dto.host !== undefined || dto.port !== undefined || 
                                dto.username !== undefined || dto.fromDomain !== undefined;

        if (shouldUpdateUri) {
          const currentHostWithPort = reg.server_uri.replace('sip:', '');
          const newHostWithPort = dto.host !== undefined 
            ? `${dto.host}${dto.port ? `:${dto.port}` : ''}` 
            : currentHostWithPort;

          regUpdate.server_uri = `sip:${newHostWithPort}`;

          const currentUsername = dto.username ?? (reg.client_uri?.match(/sip:(.*)@/)?.[1] || reg.outbound_auth || trunkId);
          const newDomain = dto.fromDomain !== undefined 
            ? (dto.fromDomain || newHostWithPort)
            : (existing.from_domain || newHostWithPort);

          regUpdate.client_uri = `sip:${currentUsername}@${newDomain}`;
        }

        if (dto.contactUser) regUpdate.contact_user = dto.contactUser;
        if (dto.transport !== undefined) regUpdate.transport = dto.transport || null;
        if (dto.registrationExpiration !== undefined) {
          regUpdate.expiration = resolveRegistrationExpiration(dto.registrationExpiration);
        }
        if (Object.keys(regUpdate).length) {
          await this.registrationModel.update(regUpdate, {
            where: { id: trunkId },
            transaction: t,
          });
        }
      }

      const identifySource = dto.matchIp
        || dto.host
        || (isAuth ? reg?.server_uri?.replace(/^sip:/i, '').split(':')[0] : null);
      if (identifySource) {
        await this.replaceIdentifyRows(trunkId, identifySource, t);
      }

      const aorUpdate: Record<string, unknown> = {};
      if (dto.host) {
        aorUpdate.contact = this.buildAorContact(dto.host, dto.port);
      }
      if (dto.qualifyFrequency !== undefined) {
        aorUpdate.qualify_frequency = resolveQualifyFrequency(dto.qualifyFrequency);
      }
      if (Object.keys(aorUpdate).length) {
        await this.aorModel.update(aorUpdate, {
          where: { id: trunkId },
          transaction: t,
        });
      }
    });

    try {
      if (this.amiService.isConnected()) {
        await this.amiService.moduleReload('res_pjsip_endpoint_identifier_ip.so');
        if (isAuth) {
          await this.amiService.moduleReload('res_pjsip_outbound_registration.so');
          await this.amiService.pjsipRegister(trunkId);
        }
        if (dto.qualifyFrequency !== undefined) {
          await this.amiService.pjsipReload();
        }
      }
    } catch (e: any) {
      this.logger.warn(`AMI reload failed after update of ${trunkId}: ${e.message}`);
    }

    if (userId) {
      await this.loggerService.logAction(
        userId, 'update', 'trunk', null, vpbxUserUid,
        `Updated trunk ${trunkId}`,
      );
    }

    return this.findOne(trunkId, vpbxUserUid);
  }

  /**
   * Delete a trunk and all its related PJSIP records.
   */
  async remove(trunkId: string, vpbxUserUid: number, userId?: number) {
    const existing = await this.endpointModel.findOne({
      where: { id: trunkId, tenantid: String(vpbxUserUid) },
    });
    if (!existing || !trunkId.startsWith('t_')) {
      throw new NotFoundException('Trunk not found');
    }

    const reg = await this.registrationModel.findByPk(trunkId);
    const isAuth = !!reg;

    // Unregister before deleting (for auth trunks)
    if (isAuth) {
      try {
        if (this.amiService.isConnected()) {
          await this.amiService.pjsipUnregister(trunkId);
        }
      } catch (e: any) {
        this.logger.warn(`AMI PJSIPUnregister failed for ${trunkId}: ${e.message}`);
      }
    }

    await this.sequelize.transaction(async (t) => {
      await this.registrationModel.destroy({ where: { id: trunkId }, transaction: t });
      await this.endpointIdIpModel.destroy({ where: { endpoint: trunkId }, transaction: t });
      await this.endpointModel.destroy({ where: { id: trunkId }, transaction: t });
      await this.authModel.destroy({ where: { id: trunkId }, transaction: t });
      await this.aorModel.destroy({ where: { id: trunkId }, transaction: t });
    });

    // Reload modules after deletion
    try {
      if (this.amiService.isConnected()) {
        if (isAuth) {
          await this.amiService.moduleReload('res_pjsip_outbound_registration.so');
        } else {
          await this.amiService.moduleReload('res_pjsip_endpoint_identifier_ip.so');
        }
      }
    } catch (e: any) {
      this.logger.warn(`AMI reload failed after deletion of ${trunkId}: ${e.message}`);
    }

    if (userId) {
      await this.loggerService.logAction(
        userId, 'delete', 'trunk', null, vpbxUserUid,
        `Deleted trunk ${trunkId}`,
      );
    }
  }

  /**
   * Delete multiple trunks.
   */
  async bulkRemove(trunkIds: string[], vpbxUserUid: number, userId?: number) {
    const results = await Promise.allSettled(
      trunkIds.map((id) => this.remove(id, vpbxUserUid, userId))
    );

    const failed = results.filter((r) => r.status === 'rejected');
    if (failed.length > 0) {
      this.logger.error(`Failed to delete some trunks: ${failed.length} failed out of ${trunkIds.length}`);
      // Throw error if all failed or handle partial success
      if (failed.length === trunkIds.length) {
        throw new Error('Failed to delete any of the selected trunks');
      }
    }
    return { success: true, deleted: trunkIds.length - failed.length, failed: failed.length };
  }

  /** Extract display name from trunk ID (e.g. t_provider44_0 тЖТ provider44) */
  private extractTrunkName(trunkId: string, vpbxUserUid: number): string {
    const suffix = `_${vpbxUserUid}`;
    let name = trunkId;
    if (name.startsWith('t_')) name = name.slice(2);
    if (name.endsWith(suffix)) name = name.slice(0, -suffix.length);
    return name;
  }

  /** Strip tenant suffix from context for display */
  private stripContext(context: string | null, vpbxUserUid: number): string {
    if (!context) return '';
    const suffix = String(vpbxUserUid);
    if (context.endsWith(suffix)) return context.slice(0, -suffix.length);
    return context;
  }

  /** Ensure trunk ID is unique */
  private async ensureUnique(trunkId: string): Promise<void> {
    const exists = await this.endpointModel.findByPk(trunkId);
    if (exists) throw new ConflictException(`Trunk with this name already exists`);
  }

  private buildAorContact(host: string, port?: number): string {
    const clean = host.replace(/^sip:/i, '').trim();
    return port ? `sip:${clean}:${port}` : `sip:${clean}`;
  }

  /** Replace all identify rows so inbound INVITEs match this trunk (auth + IP). */
  private async replaceIdentifyRows(
    trunkId: string,
    raw: string | undefined,
    transaction: Transaction,
  ): Promise<void> {
    const matches = parseIdentifyMatches(raw);
    await this.endpointIdIpModel.destroy({ where: { endpoint: trunkId }, transaction });
    for (let i = 0; i < matches.length; i++) {
      const match = matches[i];
      await this.endpointIdIpModel.create(
        {
          id: identifyRowId(trunkId, i),
          endpoint: trunkId,
          match,
          type: 'identify',
          srv_lookups: identifyNeedsSrvLookup(match) ? 'yes' : 'no',
        },
        { transaction },
      );
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { SttEngine } from '../../stt-engines/stt-engine.model';
import { TtsEngine } from '../../tts-engines/tts-engine.model';
import { YandexStreamingSttProvider } from './yandex-streaming-stt.provider';
import { YandexStreamingTtsProvider } from './yandex-streaming-tts.provider';
import { CustomHttpSttProvider } from './custom-http-stt.provider';
import { ISttStreamingProvider, ISttProvider, SttStream, SttResult } from '../interfaces/stt-provider.interface';
import { ITtsStreamingProvider } from '../interfaces/tts-provider.interface';

/**
 * STT Provider Factory.
 *
 * Routes STT requests to the appropriate provider based on engine type:
 * - 'yandex' тЖТ YandexStreamingSttProvider (gRPC bidirectional stream)
 * - 'custom' тЖТ CustomHttpSttProvider (HTTP REST batch mode)
 * - 'google' тЖТ Reserved for future Google Cloud STT integration
 *
 * Supports both streaming and batch modes:
 * - Streaming: createStream() for real-time gRPC bidirectional recognition
 * - Batch: transcribe() for REST-based providers
 */
@Injectable()
export class SttProviderFactory {
  private readonly logger = new Logger(SttProviderFactory.name);

  constructor(
    private readonly yandexStt: YandexStreamingSttProvider,
    private readonly customStt: CustomHttpSttProvider,
  ) {}

  /**
   * Check if the engine supports streaming mode.
   */
  isStreamingSupported(engine: SttEngine): boolean {
    return engine.type === 'yandex'; // Google will be added later
  }

  /**
   * Create a streaming STT session (for gRPC-capable engines).
   * Throws if the engine doesn't support streaming.
   */
  createStream(engine: SttEngine, language: string): SttStream {
    switch (engine.type) {
      case 'yandex':
        return this.yandexStt.createStream(
          engine.token,
          engine.settings || {},
          language,
        );

      default:
        throw new Error(`Streaming STT not supported for engine type: ${engine.type}`);
    }
  }

  /**
   * Batch transcribe (for REST-based engines or engines without streaming).
   */
  async transcribe(engine: SttEngine, audioBuffer: Buffer, language: string): Promise<SttResult> {
    switch (engine.type) {
      case 'custom':
        return this.customStt.transcribeWithEngine(
          audioBuffer,
          language,
          engine.custom_url || '',
          engine.token,
          engine.auth_mode,
          engine.custom_headers,
          engine.settings,
        );

      case 'yandex':
        // Yandex also supports batch via file recognition,
        // but for simplicity, we fall back to streaming with accumulation
        this.logger.warn('Yandex STT used in batch mode тАФ consider switching to streaming for lower latency');
        return this.transcribeViaTempStream(engine, audioBuffer, language);

      default:
        this.logger.error(`Unknown STT engine type: ${engine.type}`);
        return { text: '', language };
    }
  }

  /**
   * Fallback: transcribe via a temporary streaming session.
   * Opens a stream, writes all audio, waits for final text, closes.
   */
  private transcribeViaTempStream(engine: SttEngine, audioBuffer: Buffer, language: string): Promise<SttResult> {
    return new Promise((resolve) => {
      const stream = this.createStream(engine, language);
      let finalText = '';
      const timeout = setTimeout(() => {
        stream.end();
        resolve({ text: finalText, language });
      }, 10000); // 10s safety timeout

      stream.events.on('final', (text: string) => {
        finalText = text;
      });

      stream.events.on('eou', () => {
        clearTimeout(timeout);
        stream.end();
        resolve({ text: finalText, language });
      });

      stream.events.on('error', () => {
        clearTimeout(timeout);
        resolve({ text: finalText, language });
      });

      stream.events.on('end', () => {
        clearTimeout(timeout);
        resolve({ text: finalText, language });
      });

      // Write all audio at once
      stream.write(audioBuffer);

      // Signal end of audio after a small delay
      setTimeout(() => stream.end(), 500);
    });
  }
}

/**
 * TTS Provider Factory.
 *
 * Routes TTS requests to the appropriate provider based on engine type:
 * - 'yandex' тЖТ YandexStreamingTtsProvider (gRPC server stream)
 * - 'custom' тЖТ Reserved for custom REST-based TTS
 * - 'google' тЖТ Reserved for future Google Cloud TTS integration
 */
@Injectable()
export class TtsProviderFactory {
  private readonly logger = new Logger(TtsProviderFactory.name);

  constructor(
    private readonly yandexTts: YandexStreamingTtsProvider,
  ) {}

  /**
   * Get the streaming TTS provider for an engine.
   */
  getStreamingProvider(engine: TtsEngine): ITtsStreamingProvider | null {
    switch (engine.type) {
      case 'yandex':
        return this.yandexTts;

      default:
        this.logger.warn(`No streaming TTS provider for engine type: ${engine.type}`);
        return null;
    }
  }

  /**
   * Synthesize text using the appropriate engine.
   * Streams PCM16 chunks to the callback as they arrive.
   */
  async synthesize(
    engine: TtsEngine,
    text: string,
    onChunk: (pcm16: Buffer) => void,
    signal?: AbortSignal,
  ): Promise<void> {
    switch (engine.type) {
      case 'yandex':
        return this.yandexTts.synthesizeStream(
          text,
          engine.token,
          engine.settings || {},
          onChunk,
          signal,
        );

      default:
        this.logger.error(`No TTS provider for engine type: ${engine.type}`);
        throw new Error(`Unsupported TTS engine type: ${engine.type}`);
    }
  }

  /**
   * Batch synthesize: accumulates all streaming chunks into a single PCM16 buffer.
   * Used by batch/cache mode (TtsCacheService) where the full audio is needed at once.
   *
   * @param engine TTS engine configuration
   * @param text Text to synthesize
   * @returns Complete PCM16 audio buffer (LINEAR16, engine's native sample rate)
   */
  async synthesizeBatch(engine: TtsEngine, text: string): Promise<Buffer> {
    const chunks: Buffer[] = [];
    await this.synthesize(engine, text, (pcm16) => chunks.push(pcm16));
    return Buffer.concat(chunks);
  }
}

// Alaw to PCM16 Decodation Table
// Standard implementation based on ITU-T G.711

const alawToLinearTable = new Int16Array(256);

for (let i = 0; i < 256; i++) {
  let val = i ^ 0x55;
  let t = (val & 0x0f) << 4;
  const seg = (val & 0x70) >> 4;
  switch (seg) {
    case 0:
      t += 8;
      break;
    case 1:
      t += 0x108;
      break;
    default:
      t += 0x108;
      t <<= (seg - 1);
      break;
  }
  alawToLinearTable[i] = (val & 0x80) ? t : -t;
}

/**
 * Decodes G.711 A-law Buffer to a raw 16-bit PCM Buffer.
 */
export function decodeAlawToPcm16(alawBuffer: Buffer): Buffer {
  const pcmBuffer = Buffer.alloc(alawBuffer.length * 2);
  for (let i = 0; i < alawBuffer.length; i++) {
    const pcmSample = alawToLinearTable[alawBuffer[i]];
    pcmBuffer.writeInt16LE(pcmSample, i * 2);
  }
  return pcmBuffer;
}

/**
 * Decodes G.711 A-law Buffer directly into a Float32Array
 * with samples normalized between -1.0 and 1.0 (Required for ONNX/VAD).
 */
export function decodeAlawToFloat32Array(alawBuffer: Buffer): Float32Array {
  const floatArray = new Float32Array(alawBuffer.length);
  for (let i = 0; i < alawBuffer.length; i++) {
    const pcmSample = alawToLinearTable[alawBuffer[i]];
    floatArray[i] = pcmSample / 32768.0;
  }
  return floatArray;
}

