 * - Preload embeddings: ~1-2s (one-time, at session start)
 * - Query embedding: ~10-20ms
 * - Cosine similarity ├Ч 100: ~0.01ms
 * - Total per search: ~12-22ms (CPU only, no network)
 */
@Injectable()
export class DataListSearchService {
