    // These are conversational filler, not search-relevant in any domain
    '╨│╨╛╤А╨╛╨┤', '╤А╨░╨╣╨╛╨╜', '╤Г╨╗╨╕╤Ж╨░', '╨┤╨╡╤А╨╡╨▓╨╜╤П', '╤Б╨╡╨╗╨╛', '╨┐╨╛╤Б╨╡╨╗╨╛╨║', '╨┐╨╛╤Б╤С╨╗╨╛╨║',
