  ]);

  /**
   * Auto-computed per-list stop-words cache: listId тЖТ Set of words
   * Words appearing in >50% of rows in a given list are stop-words FOR THAT LIST.
   */
  private readonly listStopWordsCache = new Map<number, Set<string>>();

  /** Document frequency threshold: words in >50% of rows are stop-words */
  private static readonly DF_STOP_THRESHOLD = 0.5;

  constructor(
    private readonly semanticRouter: SemanticRouterService,
  ) {}

  /**
   * Pre-compute and cache embeddings for all rows in a data list.
   * Should be called once when a voice robot session starts.
   *
   * Only searchable columns are included in the embedding text.
   */
  async preloadList(list: VoiceRobotDataList): Promise<void> {
    if (!this.semanticRouter.isAvailable) {
      this.logger.debug('[DataListSearch] Semantic router not available, skipping preload');
      return;
    }

    // Fast check: if first and last row are cached, assume all are cached (O(1) instead of O(n))
    if (list.rows.length > 0) {
      const firstKey = this.cacheKey(list.uid, 0);
      const lastKey = this.cacheKey(list.uid, list.rows.length - 1);
      if (this.rowEmbeddingCache.has(firstKey) && this.rowEmbeddingCache.has(lastKey)) {
        return; // Already fully cached
      }
    }

    // Detect answer-like columns to exclude from embeddings.
    // The searchable column with the longest avg text is likely the "answer" field
    // (e.g., full office schedule) тАФ embedding it dilutes the search key quality.
    const answerCols = this.detectAnswerColumns(list);

    const startTime = Date.now();
    let cached = 0;

    for (let i = 0; i < list.rows.length; i++) {
      const key = this.cacheKey(list.uid, i);
      if (this.rowEmbeddingCache.has(key)) continue;

      const searchText = this.buildSearchText(list.columns, list.rows[i], answerCols);
      if (!searchText.trim()) continue;

      try {
        const embedding = await this.semanticRouter.embed(searchText, false);
        this.rowEmbeddingCache.set(key, embedding);
        cached++;
      } catch (err: any) {
        this.logger.warn(`[DataListSearch] Failed to embed row ${i} of list ${list.uid}: ${err.message}`);
      }
    }

    const elapsed = Date.now() - startTime;
    if (cached > 0) {
      this.logger.log(
        `[DataListSearch] Cached ${cached} row embeddings for list "${list.name}" (${list.uid}) in ${elapsed}ms`,
      );
    }
  }

  /**
   * Search a data list for the best matching row.
   *
   * Hybrid strategy:
   * 1. Short queries (тЙд3 words) тЖТ Levenshtein fuzzy match on searchable columns
   * 2. Long queries (>3 words) тЖТ Semantic embedding cosine similarity
   * 3. Fallback: if semantic returns nothing, try fuzzy
   *
   * @param query - Search text (from STT or slot value)
   * @param list - The data list to search
   * @param returnField - Column key to extract from matched row
   * @param threshold - Minimum confidence (default: 0.55)
   * @returns Match result with extracted field value, or null
   */
  async search(
    query: string,
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number = 0.65,
  ): Promise<DataListSearchResult | null> {
    if (!list.rows || list.rows.length === 0) return null;

    const normalizedQuery = this.normalize(query);
    const queryWords = this.tokenize(normalizedQuery);
    if (queryWords.length === 0) return null;

    // Filter out stop-words (universal + per-list auto-computed), keep at least 1 word
    const listStopWords = this.getListStopWords(list);
    const meaningfulWords = queryWords.filter(w =>
      !DataListSearchService.UNIVERSAL_STOP_WORDS.has(w) && !listStopWords.has(w),
    );
    const searchWords = meaningfulWords.length > 0 ? meaningfulWords : queryWords;

    const isShort = searchWords.length <= DataListSearchService.SHORT_QUERY_MAX_WORDS;

    // тФАтФАтФА Strategy: fuzzy first, semantic only if needed тФАтФАтФА
    let fuzzyResult: DataListSearchResult | null = null;
    let semanticResult: DataListSearchResult | null = null;

    // 1. Fuzzy match (fast, good for short/exact queries)
    fuzzyResult = this.fuzzySearch(searchWords, list, returnField, threshold);

    // 2. Semantic match тАФ only if fuzzy didn't find a strong match
    //    (avoids expensive embedding preload for obvious matches)
    const SKIP_SEMANTIC_THRESHOLD = 0.85;
    if (this.semanticRouter.isAvailable && (!fuzzyResult || fuzzyResult.confidence < SKIP_SEMANTIC_THRESHOLD)) {
      semanticResult = await this.semanticSearch(normalizedQuery, list, returnField, threshold);
    }

    // Pick the best result by confidence
    let result: DataListSearchResult | null = null;
    if (fuzzyResult && semanticResult) {
      // For short queries, prefer fuzzy unless semantic is significantly better
      if (isShort) {
        result = semanticResult.confidence > fuzzyResult.confidence + 0.15
          ? semanticResult : fuzzyResult;
      } else {
        result = semanticResult.confidence > fuzzyResult.confidence
          ? semanticResult : fuzzyResult;
      }
    } else {
      result = fuzzyResult || semanticResult;
    }

    if (result) {
      this.logger.log(
        `[DataListSearch] Match in "${list.name}": ` +
        `query="${query}" тЖТ row[${result.rowIndex}], ` +
        `${returnField}="${result.value}", ` +
        `confidence=${result.confidence.toFixed(3)}, method=${result.method}`,
      );
    }

    return result;
  }

  /**
   * Search a data list and return ALL rows matching above threshold.
   * Used when multiMatchStrategy is 'random' to pick a random result.
   */
  async searchAll(
    query: string,
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number = 0.55,
  ): Promise<DataListSearchResult[]> {
    if (!list.rows || list.rows.length === 0) return [];

    const normalizedQuery = this.normalize(query);
    const queryWords = this.tokenize(normalizedQuery);
    if (queryWords.length === 0) return [];

    // Same stop-word filtering as search() тАФ e.g. "╨│╨╛╤А╨╛╨┤ ╨Ъ╨░╨╜╤Б╨║" тЖТ "╨║╨░╨╜╤Б╨║"
    const listStopWords = this.getListStopWords(list);
    const meaningfulWords = queryWords.filter(w =>
      !DataListSearchService.UNIVERSAL_STOP_WORDS.has(w) && !listStopWords.has(w),
    );
    const searchWords = meaningfulWords.length > 0 ? meaningfulWords : queryWords;

    const results: DataListSearchResult[] = [];
    const SKIP_SEMANTIC_THRESHOLD = 0.85;

    // 1. Fuzzy search all (same filtered tokens as search())
    const fuzzyResults = this.fuzzySearchAll(searchWords, list, returnField, threshold);
    results.push(...fuzzyResults);

    const bestFuzzyConfidence = fuzzyResults.length > 0
      ? Math.max(...fuzzyResults.map(r => r.confidence))
      : 0;

    // 2. Semantic only if fuzzy has no strong match (same gate as search())
    if (
      this.semanticRouter.isAvailable &&
      bestFuzzyConfidence < SKIP_SEMANTIC_THRESHOLD
    ) {
      const semanticResults = await this.semanticSearchAll(normalizedQuery, list, returnField, threshold);
      results.push(...semanticResults);
    }

    // Deduplicate by rowIndex (prefer higher confidence)
    const byRow = new Map<number, DataListSearchResult>();
    for (const r of results) {
      const existing = byRow.get(r.rowIndex);
      if (!existing || r.confidence > existing.confidence) {
        byRow.set(r.rowIndex, r);
      }
    }

    return Array.from(byRow.values()).sort((a, b) => b.confidence - a.confidence);
  }

  /**
   * Clear cached embeddings for a specific data list.
   */
  clearListCache(listId: number): void {
    const prefix = `list_${listId}_`;
    for (const key of this.rowEmbeddingCache.keys()) {
      if (key.startsWith(prefix)) {
        this.rowEmbeddingCache.delete(key);
      }
    }
    this.listStopWordsCache.delete(listId);
  }

  /**
   * Clear all cached embeddings.
   */
  clearAllCache(): void {
    this.rowEmbeddingCache.clear();
    this.listStopWordsCache.clear();
  }

  // тФАтФАтФА Fuzzy Search тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Levenshtein word-level fuzzy match across searchable columns.
   */
  private fuzzySearch(
    queryWords: string[],
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number,
  ): DataListSearchResult | null {
    const searchableKeys = list.columns
      .filter(col => col.searchable)
      .map(col => col.key);

    let bestRow: Record<string, string> | null = null;
    let bestIndex = -1;
    let bestConfidence = 0;

    for (let i = 0; i < list.rows.length; i++) {
      const row = list.rows[i];

      // Check each searchable column individually
      for (const colKey of searchableKeys) {
        const cellValue = row[colKey];
        if (!cellValue) continue;

        const normalizedCell = this.normalize(cellValue);
        const cellWords = this.tokenize(normalizedCell);
        if (cellWords.length === 0) continue;

        let confidence = this.calculateFuzzyConfidence(queryWords, cellWords);

        // Boost: if all query words are substring-contained in cell text
        const queryJoined = queryWords.join(' ');
        if (normalizedCell.includes(queryJoined)) {
          confidence = Math.max(confidence, 0.95); // near-exact containment
        }

        if (confidence > bestConfidence) {
          bestConfidence = confidence;
          bestRow = row;
          bestIndex = i;
        }
      }

      // Also check concatenated searchable text (for multi-column queries)
      const fullSearchText = this.buildSearchText(list.columns, row);
      const fullWords = this.tokenize(this.normalize(fullSearchText));
      if (fullWords.length > 0) {
        const confidence = this.calculateFuzzyConfidence(queryWords, fullWords);
        if (confidence > bestConfidence) {
          bestConfidence = confidence;
          bestRow = row;
          bestIndex = i;
        }
      }
    }

    if (bestRow && bestConfidence >= threshold) {
      return {
        row: bestRow,
        rowIndex: bestIndex,
        value: bestRow[returnField] || '',
        confidence: bestConfidence,
        method: 'fuzzy',
      };
    }

    return null;
  }

  /**
   * Fuzzy search returning ALL rows above threshold.
   */
  private fuzzySearchAll(
    queryWords: string[],
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number,
  ): DataListSearchResult[] {
    const searchableKeys = list.columns
      .filter(col => col.searchable)
      .map(col => col.key);

    const results: DataListSearchResult[] = [];

    for (let i = 0; i < list.rows.length; i++) {
      const row = list.rows[i];
      let rowBestConfidence = 0;

      const queryJoined = queryWords.join(' ');

      for (const colKey of searchableKeys) {
        const cellValue = row[colKey];
        if (!cellValue) continue;
        const normalizedCell = this.normalize(cellValue);
        const cellWords = this.tokenize(normalizedCell);
        if (cellWords.length === 0) continue;
        let confidence = this.calculateFuzzyConfidence(queryWords, cellWords);
        if (normalizedCell.includes(queryJoined)) {
          confidence = Math.max(confidence, 0.95);
        }
        if (confidence > rowBestConfidence) rowBestConfidence = confidence;
      }

      const fullSearchText = this.buildSearchText(list.columns, row);
      const normalizedFull = this.normalize(fullSearchText);
      const fullWords = this.tokenize(normalizedFull);
      if (fullWords.length > 0) {
        let confidence = this.calculateFuzzyConfidence(queryWords, fullWords);
        if (normalizedFull.includes(queryJoined)) {
          confidence = Math.max(confidence, 0.95);
        }
        if (confidence > rowBestConfidence) rowBestConfidence = confidence;
      }

      if (rowBestConfidence >= threshold) {
        results.push({
          row,
          rowIndex: i,
          value: row[returnField] || '',
          confidence: rowBestConfidence,
          method: 'fuzzy',
        });
      }
    }

    return results;
  }

  // тФАтФАтФА Semantic Search тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Embedding cosine similarity search.
   */
  private async semanticSearch(
    query: string,
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number,
  ): Promise<DataListSearchResult | null> {
    // Use same threshold as fuzzy тАФ no reduction; false positives are worse than misses
    const semanticThreshold = threshold;

    let queryEmbed: Float32Array;
    try {
      queryEmbed = await this.semanticRouter.embed(query, true);
    } catch {
      return null;
    }

    let bestRow: Record<string, string> | null = null;
    let bestIndex = -1;
    let bestSimilarity = 0;

    for (let i = 0; i < list.rows.length; i++) {
      const key = this.cacheKey(list.uid, i);
      const cached = this.rowEmbeddingCache.get(key);
      if (!cached) continue;

      const similarity = this.cosineSimilarity(queryEmbed, cached);
      if (similarity > bestSimilarity) {
        bestSimilarity = similarity;
        bestRow = list.rows[i];
        bestIndex = i;
      }
    }

    if (bestRow && bestSimilarity >= semanticThreshold) {
      return {
        row: bestRow,
        rowIndex: bestIndex,
        value: bestRow[returnField] || '',
        confidence: bestSimilarity,
        method: 'semantic',
      };
    }

    return null;
  }

  /**
   * Semantic search returning ALL rows above threshold.
   */
  private async semanticSearchAll(
    query: string,
    list: VoiceRobotDataList,
    returnField: string,
    threshold: number,
  ): Promise<DataListSearchResult[]> {
    const semanticThreshold = threshold;

    let queryEmbed: Float32Array;
    try {
      queryEmbed = await this.semanticRouter.embed(query, true);
    } catch {
      return [];
    }

    const results: DataListSearchResult[] = [];

    for (let i = 0; i < list.rows.length; i++) {
      const key = this.cacheKey(list.uid, i);
      const cached = this.rowEmbeddingCache.get(key);
      if (!cached) continue;

      const similarity = this.cosineSimilarity(queryEmbed, cached);
      if (similarity >= semanticThreshold) {
        results.push({
          row: list.rows[i],
          rowIndex: i,
          value: list.rows[i][returnField] || '',
          confidence: similarity,
          method: 'semantic',
        });
      }
    }

    return results;
  }

  // тФАтФАтФА Per-List Stop-Words тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Get (or compute & cache) stop-words specific to a data list.
   * Words that appear in >50% of searchable rows are considered stop-words
   * because they don't help discriminate between rows.
   *
   * Example: in a list of city offices, "╨╛╤Д╨╕╤Б" appears in every row тЖТ auto stop-word.
   * In a list of tariff plans, "╤В╨░╤А╨╕╤Д" appears in every row тЖТ auto stop-word.
   */
  private getListStopWords(list: VoiceRobotDataList): Set<string> {
    if (this.listStopWordsCache.has(list.uid)) {
      return this.listStopWordsCache.get(list.uid)!;
    }

    const stopWords = new Set<string>();
    const rowCount = list.rows.length;
    if (rowCount < 2) {
      this.listStopWordsCache.set(list.uid, stopWords);
      return stopWords;
    }

    // Count document frequency of each word across searchable columns
    const wordDocFreq = new Map<string, number>();

    for (const row of list.rows) {
      const searchText = this.buildSearchText(list.columns, row);
      const words = new Set(this.tokenize(this.normalize(searchText))); // unique per row
      for (const word of words) {
        if (word.length < 2) continue; // skip single chars
        wordDocFreq.set(word, (wordDocFreq.get(word) || 0) + 1);
      }
    }

    // Words appearing in >50% of rows are stop-words for this list
    const threshold = rowCount * DataListSearchService.DF_STOP_THRESHOLD;
    for (const [word, freq] of wordDocFreq) {
      if (freq > threshold) {
        stopWords.add(word);
      }
    }

    if (stopWords.size > 0) {
      this.logger.debug(
        `[DataListSearch] Auto stop-words for "${list.name}": [${Array.from(stopWords).join(', ')}]`,
      );
    }

    this.listStopWordsCache.set(list.uid, stopWords);
    return stopWords;
  }

  /**
   * Detect which searchable columns are likely "answer" fields.
   * Heuristic: if a searchable column has 3x+ longer average text than others,
   * it's probably an answer/response field (e.g., full office schedule).
   *
   * These columns should be excluded from embeddings to avoid diluting
   * the search key vectors.
   */
  private detectAnswerColumns(list: VoiceRobotDataList): Set<string> {
    const excludeKeys = new Set<string>();
    const searchableCols = list.columns.filter(col => col.searchable);
    if (searchableCols.length <= 1) return excludeKeys; // Only 1 searchable col тАФ keep it

    // Calculate average text length per searchable column
    const avgLengths: { key: string; avg: number }[] = [];
    for (const col of searchableCols) {
      let totalLen = 0;
      for (const row of list.rows) {
        totalLen += (row[col.key] || '').length;
      }
      avgLengths.push({ key: col.key, avg: list.rows.length > 0 ? totalLen / list.rows.length : 0 });
    }

    // Find the shortest avg (the "key" column) and flag columns 3x+ longer
    const minAvg = Math.min(...avgLengths.map(a => a.avg));
    if (minAvg === 0) return excludeKeys;

    for (const { key, avg } of avgLengths) {
      if (avg > minAvg * 3 && avg > 50) { // Must be 3x longer AND > 50 chars avg
        excludeKeys.add(key);
        this.logger.debug(
          `[DataListSearch] Excluding column "${key}" from embeddings ` +
          `(avg ${avg.toFixed(0)} chars vs min ${minAvg.toFixed(0)} тАФ likely answer field)`,
        );
      }
    }

    return excludeKeys;
  }

  // тФАтФАтФА Utility Methods тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Build search text from searchable columns of a row.
   * EXCLUDES the returnField column тАФ it contains answer data
   * that would pollute embeddings and fuzzy matching.
   *
   * Example: for a city offices list with columns [city(searchable), answer(searchable)]:
   * - Before: "╨Ъ╤А╨░╤Б╨╜╨╛╤П╤А╤Б╨║ ╨Ю╤Д╨╕╤Б ╨║╨╛╨╝╨┐╨░╨╜╨╕╨╕ ╨╜╨░╤Е╨╛╨┤╨╕╤В╤Б╤П ╨┐╨╛ ╨░╨┤╤А╨╡╤Б╤Г..." (embedded together)
   * - After:  "╨Ъ╤А╨░╤Б╨╜╨╛╤П╤А╤Б╨║" (only the search key is embedded)
   */
  private buildSearchText(
    columns: IDataListColumn[],
    row: Record<string, string>,
    excludeKeys?: Set<string>,
  ): string {
    return columns
      .filter(col => col.searchable && (!excludeKeys || !excludeKeys.has(col.key)))
      .map(col => row[col.key] || '')
      .filter(Boolean)
      .join(' ');
  }

  /**
   * Calculate fuzzy confidence: how many query words match cell words.
   */
  private calculateFuzzyConfidence(
    queryWords: string[],
    cellWords: string[],
  ): number {
    let matchedWords = 0;
    let totalSimilarity = 0;

    for (const qWord of queryWords) {
      let bestWordSimilarity = 0;

      for (const cWord of cellWords) {
        const similarity = this.wordSimilarity(qWord, cWord);
        if (similarity > bestWordSimilarity) {
          bestWordSimilarity = similarity;
        }
      }

      if (bestWordSimilarity >= 0.7) {
        matchedWords++;
        totalSimilarity += bestWordSimilarity;
      }
    }

    if (queryWords.length === 0) return 0;

    const wordCoverage = matchedWords / queryWords.length;
    const avgSimilarity = matchedWords > 0 ? totalSimilarity / matchedWords : 0;

    return wordCoverage * avgSimilarity;
  }

  /**
   * Levenshtein word similarity (0.0тАУ1.0).
   */
  private wordSimilarity(a: string, b: string): number {
    if (a === b) return 1.0;
    const maxLen = Math.max(a.length, b.length);
    if (maxLen === 0) return 1.0;
    return 1.0 - distance(a, b) / maxLen;
  }

  /**
   * Cosine similarity (assumes normalized vectors тЖТ dot product).
   */
  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    const len = Math.min(a.length, b.length);
    let dot = 0;
    for (let i = 0; i < len; i++) {
      dot += a[i] * b[i];
    }
    return dot;
  }

  private normalize(text: string): string {
    return text
      .toLowerCase()
      .replace(/╤С/g, '╨╡')
      .replace(/[^\p{L}\p{N}\s]/gu, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  private tokenize(text: string): string[] {
    return text.split(' ').filter(w => w.length > 0);
  }

  private cacheKey(listId: number, rowIndex: number): string {
    return `list_${listId}_row_${rowIndex}`;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { distance } from 'fastest-levenshtein';
import { VoiceRobotKeyword } from '../keyword.model';
import { SemanticRouterService } from './semantic-router.service';

/**
 * Result of a keyword match attempt.
 */
export interface MatchResult {
  /** Matched keyword entity */
  keyword: VoiceRobotKeyword;
  /** Confidence score (0.0тАУ1.0) */
  confidence: number;
  /** Which specific phrase triggered the match */
  matchedPhrase: string;
  /** Number of words matched */
  matchedWordCount: number;
  /** Matching method used */
  method: 'levenshtein' | 'semantic' | 'fallback' | 'max_retries';
}

/**
 * Hybrid Keyword Matcher Service.
 *
 * Two-tier matching strategy:
 * 1. Short utterances (тЙд2 words) тЖТ Levenshtein fuzzy word-matching
 *    - Fast, reliable for "╨┤╨░", "╨╜╨╡╤В", "╨┐╨╛╨╝╨╛╤Й╤М", "╨╛╨┐╨╡╤А╨░╤В╨╛╤А"
 *    - O(N*M) where N = text words, M = keyword words
 *
 * 2. Long utterances (>2 words) тЖТ Semantic embedding cosine similarity
 *    - Understands meaning: "╨╝╨╜╨╡ ╨╜╤Г╨╢╨╜╨░ ╨┐╨╛╨╝╨╛╤Й╤М ╤Б╨┐╨╡╤Ж╨╕╨░╨╗╨╕╤Б╤В╨░" тЙИ "╨┐╨╛╨╝╨╛╤Й╤М"
 *    - Uses nomic-embed-text-v1.5 via SemanticRouterService
 *    - Falls back to Levenshtein if semantic router unavailable
 *
 * Negative keywords support:
 *    - If text semantically matches a negative keyword (>0.7), the positive
 *      match is suppressed even if confidence is high.
 */
@Injectable()
export class KeywordMatcherService {
  private readonly logger = new Logger(KeywordMatcherService.name);

  /** Word count threshold: тЙд this тЖТ Levenshtein, > this тЖТ semantic */
  private static readonly SHORT_UTTERANCE_MAX_WORDS = 2;

  constructor(
    private readonly semanticRouter: SemanticRouterService,
  ) {}

  /**
   * Match recognized text against a list of keywords.
   * Returns the best match or null if no match found.
   *
   * Uses hybrid strategy: short text тЖТ Levenshtein, long text тЖТ semantic.
   *
   * @param text - The STT-recognized text
   * @param keywords - Database keyword entries with phrases
   * @param negativePhrases - Optional list of negative keyword phrases
   * @param threshold - Minimum confidence to accept match (default: 0.7)
   */
  async match(
    text: string,
    keywords: VoiceRobotKeyword[],
    negativePhrases: string[] = [],
    threshold: number = 0.7,
  ): Promise<MatchResult | null> {
    const normalizedText = this.normalize(text);
    const textWords = this.tokenize(normalizedText);

    if (textWords.length === 0) return null;

    // Choose matching strategy based on utterance length
    const isShort = textWords.length <= KeywordMatcherService.SHORT_UTTERANCE_MAX_WORDS;

    let result: MatchResult | null = null;

    if (isShort || !this.semanticRouter.isAvailable) {
      // тФАтФАтФА Strategy 1: Levenshtein fuzzy word matching тФАтФАтФА
      result = this.levenshteinMatch(textWords, keywords, threshold);
    } else {
      // тФАтФАтФА Strategy 2: Semantic embedding cosine similarity тФАтФАтФА
      result = await this.semanticMatch(normalizedText, keywords, threshold);

      // Fallback to Levenshtein if semantic returned nothing
      if (!result) {
        result = this.levenshteinMatch(textWords, keywords, threshold);
      }
    }

    // тФАтФАтФА Negative keyword check тФАтФАтФА
    if (result && negativePhrases.length > 0 && this.semanticRouter.isAvailable) {
      const isNegative = await this.semanticRouter.matchesNegative(
        normalizedText,
        negativePhrases,
        0.7,
      );

      if (isNegative) {
        this.logger.log(
          `[Matcher] Match "${result.matchedPhrase}" suppressed by negative keyword for text: "${text}"`,
        );
        return null;
      }
    }

    return result;
  }

  /**
   * Synchronous match тАФ backwards-compatible with existing code that
   * doesn't await. Uses Levenshtein only (no semantic).
   */
  matchSync(text: string, keywords: VoiceRobotKeyword[], threshold: number = 0.7): MatchResult | null {
    const normalizedText = this.normalize(text);
    const textWords = this.tokenize(normalizedText);
    if (textWords.length === 0) return null;

    return this.levenshteinMatch(textWords, keywords, threshold);
  }

  /**
   * Pre-cache keyword embeddings for semantic matching.
   * Should be called when a robot session starts or keywords are updated.
   */
  async preloadEmbeddings(keywords: VoiceRobotKeyword[]): Promise<void> {
    if (!this.semanticRouter.isAvailable) return;

    const allPhrases: string[] = [];
    for (const keyword of keywords) {
      allPhrases.push(...this.getKeywordPhrases(keyword));
    }

    await this.semanticRouter.cacheKeywordEmbeddings(allPhrases);
  }

  // тФАтФАтФА Levenshtein matching тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Word-level fuzzy matching using Levenshtein distance.
   */
  private levenshteinMatch(
    textWords: string[],
    keywords: VoiceRobotKeyword[],
    threshold: number,
  ): MatchResult | null {
    let bestMatch: MatchResult | null = null;
    let bestConfidence = 0;

    for (const keyword of keywords) {
      if (!keyword.keywords) continue;

      const phrases = this.getKeywordPhrases(keyword);

      for (const phrase of phrases) {
        const phraseWords = this.tokenize(this.normalize(phrase));
        if (phraseWords.length === 0) continue;

        const confidence = this.calculateWordMatchConfidence(textWords, phraseWords);

        if (confidence >= threshold && confidence > bestConfidence) {
          bestConfidence = confidence;
          bestMatch = {
            keyword,
            confidence,
            matchedPhrase: phrase,
            matchedWordCount: phraseWords.length,
            method: 'levenshtein',
          };
        }
      }
    }

    return bestMatch;
  }

  // тФАтФАтФА Semantic matching тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Semantic embedding cosine similarity matching.
   */
  private async semanticMatch(
    text: string,
    keywords: VoiceRobotKeyword[],
    threshold: number,
  ): Promise<MatchResult | null> {
    // Collect all candidate phrases
    const phraseToKeyword = new Map<string, VoiceRobotKeyword>();
    const candidatePhrases: string[] = [];

    for (const keyword of keywords) {
      const phrases = this.getKeywordPhrases(keyword);
      for (const phrase of phrases) {
        phraseToKeyword.set(phrase, keyword);
        candidatePhrases.push(phrase);
      }
    }

    if (candidatePhrases.length === 0) return null;

    // Semantic threshold is slightly lower since cosine similarity
    // is inherently more nuanced than Levenshtein
    const semanticThreshold = Math.max(threshold - 0.15, 0.4);

    const match = await this.semanticRouter.findBestMatch(
      text,
      candidatePhrases,
      semanticThreshold,
    );

    if (!match) return null;

    const keyword = phraseToKeyword.get(match.phrase);
    if (!keyword) return null;

    return {
      keyword,
      confidence: match.similarity,
      matchedPhrase: match.phrase,
      matchedWordCount: this.tokenize(match.phrase).length,
      method: 'semantic',
    };
  }

  // тФАтФАтФА Utility methods тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Calculate confidence that all phrase words exist in the text (fuzzy).
   * Returns 0.0тАУ1.0 based on how many phrase words were found.
   */
  private calculateWordMatchConfidence(
    textWords: string[],
    phraseWords: string[],
  ): number {
    let matchedWords = 0;
    let totalSimilarity = 0;

    for (const phraseWord of phraseWords) {
      let bestWordSimilarity = 0;

      for (const textWord of textWords) {
        const similarity = this.wordSimilarity(textWord, phraseWord);
        if (similarity > bestWordSimilarity) {
          bestWordSimilarity = similarity;
        }
      }

      // Word is considered matched if similarity > 0.7
      if (bestWordSimilarity >= 0.7) {
        matchedWords++;
        totalSimilarity += bestWordSimilarity;
      }
    }

    if (phraseWords.length === 0) return 0;

    // Confidence = percentage of phrase words found * average similarity of matches
    const wordCoverage = matchedWords / phraseWords.length;
    const avgSimilarity = matchedWords > 0 ? totalSimilarity / matchedWords : 0;

    return wordCoverage * avgSimilarity;
  }

  /**
   * Calculate similarity between two words using Levenshtein distance.
   * Returns 0.0тАУ1.0 (1.0 = exact match).
   */
  private wordSimilarity(a: string, b: string): number {
    if (a === b) return 1.0;

    const maxLen = Math.max(a.length, b.length);
    if (maxLen === 0) return 1.0;

    const dist = distance(a, b);
    return 1.0 - dist / maxLen;
  }

  /**
   * Get all trigger phrases from a keyword.
   * Uses keyword.keywords as primary, and keyword.synonyms array if available.
   */
  private getKeywordPhrases(keyword: VoiceRobotKeyword): string[] {
    const phrases: string[] = [];

    if (keyword.keywords) {
      phrases.push(keyword.keywords);
    }

    if (keyword.synonyms && Array.isArray(keyword.synonyms)) {
      phrases.push(...keyword.synonyms);
    }

    return phrases;
  }

  /**
   * Normalize text: lowercase, remove all non-word characters.
   */
  private normalize(text: string): string {
    return text
      .toLowerCase()
      .replace(/╤С/g, '╨╡')
      .replace(/[^\p{L}\p{N}\s]/gu, '') // Remove all non-letter/non-number chars (Unicode-safe)
      .replace(/\s+/g, ' ')
      .trim();
  }

  /**
   * Tokenize text into individual words.
   */
  private tokenize(text: string): string[] {
    return text.split(' ').filter((w) => w.length > 0);
  }
}

import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import * as dgram from 'dgram';
import { EventEmitter } from 'events';
import { AudioService } from './audio.service';

/**
 * Per-session RTP data container.
 * Holds an ephemeral UDP socket and emits decoded audio events.
 */
export class RtpSession {
  public readonly eventEmitter = new EventEmitter();
  public readonly port: number;
  private readonly socket: dgram.Socket;
  private readonly logger = new Logger(RtpSession.name);
  private closed = false;

  /** Track whether we've received at least one RTP packet (for NAT remap) */
  private rtpReceived = false;

  constructor(
    private readonly audioService: AudioService,
    socket: dgram.Socket,
    port: number,
  ) {
    this.socket = socket;
    this.port = port;

    this.socket.on('message', (msg: Buffer, rinfo: dgram.RemoteInfo) => {
      if (this.closed) return;

      if (!this.rtpReceived) {
        this.rtpReceived = true;
        this.logger.log(`First RTP packet from ${rinfo.address}:${rinfo.port} тЖТ port ${this.port}`);
      }

      try {
        // Strip RTP header (12 bytes)
        const alawPayload = this.audioService.removeRTPHeader(msg);

        // Decode to PCM16 for STT accumulation
        const pcm16 = this.audioService.decodeAlawToPcm16(alawPayload);
        this.eventEmitter.emit('audio-pcm16', pcm16);

        // Decode to Float32 for VAD inference
        const float32 = this.audioService.decodeAlawToFloat32(alawPayload);
        this.eventEmitter.emit('audio-float32', float32);

      } catch (e: any) {
        this.logger.error(`Error processing RTP packet: ${e.message}`);
      }
    });

    this.socket.on('error', (err) => {
      this.logger.error(`UDP socket error on port ${this.port}: ${err.message}`);
    });
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    this.eventEmitter.removeAllListeners();
    try {
      this.socket.close();
    } catch {
      // Socket may already be closed
    }
    this.logger.log(`RTP session closed on port ${this.port}`);
  }
}

/**
 * RTP UDP Server Service.
 *
 * Creates ephemeral UDP sockets for each Voice Robot call session.
 * Each session gets its own port and emits decoded audio events
 * for VAD and STT processing.
 */
@Injectable()
export class RtpUdpServerService implements OnModuleDestroy {
  private readonly logger = new Logger(RtpUdpServerService.name);
  private readonly activeSessions = new Map<number, RtpSession>();
  
  private readonly minPort: number;
  private readonly maxPort: number;
  private currentPort: number;

  constructor(
    private readonly audioService: AudioService,
    private readonly configService: ConfigService,
  ) {
    const minStr = this.configService.get<string>('RTP_MIN_PORT');
    const maxStr = this.configService.get<string>('RTP_MAX_PORT');
    this.minPort = minStr ? parseInt(minStr, 10) : 0;
    this.maxPort = maxStr ? parseInt(maxStr, 10) : 0;
    this.currentPort = this.minPort;
  }

  private getNextPort(): number {
    if (this.minPort === 0 || this.maxPort === 0 || this.minPort > this.maxPort) {
      return 0; // OS assigns an ephemeral port
    }

    // Try finding an available port in the range
    for (let i = 0; i <= (this.maxPort - this.minPort); i++) {
      const port = this.currentPort;
      this.currentPort++;
      if (this.currentPort > this.maxPort) {
        this.currentPort = this.minPort;
      }
      
      if (!this.activeSessions.has(port)) {
        return port;
      }
    }
    
    throw new Error('No available RTP ports in configured range');
  }

  /**
   * Create a new RTP session with an ephemeral UDP port.
   *
   * @returns RtpSession with port number and audio event emitter
   */
  async createSession(): Promise<RtpSession> {
    return new Promise<RtpSession>((resolve, reject) => {
      const socket = dgram.createSocket('udp4');

      socket.on('listening', () => {
        socket.removeAllListeners('error'); // remove setup error handler
        
        // Add permanent runtime error handler
        socket.on('error', (err) => {
          this.logger.error(`UDP socket runtime error: ${err.message}`);
        });

        const addr = socket.address();
        const port = addr.port;

        const session = new RtpSession(this.audioService, socket, port);
        this.activeSessions.set(port, session);

        this.logger.log(`RTP session created on port ${port}`);
        resolve(session);
      });

      const attemptBind = (attempts: number) => {
        if (attempts > 50) {
          return reject(new Error('Failed to bind UDP socket after 50 attempts'));
        }

        try {
          const portToBind = this.getNextPort();
          
          socket.once('error', (err: any) => {
            if (err.code === 'EADDRINUSE' && portToBind !== 0) {
              this.logger.warn(`Port ${portToBind} in use, trying next...`);
              attemptBind(attempts + 1);
            } else {
              this.logger.error(`Failed to bind UDP socket: ${err.message}`);
              reject(err);
            }
          });

          socket.bind(portToBind);
        } catch (e) {
          reject(e);
        }
      };

      attemptBind(0);
    });
  }

  /**
   * Close a specific RTP session by port.
   */
  closeSession(port: number): void {
    const session = this.activeSessions.get(port);
    if (session) {
      session.close();
      this.activeSessions.delete(port);
    }
  }

  /**
   * Get count of active sessions (for monitoring).
   */
  getActiveSessionCount(): number {
    return this.activeSessions.size;
  }

  onModuleDestroy() {
    this.logger.log(`Shutting down ${this.activeSessions.size} RTP sessions...`);
    for (const [port, session] of this.activeSessions) {
      session.close();
    }
    this.activeSessions.clear();
  }
}

import { Injectable, Logger, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import { IVadProvider, VadConfig, VadResult } from '../interfaces/vad-provider.interface';

/**
 * Per-session VAD instance with isolated LSTM state.
 *
 * Each VoiceRobotSession creates its own VadSessionInstance
 * to prevent cross-session LSTM state contamination.
 *
 * CRITICAL FIX: The previous implementation shared _h/_c across all
 * concurrent sessions, causing false VAD triggers under load (тЙе2 calls).
 */
export class VadSessionInstance {
  private _sr: any;
  private _state: any;
  private frameAccumulator = new Float32Array(0);
  private destroyed = false;

  private static readonly FRAME_SIZE = 256;

  constructor(
    private readonly ort: any,
    private readonly onnxSession: any,
    private readonly threshold: number,
  ) {
    this.resetState();
  }

  /**
   * Process a Float32Array frame through VAD.
   * Handles frame accumulation internally (RTP gives ~160 samples, Silero needs 256).
   */
  async processFrame(frame: Float32Array): Promise<VadResult> {
    if (this.destroyed || !this.onnxSession) {
      return { isSpeech: false, probability: 0 };
    }

    // Accumulate frames until we have enough for a Silero frame
    const combined = new Float32Array(this.frameAccumulator.length + frame.length);
    combined.set(this.frameAccumulator, 0);
    combined.set(frame, this.frameAccumulator.length);
    this.frameAccumulator = combined;

    let maxProbability = 0;

    // Process all complete 256-sample frames in the accumulator
    while (this.frameAccumulator.length >= VadSessionInstance.FRAME_SIZE) {
      const vadFrame = this.frameAccumulator.slice(0, VadSessionInstance.FRAME_SIZE);
      this.frameAccumulator = this.frameAccumulator.slice(VadSessionInstance.FRAME_SIZE);

      const probability = await this.runOnnxFrame(vadFrame);
      if (probability > maxProbability) {
        maxProbability = probability;
      }
    }

    return {
      isSpeech: maxProbability >= this.threshold,
      probability: maxProbability,
    };
  }

  /**
   * Run a single 256-sample frame through ONNX Silero VAD.
   * Returns speech probability [0..1].
   */
  private async runOnnxFrame(frame: Float32Array): Promise<number> {
    const Tensor = this.ort.Tensor;

    const inputTensor = new Tensor('float32', frame, [1, frame.length]);

    const feeds = {
      input: inputTensor,
      sr: this._sr,
      state: this._state,
    };

    const result = await this.onnxSession.run(feeds);

    // Update state for next frame (isolated per session)
    this._state = result.stateN;

    return result.output.data[0] as number;
  }

  /**
   * Reset ONNX LSTM internal state.
   */
  resetState(): void {
    if (!this.ort) return;
    const Tensor = this.ort.Tensor;

    this._sr = new Tensor('int64', BigInt64Array.from([BigInt(8000)]), []);
    this._state = new Tensor('float32', new Float32Array(2 * 1 * 128).fill(0), [2, 1, 128]);
  }

  /**
   * Cleanup resources. Must be called when session ends.
   */
  destroy(): void {
    this.destroyed = true;
    this._state = null;
    this._sr = null;
    this.frameAccumulator = new Float32Array(0);
  }
}

/**
 * Silero VAD Provider тАФ Factory Pattern.
 *
 * The ONNX model is loaded ONCE at module init (singleton).
 * Each call session gets an isolated VadSessionInstance via createSessionInstance().
 *
 * Uses onnxruntime-node for per-frame voice activity detection.
 * Runs on CPU, ~50 MB RAM for the shared model, ~1-2ms per frame.
 *
 * Input: Float32Array frame with 256 samples @ 8kHz (32ms per frame).
 * Model: Silero VAD v6 ONNX.
 */
@Injectable()
export class SileroVadProvider implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(SileroVadProvider.name);

  private ort: any = null;
  private modelPath: string | null = null;
  private initialized = false;
  private config: VadConfig;

  onModuleInit(): void {
    // Load ONNX model in background тАФ don't block NestJS bootstrap.
    // onnxruntime-node loads native binaries synchronously which can
    // hang app startup on Windows if awaited during module initialization.
    this.config = {
      threshold: 0.5,
      silenceDurationMs: 2000,
      prefixPaddingMs: 300,
      minSpeechDurationMs: 300,
    };
    setTimeout(() => this.loadModel(), 0);
  }

  private async loadModel(): Promise<void> {
    try {
      this.ort = require('onnxruntime-node');

      // Resolve model path тАФ try package first, then local
      try {
        this.modelPath = require.resolve('@ricky0123/vad-node/dist/silero_vad.onnx');
      } catch {
        const path = require('path');
        this.modelPath = path.join(process.cwd(), 'models', 'silero_vad.onnx');
      }

      // Verify model is loadable by creating a test session
      const testSession = await this.ort.InferenceSession.create(this.modelPath);
      // Release the test session immediately
      testSession.release?.();

      this.initialized = true;
      this.logger.log(
        `Silero VAD factory initialized (model: ${this.modelPath}, threshold: ${this.config.threshold})`,
      );
    } catch (err: any) {
      this.logger.warn(
        `Silero VAD not initialized тАФ onnxruntime-node or model not found: ${err.message}`,
      );
      this.logger.warn(
        `Voice Robots will run without VAD. Ensure 'silero_vad.onnx' (v6) is placed in the 'models' directory.`,
      );
    }
  }

  onModuleDestroy(): void {
    this.ort = null;
    this.modelPath = null;
    this.initialized = false;
  }

  /**
   * Whether the VAD provider is available.
   */
  get isAvailable(): boolean {
    return this.initialized;
  }

  /**
   * Create an isolated VAD session instance for a specific call.
   *
   * Each session gets its own ONNX InferenceSession and LSTM state (_h, _c).
   * This prevents cross-session state contamination under concurrent load.
   *
   * The returned instance MUST be destroyed when the call session ends
   * to release ONNX resources.
   */
  async createSessionInstance(): Promise<VadSessionInstance> {
    if (!this.initialized || !this.ort || !this.modelPath) {
      throw new Error('SileroVadProvider not initialized');
    }

    const onnxSession = await this.ort.InferenceSession.create(this.modelPath);
    return new VadSessionInstance(this.ort, onnxSession, this.config.threshold);
  }

  /**
   * Get the default VAD config.
   */
  getDefaultConfig(): VadConfig {
    return { ...this.config };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { distance } from 'fastest-levenshtein';
import { ISlotDefinition, ISlotExtractionResult, ISlotChoice } from '../interfaces/bot-action.types';

/**
 * Slot Extractor Service тАФ Deterministic Function Calling (no LLM).
 *
 * Extracts structured data from STT text using rule-based methods:
 * - digits:   Russian verbal numbers тЖТ numeric string
 * - phone:    Phone number patterns
 * - yes_no:   Affirmative/negative phrase dictionaries
 * - date:     Date patterns + relative date words
 * - choice:   Levenshtein matching against predefined options
 * - freetext: Raw STT text passthrough
 *
 * Performance: ~0.1ms per extraction (CPU only, no ML).
 * Reliability: 100% deterministic тАФ same input always gives same output.
 */
@Injectable()
export class SlotExtractorService {
  private readonly logger = new Logger(SlotExtractorService.name);

  /**
   * Extract a slot value from STT-recognized text.
   */
  extract(text: string, slot: ISlotDefinition): ISlotExtractionResult {
    const normalized = text.toLowerCase().trim();

    switch (slot.type) {
      case 'digits':
        return this.extractDigits(normalized, slot.name);
      case 'phone':
        return this.extractPhone(normalized);
      case 'yes_no':
        return this.extractYesNo(normalized);
      case 'date':
        return this.extractDate(normalized);
      case 'choice':
        return this.extractChoice(normalized, slot.choices || []);
      case 'freetext':
        return {
          success: normalized.length > 0,
          value: text.trim(),
          rawText: text,
          confidence: normalized.length > 0 ? 1.0 : 0,
        };
      default:
        return { success: false, rawText: text, confidence: 0 };
    }
  }

  // тФАтФАтФА Digits extraction тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /** Map of Russian verbal numbers тЖТ numeric values */
  private static readonly VERBAL_NUMBERS: Record<string, number> = {
    '╨╜╨╛╨╗╤М': 0, '╨╜╤Г╨╗╤М': 0,
    '╨╛╨┤╨╕╨╜': 1, '╨╛╨┤╨╜╨░': 1, '╨╛╨┤╨╜╨╛': 1, '╤А╨░╨╖': 1,
    '╨┤╨▓╨░': 2, '╨┤╨▓╨╡': 2,
    '╤В╤А╨╕': 3,
    '╤З╨╡╤В╤Л╤А╨╡': 4,
    '╨┐╤П╤В╤М': 5,
    '╤И╨╡╤Б╤В╤М': 6,
    '╤Б╨╡╨╝╤М': 7,
    '╨▓╨╛╤Б╨╡╨╝╤М': 8,
    '╨┤╨╡╨▓╤П╤В╤М': 9,
    '╨┤╨╡╤Б╤П╤В╤М': 10,
    '╨╛╨┤╨╕╨╜╨╜╨░╨┤╤Ж╨░╤В╤М': 11,
    '╨┤╨▓╨╡╨╜╨░╨┤╤Ж╨░╤В╤М': 12,
    '╤В╤А╨╕╨╜╨░╨┤╤Ж╨░╤В╤М': 13,
    '╤З╨╡╤В╤Л╤А╨╜╨░╨┤╤Ж╨░╤В╤М': 14,
    '╨┐╤П╤В╨╜╨░╨┤╤Ж╨░╤В╤М': 15,
    '╤И╨╡╤Б╤В╨╜╨░╨┤╤Ж╨░╤В╤М': 16,
    '╤Б╨╡╨╝╨╜╨░╨┤╤Ж╨░╤В╤М': 17,
    '╨▓╨╛╤Б╨╡╨╝╨╜╨░╨┤╤Ж╨░╤В╤М': 18,
    '╨┤╨╡╨▓╤П╤В╨╜╨░╨┤╤Ж╨░╤В╤М': 19,
    '╨┤╨▓╨░╨┤╤Ж╨░╤В╤М': 20,
    '╤В╤А╨╕╨┤╤Ж╨░╤В╤М': 30,
    '╤Б╨╛╤А╨╛╨║': 40,
    '╨┐╤П╤В╤М╨┤╨╡╤Б╤П╤В': 50,
    '╤И╨╡╤Б╤В╤М╨┤╨╡╤Б╤П╤В': 60,
    '╤Б╨╡╨╝╤М╨┤╨╡╤Б╤П╤В': 70,
    '╨▓╨╛╤Б╨╡╨╝╤М╨┤╨╡╤Б╤П╤В': 80,
    '╨┤╨╡╨▓╤П╨╜╨╛╤Б╤В╨╛': 90,
    '╤Б╤В╨╛': 100,
    '╨┤╨▓╨╡╤Б╤В╨╕': 200,
    '╤В╤А╨╕╤Б╤В╨░': 300,
    '╤З╨╡╤В╤Л╤А╨╡╤Б╤В╨░': 400,
    '╨┐╤П╤В╤М╤Б╨╛╤В': 500,
    '╤И╨╡╤Б╤В╤М╤Б╨╛╤В': 600,
    '╤Б╨╡╨╝╤М╤Б╨╛╤В': 700,
    '╨▓╨╛╤Б╨╡╨╝╤М╤Б╨╛╤В': 800,
    '╨┤╨╡╨▓╤П╤В╤М╤Б╨╛╤В': 900,
    '╤В╤Л╤Б╤П╤З╨░': 1000, '╤В╤Л╤Б╤П╤З╤Г': 1000, '╤В╤Л╤Б╤П╤З╨╕': 1000,
  };

  /**
   * Extract digits from verbal Russian numbers or mixed text.
   * "╨┤╨▓╨╡╨╜╨░╨┤╤Ж╨░╤В╤М ╤В╤А╨╕╨┤╤Ж╨░╤В╤М ╤З╨╡╤В╤Л╤А╨╡" тЖТ "1234"
   * "╨╛╨┤╨╕╨╜ ╨┤╨▓╨░ ╤В╤А╨╕" тЖТ "123"  (single digits concatenated)
   * "455" тЖТ "455" (passthrough numeric)
   */
  private extractDigits(text: string, slotName?: string): ISlotExtractionResult {
    // Contextual pre-filtering: for named slots, extract text after relevant markers
    // e.g. "╨║╤А╨░╤Б╨╜╨╛╤П╤А╤Б╨║ ╤Б╤В╤А╨╛╨╕╤В╨╡╨╗╤М╨╜╨░╤П 18 ╨║╨▓╨░╤А╤В╨╕╤А╨░ 8" тЖТ extract "8" for apartment slot
    let effectiveText = text;
    if (slotName) {
      const markerMap: Record<string, RegExp> = {
        'apartment': /(?:╨║╨▓╨░╤А╤В╨╕╤А[╨░╤Л]|╨║╨▓\.?\s*)\s*/gi,
        'house':     /(?:╨┤╨╛╨╝|╨┤\.?\s*)\s*/gi,
      };
      const marker = markerMap[slotName];
      if (marker) {
        // Find the LAST occurrence of the marker and take text after it
        let lastIndex = -1;
        let match: RegExpExecArray | null;
        while ((match = marker.exec(text)) !== null) {
          lastIndex = match.index + match[0].length;
        }
        if (lastIndex > 0 && lastIndex < text.length) {
          effectiveText = text.substring(lastIndex).trim();
        }
      }
    }

    // 1. Try direct numeric extraction (STT sometimes returns digits)
    const directDigits = effectiveText.replace(/[^\d]/g, '');
    if (directDigits.length > 0) {
      return {
        success: true,
        value: directDigits,
        rawText: text,
        confidence: 1.0,
      };
    }

    // 2. Parse Russian verbal numbers
    const words = effectiveText.split(/\s+/).filter(w => w.length > 0);
    const numbers: number[] = [];
    let accumulated = 0;
    let hasNumber = false;

    for (const word of words) {
      const cleanWord = word.replace(/[^╨░-╤П╤С]/g, '');
      if (!cleanWord) continue;

      const num = SlotExtractorService.VERBAL_NUMBERS[cleanWord];
      if (num !== undefined) {
        hasNumber = true;

        // Single digits (0-9) тЖТ concatenate directly (for phone/account numbers)
        if (num <= 9 && accumulated === 0) {
          numbers.push(num);
        }
        // Tens/hundreds/thousands тЖТ accumulate for compound numbers
        else if (num >= 100 && num < 1000) {
          accumulated += num;
        } else if (num >= 1000) {
          accumulated = (accumulated || 1) * num;
        } else if (num >= 10) {
          // Check if previous accumulation has hundreds
          accumulated += num;
        } else {
          // Single digit after tens (e.g. ╨┤╨▓╨░╨┤╤Ж╨░╤В╤М + ╨╛╨┤╨╕╨╜ = 21)
          accumulated += num;
        }
      } else {
        // Flush accumulated compound number
        if (accumulated > 0) {
          numbers.push(accumulated);
          accumulated = 0;
        }
      }
    }

    // Flush remaining
    if (accumulated > 0) {
      numbers.push(accumulated);
    }

    if (!hasNumber) {
      return { success: false, rawText: text, confidence: 0 };
    }

    const result = numbers.join('');
    return {
      success: true,
      value: result,
      rawText: text,
      confidence: 0.9,
    };
  }

  // тФАтФАтФА Phone extraction тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Extract phone number from text.
   * Supports: +7XXXXXXXXXX, 8XXXXXXXXXX, verbal digits.
   */
  private extractPhone(text: string): ISlotExtractionResult {
    // Try regex first
    const phoneRegex = /(?:\+?[78])[\s\-]?\(?(\d{3})\)?[\s\-]?(\d{3})[\s\-]?(\d{2})[\s\-]?(\d{2})/;
    const match = text.match(phoneRegex);
    if (match) {
      const phone = `+7${match[1]}${match[2]}${match[3]}${match[4]}`;
      return { success: true, value: phone, rawText: text, confidence: 1.0 };
    }

    // Fallback to digits extraction
    const digitsResult = this.extractDigits(text);
    if (digitsResult.success && typeof digitsResult.value === 'string') {
      const digits = digitsResult.value;
      if (digits.length >= 10 && digits.length <= 11) {
        const phone = digits.startsWith('8') || digits.startsWith('7')
          ? `+7${digits.slice(-10)}`
          : `+7${digits}`;
        return { success: true, value: phone, rawText: text, confidence: 0.8 };
      }
    }

    return { success: false, rawText: text, confidence: 0 };
  }

  // тФАтФАтФА Yes/No extraction тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  private static readonly YES_WORDS = [
    '╨┤╨░', '╨║╨╛╨╜╨╡╤З╨╜╨╛', '╤А╨░╨╖╤Г╨╝╨╡╨╡╤В╤Б╤П', '╨▓╨╡╤А╨╜╨╛', '╨┐╤А╨░╨▓╨╕╨╗╤М╨╜╨╛',
    '╤Б╨╛╨│╨╗╨░╤Б╨╡╨╜', '╤Б╨╛╨│╨╗╨░╤Б╨╜╨░', '╨┐╨╛╨┤╤В╨▓╨╡╤А╨╢╨┤╨░╤О', '╨░╨│╨░', '╤Г╨│╤Г',
    '╤В╨╛╤З╨╜╨╛', '╨╕╨╝╨╡╨╜╨╜╨╛', '╤Е╨╛╤А╨╛╤И╨╛', '╨╗╨░╨┤╨╜╨╛', '╨╛╨║╨╡╨╣', '╨╛╨║',
    '╨┤╨░╨▓╨░╨╣', '╨┤╨░╨▓╨░╨╣╤В╨╡', '╨┐╨╛╨╢╨░╨╗╤Г╨╣', '╨╡╤Б╤В╨╡╤Б╤В╨▓╨╡╨╜╨╜╨╛',
  ];

  private static readonly NO_WORDS = [
    '╨╜╨╡╤В', '╨╜╨╡', '╨╜╨╡╨░', '╨╜╨╡╤В╤Г', '╨╛╤В╨║╨░╨╖', '╨╛╤В╨║╨░╨╖╤Л╨▓╨░╤О╤Б╤М',
    '╨╜╨╡ ╨╜╨░╨┤╨╛', '╨╜╨╡ ╨╜╤Г╨╢╨╜╨╛', '╨╜╨╡ ╤Е╨╛╤З╤Г', '╨╜╨╡ ╨▒╤Г╨┤╤Г', '╨╜╨╕ ╨▓ ╨║╨╛╨╡╨╝',
    '╨╜╨╕╨║╨╛╨│╨┤╨░', '╨╛╤В╨╝╨╡╨╜╨░', '╤Б╤В╨╛╨┐', '╤Е╨▓╨░╤В╨╕╤В',
  ];

  /**
   * Extract yes/no boolean from text.
   */
  private extractYesNo(text: string): ISlotExtractionResult {
    const words = text.split(/\s+/);

    // Check negative first (more specific)
    for (const noPhrase of SlotExtractorService.NO_WORDS) {
      if (text.includes(noPhrase)) {
        return { success: true, value: false, rawText: text, confidence: 0.95 };
      }
    }

    for (const yesWord of SlotExtractorService.YES_WORDS) {
      for (const word of words) {
        if (word === yesWord || this.fuzzyMatch(word, yesWord, 0.8)) {
          return { success: true, value: true, rawText: text, confidence: 0.95 };
        }
      }
    }

    return { success: false, rawText: text, confidence: 0 };
  }

  // тФАтФАтФА Date extraction тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  private static readonly RELATIVE_DATES: Record<string, (now: Date) => Date> = {
    '╤Б╨╡╨│╨╛╨┤╨╜╤П': (now) => now,
    '╨╖╨░╨▓╤В╤А╨░': (now) => new Date(now.getTime() + 86400000),
    '╨┐╨╛╤Б╨╗╨╡╨╖╨░╨▓╤В╤А╨░': (now) => new Date(now.getTime() + 2 * 86400000),
    '╨▓╤З╨╡╤А╨░': (now) => new Date(now.getTime() - 86400000),
    '╨┐╨╛╨╖╨░╨▓╤З╨╡╤А╨░': (now) => new Date(now.getTime() - 2 * 86400000),
  };

  private static readonly MONTHS: Record<string, number> = {
    '╤П╨╜╨▓╨░╤А': 0, '╤Д╨╡╨▓╤А╨░╨╗': 1, '╨╝╨░╤А╤В': 2, '╨░╨┐╤А╨╡╨╗': 3,
    '╨╝╨░': 4, '╨╕╤О╨╜': 5, '╨╕╤О╨╗': 6, '╨░╨▓╨│╤Г╤Б╤В': 7,
    '╤Б╨╡╨╜╤В╤П╨▒╤А': 8, '╨╛╨║╤В╤П╨▒╤А': 9, '╨╜╨╛╤П╨▒╤А': 10, '╨┤╨╡╨║╨░╨▒╤А': 11,
  };

  /**
   * Extract date from text.
   * Supports: "╨╖╨░╨▓╤В╤А╨░", "15 ╨░╨┐╤А╨╡╨╗╤П", "2025-04-15".
   */
  private extractDate(text: string): ISlotExtractionResult {
    const now = new Date();

    // ISO date passthrough
    const isoMatch = text.match(/(\d{4})-(\d{2})-(\d{2})/);
    if (isoMatch) {
      return { success: true, value: isoMatch[0], rawText: text, confidence: 1.0 };
    }

    // Relative dates
    for (const [word, resolver] of Object.entries(SlotExtractorService.RELATIVE_DATES)) {
      if (text.includes(word)) {
        const date = resolver(now);
        return {
          success: true,
          value: date.toISOString().split('T')[0],
          rawText: text,
          confidence: 0.95,
        };
      }
    }

    // "15 ╨░╨┐╤А╨╡╨╗╤П", "3 ╨╝╨░╤А╤В╨░"
    const dateRegex = /(\d{1,2})\s+([╨░-╤П╤С]+)/;
    const dateMatch = text.match(dateRegex);
    if (dateMatch) {
      const day = parseInt(dateMatch[1]);
      const monthWord = dateMatch[2];

      for (const [prefix, monthIdx] of Object.entries(SlotExtractorService.MONTHS)) {
        if (monthWord.startsWith(prefix)) {
          const year = now.getFullYear();
          const date = new Date(year, monthIdx, day);
          // If date is in the past, assume next year
          if (date < now) date.setFullYear(year + 1);

          return {
            success: true,
            value: date.toISOString().split('T')[0],
            rawText: text,
            confidence: 0.9,
          };
        }
      }
    }

    return { success: false, rawText: text, confidence: 0 };
  }

  // тФАтФАтФА Choice extraction тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Extract a choice from predefined options using Levenshtein similarity.
   */
  private extractChoice(text: string, choices: ISlotChoice[]): ISlotExtractionResult {
    if (choices.length === 0) {
      return { success: false, rawText: text, confidence: 0 };
    }

    let bestChoice: ISlotChoice | null = null;
    let bestSimilarity = 0;

    for (const choice of choices) {
      // Check canonical value
      const valueSim = this.phraseSimilarity(text, choice.value.toLowerCase());
      if (valueSim > bestSimilarity) {
        bestSimilarity = valueSim;
        bestChoice = choice;
      }

      // Check all synonyms
      for (const synonym of choice.synonyms) {
        const synSim = this.phraseSimilarity(text, synonym.toLowerCase());
        if (synSim > bestSimilarity) {
          bestSimilarity = synSim;
          bestChoice = choice;
        }
      }
    }

    if (bestChoice && bestSimilarity >= 0.6) {
      return {
        success: true,
        value: bestChoice.value,
        rawText: text,
        confidence: bestSimilarity,
      };
    }

    return { success: false, rawText: text, confidence: 0 };
  }

  // тФАтФАтФА Utilities тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Phrase-level similarity: checks if target phrase is contained in text
   * or measures overall word overlap.
   */
  private phraseSimilarity(text: string, phrase: string): number {
    // Exact containment
    if (text.includes(phrase)) return 1.0;

    const textWords = text.split(/\s+/);
    const phraseWords = phrase.split(/\s+/);

    let matched = 0;
    for (const pw of phraseWords) {
      for (const tw of textWords) {
        if (this.fuzzyMatch(tw, pw, 0.75)) {
          matched++;
          break;
        }
      }
    }

    return phraseWords.length > 0 ? matched / phraseWords.length : 0;
  }

  /**
   * Fuzzy match two words using Levenshtein distance.
   */
  private fuzzyMatch(a: string, b: string, threshold: number): boolean {
    if (a === b) return true;
    const maxLen = Math.max(a.length, b.length);
    if (maxLen === 0) return true;
    const similarity = 1 - distance(a, b) / maxLen;
    return similarity >= threshold;
  }
}

import { Logger } from '@nestjs/common';
import { AriHttpClientService, Channel, Bridge } from '../../ari/ari-http-client.service';
import { RtpUdpServerService, RtpSession } from './rtp-udp-server.service';
import { SileroVadProvider, VadSessionInstance } from './silero-vad.provider';
import { KeywordMatcherService, MatchResult } from './keyword-matcher.service';
import { SlotExtractorService } from './slot-extractor.service';
import { StreamingSttService } from './streaming-stt.service';
import { StreamAudioService } from './stream-audio.service';
import { AudioService } from './audio.service';
import { TtsCacheService } from './tts-cache.service';
import { TtsProviderFactory } from '../providers/provider-factory';
import { SttProviderFactory } from '../providers/provider-factory';
import { TtsEngine } from '../../tts-engines/tts-engine.model';
import { SttEngine } from '../../stt-engines/stt-engine.model';
import { SttStream } from '../interfaces/stt-provider.interface';
import { VoiceRobot } from '../voice-robot.model';
import { VoiceRobotKeyword } from '../keyword.model';
import { VoiceRobotKeywordGroup } from '../keyword-group.model';
import { VoiceRobotLog } from '../voice-robot-log.model';
import { VoiceRobotCdr } from '../voice-robot-cdr.model';
import { VoiceRobotDataList } from '../data-list.model';
import { IVoiceRobotBotAction, ISlotDefinition } from '../interfaces/bot-action.types';
import { DataListSearchService } from './data-list-search.service';
import { abortTtsPipeline, createSerialQueue, isTtsPipelineAborted } from './tts-pipeline-abort';
import { randomUUID } from 'crypto';

/** Caller info passed from StasisStart event */
export interface CallerInfo {
  callerId: string | null;
  callerName: string | null;
  callUniqueId: string | null;
}

/**
 * Per-call Voice Robot session.
 *
 * Lifecycle:
 * 1. ARI StasisStart тЖТ new VoiceRobotSession()
 * 2. start() тЖТ answer тЖТ bridge тЖТ externalMedia тЖТ greeting тЖТ VAD loop
 * 3. VAD detects speech тЖТ STT тЖТ KeywordMatcher тЖТ route or retry
 * 4. ARI StasisEnd тЖТ cleanup()
 *
 * Production patterns ported from aiPBX:
 * - Bridge flow (createBridge тЖТ addChannel тЖТ externalMedia тЖТ addChannel)
 * - Pre-speech ring buffer (captures ~300ms before VAD trigger)
 * - Step counter with max_conversation_steps
 * - Max duration watchdog
 * - Barge-in via AbortController
 * - Idempotent cleanup (bridge destroy, external channel hangup)
 * - Two-phase RTP init (wait for ChannelVarset with UNICASTRTP params)
 * - Per-session VAD instance (isolated LSTM state)
 */
export class VoiceRobotSession {
  private readonly logger = new Logger(VoiceRobotSession.name);

  // ARI resources (must be cleaned up)
  private bridge: Bridge | null = null;
  private externalChannel: Channel | null = null;
  private rtpSession: RtpSession | null = null;

  // VAD тАФ per-session isolated instance
  private vadInstance: VadSessionInstance | null = null;

  // VAD state
  private isSpeaking = false;
  private silenceTimer: NodeJS.Timeout | null = null;
  private sttBuffer: Buffer[] = [];

  // Pre-speech ring buffer
  private readonly preSpeechRingBuffer: Buffer[] = [];
  private readonly PRE_SPEECH_FRAMES: number;

  // Step counter
  private stepCount = 0;
  private readonly maxSteps: number;

  // Max duration watchdog
  private maxDurationTimer: NodeJS.Timeout | null = null;

  // Barge-in
  private pipelineAbort: AbortController | null = null;
  private isBotSpeaking = false;
  /** One utterance/action at a time тАФ overlapping STT finals used to double-fire nextState. */
  private readonly enqueueUtterance = createSerialQueue();

  // Inactivity detection тАФ repeat question if user is silent
  private inactivityTimer: NodeJS.Timeout | null = null;
  private inactivityRepeatCount = 0;
  private inactivityFallbackCycles = 0; // Global counter: how many times inactivity triggered fallback
  private static readonly MAX_INACTIVITY_FALLBACK_CYCLES = 3;
  private lastBotResponse: { type: string; value?: string } | null = null;

  // RTP params (filled asynchronously by ChannelVarset events)
  private rtpAddress: string | null = null;
  private rtpPort: number | null = null;

  // Cleanup guard
  private cleanedUp = false;

  // тФАтФАтФА CDR tracking тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА
  private readonly sessionId = randomUUID();
  private readonly startedAt = new Date();
  private readonly transcript: string[] = [];
  private noMatchCount = 0;
  private consecutiveNoMatchCount = 0;  // Resets on successful match
  private totalConfidence = 0;
  private totalMatches = 0;
  private cdrDisposition: 'completed' | 'caller_hangup' | 'fallback' | 'max_steps' | 'error' | 'timeout' = 'completed';
  private lastActionType: string | null = null;
  private lastTransferTarget: string | null = null;
  private informationDelivered = false;  // Set when caller receives data (data list found, webhook success)

  // Active keyword set (can change via switch_group)
  private activeKeywords: VoiceRobotKeyword[];

  // Global keywords (always active regardless of current group)
  private readonly globalKeywords: VoiceRobotKeyword[];

  // Dialogue context тАФ persistent session memory, sent to every webhook
  private dialogueContext: Record<string, any> = {};

  // Group navigation stack (for "go back" support in switch_group)
  private groupStack: number[] = [];

  // Tags: names of keyword groups visited during the session
  private visitedTags: string[] = [];

  // Streaming STT session (null = batch mode)
  private sttStream: SttStream | null = null;
  private sttStreamFinalText = '';
  private sttStreamPartialText = '';

  // Keyword repetition counter for escalation
  private keywordHitCounts: Record<number, number> = {};

  // Data list search not-found retry counter (keyed by listId)
  private dataListNotFoundCounts: Record<number, number> = {};

  // Webhook continue_dialogue loop detector (keyed by URL)
  private webhookContinueCounts: Record<string, number> = {};

  /** Last STT text тАФ sent to webhooks as `utterance` and used to prefill silent freetext slots */
  private lastRecognizedText: string | null = null;

  // Slot filling state
  private slotFillingState: {
    action: IVoiceRobotBotAction;
    keyword: VoiceRobotKeyword;
    slots: ISlotDefinition[];
    filledSlots: Record<string, string | boolean>;
    currentSlotIndex: number;
    retryCount: number;
  } | null = null;

  // Data list search state тАФ when set, the next utterance is used as search query
  private pendingDataListSearch: {
    action: IVoiceRobotBotAction;
    filledSlots: Record<string, string | boolean>;
  } | null = null;

  /** Tenant ID (vpbx_user_uid) for context/queue name resolution */
  private readonly tenantId: number;

  /**
   * Resolve a tenant-aware Asterisk context.
   * Convention from dialplan.util.ts: `${contextBase}${vpbxUserUid}`
   * Examples: "sip-out" тЖТ "sip-out1", "ctx-" тЖТ "ctx-1"
   * If no context provided, uses the internal context "ctx-{tenantId}".
   */
  private resolveContext(context?: string): string {
    if (!context) return `ctx-${this.tenantId}`;
    // If context already ends with tenantId string, don't double-add
    const suffix = String(this.tenantId);
    if (context.endsWith(suffix)) return context;
    return `${context}${this.tenantId}`;
  }

  constructor(
    private readonly ariClient: AriHttpClientService,
    private readonly udpServer: RtpUdpServerService,
    private readonly vadProvider: SileroVadProvider,
    private readonly sttService: StreamingSttService,
    private readonly matcherService: KeywordMatcherService,
    private readonly slotExtractor: SlotExtractorService,
    private readonly streamAudio: StreamAudioService,
    private readonly audioService: AudioService,
    private readonly ttsFactory: TtsProviderFactory,
    private readonly ttsCache: TtsCacheService,
    private readonly ttsEngine: TtsEngine | null,
    private readonly sttProviderFactory: SttProviderFactory,
    private readonly sttEngine: SttEngine | null,
    private readonly channelId: string,
    private readonly robotConfig: VoiceRobot,
    private readonly keywordsDb: VoiceRobotKeyword[],
    private readonly keywordGroupsDb: VoiceRobotKeywordGroup[],
    private readonly externalHost: string,
    private readonly logModel: typeof VoiceRobotLog,
    private readonly cdrModel: typeof VoiceRobotCdr,
    private readonly callerInfo: CallerInfo,
    private readonly dataListSearchService: DataListSearchService | null,
    private readonly dataListsDb: VoiceRobotDataList[],
  ) {
    const config = this.robotConfig.vad_config || {};
    this.PRE_SPEECH_FRAMES = Math.ceil((config.prefix_padding_ms || 300) / 32);
    this.maxSteps = this.robotConfig.max_conversation_steps || 10;
    this.tenantId = this.robotConfig.user_uid;

    // тФАтФАтФА FSM Initialization: activate only initial group + globals тФАтФАтФА
    // Global keywords are always active in every dialogue state
    const globalGroupIds = this.keywordGroupsDb
      .filter(g => g.is_global === 1)
      .map(g => g.uid);
    this.globalKeywords = this.keywordsDb.filter(k => globalGroupIds.includes(k.group_id));

    // Initial group = explicitly set via initial_group_id, fallback to first non-global
    const initialGroupId = this.robotConfig.initial_group_id;
    const initialGroup = initialGroupId
      ? this.keywordGroupsDb.find(g => g.uid === initialGroupId)
      : this.keywordGroupsDb.filter(g => g.is_global !== 1)[0];

    if (initialGroup) {
      const initialKeywords = this.keywordsDb.filter(k => k.group_id === initialGroup.uid);
      this.activeKeywords = [...initialKeywords, ...this.globalKeywords];
      this.logger.log(`[FSM] Initial group: "${initialGroup.name}" (id=${initialGroup.uid}, ${initialKeywords.length} keywords + ${this.globalKeywords.length} global)`);
      this.visitedTags.push(initialGroup.name);
    } else {
      // Fallback: all keywords (backwards compat if no groups configured properly)
      this.activeKeywords = [...this.keywordsDb];
      this.logger.warn(`[FSM] No initial group found, activating all ${this.keywordsDb.length} keywords`);
    }
  }

  /**
   * Initialize the call session: answer, bridge, ExternalMedia, greet.
   */
  async start() {
    this.logger.log(`Starting Voice Robot Session for channel ${this.channelId}`);

    try {
      // 0. Create per-session VAD instance (isolated LSTM state)
      if (this.vadProvider.isAvailable) {
        this.vadInstance = await this.vadProvider.createSessionInstance();
        this.logger.log(`VAD session instance created for ${this.channelId}`);
      } else {
        this.logger.warn(`VAD not available тАФ session ${this.channelId} will run without VAD`);
      }

      // 1. Answer channel
      await this.ariClient.answerChannel(this.channelId);

      // 2. Create mixing bridge
      this.bridge = await this.ariClient.createBridge('mixing');
      this.logger.log(`Bridge created: ${this.bridge.id}`);

      // 3. Add primary channel to bridge
      await this.ariClient.addChannelToBridge(this.bridge.id, this.channelId);

      // 4. Create RTP UDP session (ephemeral port)
      this.rtpSession = await this.udpServer.createSession();

      // 5. Create ExternalMedia channel тЖТ Asterisk will stream RTP to our UDP port
      //    The 'data' param passes our channelId so ChannelVarset events can be routed back
      this.externalChannel = await this.ariClient.externalMedia(
        null, // Asterisk assigns channel ID
        this.ariClient.getAppName(),
        `${this.externalHost}:${this.rtpSession.port}`,
        'alaw',
        this.channelId, // data = parent channel ID for routing
      );
      this.logger.log(`ExternalMedia channel: ${this.externalChannel.id} тЖТ port ${this.rtpSession.port}`);

      // 6. Add ExternalMedia channel to the SAME bridge
      await this.ariClient.addChannelToBridge(this.bridge.id, this.externalChannel.id);

      // 7. Extract RTP params from channel vars (may come synchronously or via ChannelVarset event)
      const vars = this.externalChannel.channelvars || {};
      if (vars.UNICASTRTP_LOCAL_ADDRESS && vars.UNICASTRTP_LOCAL_PORT) {
        this.rtpAddress = vars.UNICASTRTP_LOCAL_ADDRESS;
        this.rtpPort = Number(vars.UNICASTRTP_LOCAL_PORT);
      }

      // 8. Initialize StreamAudio for TTS playback (if RTP params already known)
      if (this.rtpAddress && this.rtpPort) {
        this.streamAudio.addStream(this.channelId, this.rtpAddress, this.rtpPort);
      }

      // 9. Hook VAD audio processing FIRST тАФ so we can hear during greeting
      this.setupAudioPipeline();

      // 10. Play greeting (VAD is already attached and will gate via isBotSpeaking)
      await this.playGreeting();

      this.logger.log(`Session ${this.channelId} fully initialized`);

    } catch (e: any) {
      this.logger.error(`Failed to start session: ${e.message}`, e.stack);
      this.cleanup();
    }
  }

  /**
   * Called when ChannelVarset provides UNICASTRTP_LOCAL_ADDRESS/PORT asynchronously.
   */
  updateRtpParams(variable: string, value: string): void {
    if (variable === 'UNICASTRTP_LOCAL_ADDRESS') {
      this.rtpAddress = value;
    } else if (variable === 'UNICASTRTP_LOCAL_PORT') {
      this.rtpPort = Number(value);
    }

    // Once both are known, initialize the StreamAudio sender
    if (this.rtpAddress && this.rtpPort) {
      this.streamAudio.addStream(this.channelId, this.rtpAddress, this.rtpPort);
      this.logger.log(`RTP params resolved: ${this.rtpAddress}:${this.rtpPort}`);
    }
  }

  /**
   * Play greeting prompt or TTS.
   */
  private async playGreeting(): Promise<void> {
    // Greeting via pre-recorded prompts
    if (this.robotConfig.greeting_prompts && Array.isArray(this.robotConfig.greeting_prompts)) {
      for (const prompt of this.robotConfig.greeting_prompts) {
        try {
          await this.ariClient.playMedia(this.channelId, prompt);
        } catch (e: any) {
          this.logger.warn(`Failed to play greeting prompt "${prompt}": ${e.message}`);
        }
      }
    }

    // TTS greeting
    if (this.robotConfig.greeting_tts_text) {
      await this.speakResponse({ type: 'tts', value: this.robotConfig.greeting_tts_text });
    }
  }

  /**
   * Connect RTP audio events to VAD + STT processing.
   *
   * Two modes controlled by `robotConfig.stt_mode`:
   *
   * 1. **hybrid** (default, recommended):
   *    - Silero VAD runs locally, detects speech start/end.
   *    - gRPC stream opened at session start, but audio piped ONLY during speech.
   *    - VAD silence triggers buffer flush тЖТ keyword match.
   *    - Cost-efficient: stream idles during silence.
   *
   * 2. **full_stream**:
   *    - No local VAD. gRPC stream receives ALL audio frames.
   *    - Yandex detects speech/silence internally via EOU events.
   *    - Zero local latency, but higher API cost (continuous stream).
   */
  private setupAudioPipeline(): void {
    if (!this.rtpSession) return;

    const isFullStream = this.robotConfig.stt_mode === 'full_stream';
    const supportsStreaming = this.sttEngine && this.sttProviderFactory.isStreamingSupported(this.sttEngine);

    // тФАтФАтФА Open gRPC stream (both modes need it if engine supports streaming) тФАтФАтФА
    if (supportsStreaming) {
      this.initStreamingStt();
    }

    if (isFullStream && supportsStreaming) {
      // тХРтХРтХР Full-Stream Mode тХРтХРтХР
      // No VAD processing. All audio goes directly to gRPC stream.
      // Yandex handles speech detection via internal EOU logic.
      this.logger.log('[Pipeline] Full-stream STT mode: VAD disabled, all audio тЖТ gRPC');

      this.rtpSession.eventEmitter.on('audio-pcm16', (pcm: Buffer) => {
        if (this.sttStream) {
          this.sttStream.write(pcm);
        }
        // Still accumulate for fallback (if stream dies mid-session)
        this.sttBuffer.push(pcm);
      });

      // No audio-float32 handler тАФ VAD completely bypassed
    } else {
      // тХРтХРтХР Hybrid Mode (default) тХРтХРтХР
      // Audio ALWAYS flows to STT stream ("always listening").
      // VAD is used only for speech start/end detection and barge-in.
      this.logger.log('[Pipeline] Hybrid STT mode: always-on stream + VAD silence detection');

      // VAD processing on Float32 frames (per-session instance)
      this.rtpSession.eventEmitter.on('audio-float32', async (frame: Float32Array) => {
        if (!this.vadInstance) return;

        try {
          const result = await this.vadInstance.processFrame(frame);
          this.handleVadResult(result.probability);
        } catch (e: any) {
          this.logger.error(`VAD processing error: ${e.message}`);
        }
      });

      // Always pipe PCM16 to STT stream тАФ no deaf gaps
      this.rtpSession.eventEmitter.on('audio-pcm16', (pcm: Buffer) => {
        // Always pipe to gRPC stream (keeps it alive, captures all speech)
        if (this.sttStream) {
          this.sttStream.write(pcm);
        }

        if (this.isSpeaking) {
          this.sttBuffer.push(pcm);
        } else {
          // Pre-speech ring buffer (for batch fallback)
          this.preSpeechRingBuffer.push(pcm);
          if (this.preSpeechRingBuffer.length > this.PRE_SPEECH_FRAMES) {
            this.preSpeechRingBuffer.shift();
          }
        }
      });
    }
  }

  /**
   * Initialize a persistent streaming STT session.
   * Listens for 'final' and 'eou' events from the gRPC stream.
   *
   * In streaming mode:
   * - VAD speech start тЖТ pre-speech buffer flushed to stream
   * - Each audio frame is piped to stream.write()
   * - On EOU (end of utterance) тЖТ process recognized text
   * - On speech end (VAD silence) тЖТ if no EOU yet, wait for final
   */
  private initStreamingStt(): void {
    if (!this.sttEngine) return;
    // Guard: don't create a duplicate stream if one already exists
    if (this.sttStream) return;

    try {
      this.sttStream = this.sttProviderFactory.createStream(
        this.sttEngine,
        this.robotConfig.language || 'ru-RU',
      );

      const currentStream = this.sttStream;

      this.sttStreamFinalText = '';
      this.sttStreamPartialText = '';

      currentStream.events.on('partial', (text: string) => {
        if (this.sttStream !== currentStream) return;
        this.logger.debug(`[STT/stream] Partial: "${text}"`);
        this.sttStreamPartialText = text;
      });

      currentStream.events.on('final', (text: string) => {
        if (this.sttStream !== currentStream) return;
        this.logger.log(`[STT/stream] Final: "${text}"`);
        this.sttStreamFinalText = text;
      });

      // Normalized text from final_refinement (numbers as digits, etc.)
      // May arrive before or after EOU тАФ we handle both cases
      currentStream.events.on('normalized', (text: string) => {
        if (this.sttStream !== currentStream) return;
        this.logger.log(`[STT/stream] Normalized: "${text}"`);
        this.sttStreamFinalText = text;
      });

      currentStream.events.on('eou', () => {
        if (this.sttStream !== currentStream) return;
        // Discard EOU events while bot is speaking тАФ text is echo from TTS playback
        if (this.isBotSpeaking) {
          this.logger.debug(`[STT/stream] EOU ignored тАФ bot is speaking (echo)`);
          this.sttStreamFinalText = '';
          this.sttStreamPartialText = '';
          return;
        }
        // End of utterance detected by the provider's EOU classifier
        if (this.sttStreamFinalText || this.sttStreamPartialText) {
          const text = this.sttStreamFinalText || this.sttStreamPartialText;
          this.logger.log(`[STT/stream] EOU тЖТ processing: "${text}"`);
          this.sttStreamFinalText = '';
          this.sttStreamPartialText = '';
          void this.enqueueUtterance(() => this.handleStreamingSttResult(text));
        }
      });

      currentStream.events.on('error', (err: Error) => {
        if (this.sttStream !== currentStream) return;
        this.logger.error(`[STT/stream] Error: ${err.message}`);
        this.sttStream = null;
        // Auto-recreate after error (keep always-on)
        if (!this.cleanedUp) {
          setTimeout(() => this.initStreamingStt(), 200);
        }
      });

      currentStream.events.on('end', () => {
        if (this.sttStream !== currentStream) return;
        this.logger.debug('[STT/stream] Stream ended тАФ recreating');
        this.sttStream = null;
        // Auto-recreate so we're always listening
        if (!this.cleanedUp) {
          setTimeout(() => this.initStreamingStt(), 50);
        }
      });

      this.logger.log(`[STT/stream] Streaming STT initialized (engine: ${this.sttEngine.type})`);
    } catch (e: any) {
      this.logger.error(`[STT/stream] Failed to initialize: ${e.message}`);
      this.sttStream = null;
    }
  }

  /**
   * Handle a completed utterance from the streaming STT.
   * Same pipeline as batch mode: keyword match тЖТ bot action.
   */
  private async handleStreamingSttResult(text: string): Promise<void> {
    if (this.cleanedUp) return;
    // Guard: ignore STT results while bot is speaking тАФ these are TTS echo
    if (this.isBotSpeaking) {
      this.logger.debug(`[STT/stream] Ignoring result during TTS playback (echo): "${text.substring(0, 40)}..."`);
      return;
    }

    // User is actively providing input тАФ cancel inactivity timer to prevent
    // it firing while we wait for a slow webhook response.
    this.clearInactivityTimer();

    this.stepCount++;
    this.logger.log(`[STT/stream] Step ${this.stepCount}/${this.maxSteps}`);

    const sttResult = { text, rawJson: { streaming: true } };
    await this.handleRecognizedText(text, sttResult, 0);

    if (this.stepCount >= this.maxSteps) {
      this.logger.warn(`[Session] Max steps (${this.maxSteps}) reached`);
      this.exitToFallback('MAX_RETRIES');
    }
  }

  /**
   * VAD probability handler тАФ Finite State Machine.
   */
  private handleVadResult(prob: number): void {
    const config = this.robotConfig.vad_config || {};
    const speechThreshold = config.speech_threshold || 0.5;
    const silenceThreshold = config.silence_threshold || 0.3;
    const silenceTimeoutMs = config.silence_timeout_ms || 2000;

    // While bot is speaking, only handle barge-in (speech detection that
    // interrupts the bot). Skip all other VAD state transitions to avoid
    // the bot's own RTP echo from triggering phantom STT sessions.
    if (this.isBotSpeaking) {
      if (prob >= speechThreshold && !this.isSpeaking && (config.barge_in !== false)) {
        this.logger.log(`[VAD] Barge-in тАФ interrupting bot speech`);
        this.abortPipeline();
        this.streamAudio.interruptStream(this.channelId);

        // Transition to "speech started" so the user's barge-in utterance
        // gets captured by STT. Without this, VAD would return early and
        // the user's speech would be lost (no partials, no silence timer).
        this.isSpeaking = true;
        this.clearInactivityTimer();

        if (this.silenceTimer) {
          clearTimeout(this.silenceTimer);
          this.silenceTimer = null;
        }

        // Ensure STT stream exists
        if (!this.sttStream) {
          this.initStreamingStt();
        }

        // Restore pre-speech ring buffer for batch fallback
        this.sttBuffer = [...this.preSpeechRingBuffer];
        this.preSpeechRingBuffer.length = 0;

        // Start max duration watchdog
        if (this.maxDurationTimer) {
          clearTimeout(this.maxDurationTimer);
        }
        const maxDurationSec = config.max_duration_seconds || 15;
        this.maxDurationTimer = setTimeout(() => {
          this.logger.warn(`[VAD] Max duration ${maxDurationSec}s reached тАФ forcefully cutting off speaker`);
          this.isSpeaking = false;
          this.maxDurationTimer = null;
          this.processSttBuffer();
        }, maxDurationSec * 1000);
      }
      return;
    }

    if (prob >= speechThreshold && !this.isSpeaking) {
      // тФАтФАтФА SPEECH START тФАтФАтФА
      this.logger.log(`[VAD] Speech started (prob: ${prob.toFixed(2)})`);
      this.isSpeaking = true;

      // Ensure STT stream exists (recreate if Yandex closed it)
      if (!this.sttStream) {
        this.initStreamingStt();
      }

      // Cancel inactivity timer тАФ user is responding
      this.clearInactivityTimer();

      if (this.silenceTimer) {
        clearTimeout(this.silenceTimer);
        this.silenceTimer = null;
      }

      // Start max duration watchdog for this speech segment
      if (this.maxDurationTimer) {
        clearTimeout(this.maxDurationTimer);
      }
      const maxDurationSec = config.max_duration_seconds || 15;
      this.maxDurationTimer = setTimeout(() => {
        this.logger.warn(`[VAD] Max duration ${maxDurationSec}s reached тАФ forcefully cutting off speaker`);
        this.isSpeaking = false;
        this.maxDurationTimer = null;
        this.processSttBuffer();
      }, maxDurationSec * 1000);


      // Restore pre-speech frames into STT buffer for batch fallback
      this.sttBuffer = [...this.preSpeechRingBuffer];
      this.preSpeechRingBuffer.length = 0;

    } else if (prob <= silenceThreshold && this.isSpeaking) {
      // тФАтФАтФА SILENCE DURING SPEECH тФАтФАтФА
      // Use longer silence timeout when collecting freetext slot input (address, locality).
      // People naturally pause between address components (e.g., "╨║╨▓╨░╤А╤В╨╕╤А╨░" тЖТ pause тЖТ "28")
      // and the default 2000ms cuts them off mid-sentence.
      const currentSlotType = this.slotFillingState?.slots[this.slotFillingState.currentSlotIndex]?.type;
      const effectiveSilenceMs = currentSlotType === 'freetext'
        ? Math.max(silenceTimeoutMs, config.slot_silence_timeout_ms || 3500)
        : silenceTimeoutMs;

      if (!this.silenceTimer) {
        this.silenceTimer = setTimeout(() => {
          this.logger.log(`[VAD] Speech ended (silence timeout ${effectiveSilenceMs}ms${currentSlotType === 'freetext' ? ', freetext slot' : ''})`);
          this.isSpeaking = false;

          if (this.maxDurationTimer) {
            clearTimeout(this.maxDurationTimer);
            this.maxDurationTimer = null;
          }

          this.processSttBuffer();
        }, effectiveSilenceMs);
      }

    } else if (prob >= speechThreshold && this.isSpeaking) {
      // тФАтФАтФА CONTINUING SPEECH тФАтФАтФА
      if (this.silenceTimer) {
        clearTimeout(this.silenceTimer);
        this.silenceTimer = null;
      }
    }
  }

  /**
   * Process accumulated speech buffer through STT тЖТ KeywordMatcher.
   */
  private async processSttBuffer(): Promise<void> {
    // тФАтФАтФА Streaming Mode тФАтФАтФА
    if (this.sttStream) {
      // Guard: discard any buffered text during TTS playback (echo)
      if (this.isBotSpeaking) {
        this.logger.debug('[STT/stream] Discarding buffer тАФ bot is speaking (echo)');
        this.sttStreamFinalText = '';
        this.sttStreamPartialText = '';
        this.sttBuffer = [];
        return;
      }

      let textToProcess = '';
      if (this.sttStreamFinalText) {
        textToProcess = this.sttStreamFinalText;
      } else if (this.sttStreamPartialText) {
        textToProcess = this.sttStreamPartialText;
      }

      this.sttStreamFinalText = '';
      this.sttStreamPartialText = '';

      if (textToProcess) {
        this.sttBuffer = [];
        this.stepCount++;
        this.clearInactivityTimer(); // User spoke тАФ prevent timer during webhook
        this.logger.log(`[STT/stream] Silence-triggered: "${textToProcess}"`);

        // Close current stream тАФ auto-recreate handler will open a new one
        try { this.sttStream.end(); } catch {}
        this.sttStream = null;
        // Immediately recreate so we're listening during handleRecognizedText/TTS
        this.initStreamingStt();

        await this.enqueueUtterance(() =>
          this.handleRecognizedText(textToProcess, { text: textToProcess, rawJson: { streaming: true } }, 0),
        );
        if (this.stepCount >= this.maxSteps) {
          this.exitToFallback('MAX_RETRIES');
        }
        return;
      }

      // No text available
      this.sttBuffer = [];
      this.logger.debug('[STT/stream] No final or partial text at silence тАФ waiting for next utterance');
      return;
    }

    // тФАтФАтФА Batch Mode (legacy) тФАтФАтФА
    const totalPcm = Buffer.concat(this.sttBuffer);
    this.sttBuffer = [];

    // Check min voice duration
    const minMs = this.robotConfig.vad_config?.min_speech_duration_ms || 300;
    const minBytes = minMs * 16; // 8kHz * 2 bytes = 16 bytes/ms
    if (totalPcm.length < minBytes) {
      this.logger.debug(`[VAD] Ignored short noise (${totalPcm.length} bytes < ${minBytes})`);
      return;
    }

    this.stepCount++;
    this.logger.log(`[STT] Step ${this.stepCount}/${this.maxSteps}: Sending ${totalPcm.length} bytes to STT...`);

    const startTime = Date.now();
    const sttResult = await this.sttService.transcribe(
      totalPcm,
      this.robotConfig.language || 'ru-RU',
    );
    const sttDurationMs = Date.now() - startTime;

    if (sttResult.text) {
      this.logger.log(`[STT] Recognized: "${sttResult.text}" (${sttDurationMs}ms)`);
      await this.enqueueUtterance(() =>
        this.handleRecognizedText(sttResult.text, sttResult, sttDurationMs),
      );
    } else {
      this.logger.log(`[STT] No text recognized`);
      await this.writeLog(null, sttResult, sttDurationMs, null, 0);
    }

    // Check step limit
    if (this.stepCount >= this.maxSteps) {
      this.logger.warn(`[Session] Max steps (${this.maxSteps}) reached for ${this.channelId}`);
      this.exitToFallback('MAX_RETRIES');
    }
  }

  /**
   * Match recognized text against keyword database and route.
   * Supports both new bot_action format and legacy dialplan routing.
   */
  private async handleRecognizedText(
    text: string,
    sttResult: any,
    sttDurationMs: number,
  ): Promise<void> {
    if (this.cleanedUp) return;
    // Reset inactivity timer repeats since user responded
    this.inactivityRepeatCount = 0;
    this.inactivityFallbackCycles = 0;
    this.lastRecognizedText = text;

    // тФАтФАтФА If we're waiting for a search query, use this utterance directly тФАтФАтФА
    if (this.pendingDataListSearch) {
      // Filter out noise/phatic utterances тАФ not real search queries
      const noiseWords = new Set([
        '╨░╨╗╨╗╨╛', '╨┤╨░', '╨╜╨╡╤В', '╨░╨│╨░', '╤Г╨│╤Г', '╨╜╤Г', '╨╛╨╣', '╨░╨╗╨╛', '╤Б╨╗╤Г╤И╨░╤О',
        '╤З╤В╨╛', '╨░', '╤Н╨╣', '╤Е╨╝', '╨╝╨╝╨╝', '╤В╨░╨║', '╨╗╨░╨┤╨╜╨╛', '╤Е╨╛╤А╨╛╤И╨╛', '╨╛╨║',
      ]);
      const normalized = text.toLowerCase().replace(/[^╨░-╤П╤Сa-z\s]/g, '').trim();
      const words = normalized.split(/\s+/).filter(w => w.length > 0);
      const isNoise = words.length <= 2 && words.every(w => noiseWords.has(w));

      if (isNoise) {
        this.logger.log(`[DataListSearch] Ignoring noise utterance: "${text}" тАФ waiting for real query`);
        // Re-speak the last prompt so the user knows to answer
        if (this.lastBotResponse) {
          await this.speakResponse(this.lastBotResponse);
        }
        return; // Keep pendingDataListSearch active
      }

      const { action, filledSlots } = this.pendingDataListSearch;
      this.pendingDataListSearch = null;
      this.logger.log(`[DataListSearch] Got search utterance: "${text}"`);
      // Clear inactivity timer тАФ search can take seconds (embedding cache, semantic search)
      this.clearInactivityTimer();
      await this.executeDataListSearch(action, filledSlots, text);
      return;
    }

    // тФАтФАтФА If we're in slot filling mode, check global keywords first тФАтФАтФА
    if (this.slotFillingState) {
      const currentSlot = this.slotFillingState.slots[this.slotFillingState.currentSlotIndex];

      // For freetext slots, check if the user is saying a global keyword
      // (e.g. "╤Б╨╛╨╡╨┤╨╕╨╜╨╕ ╤Б ╨╛╨┐╨╡╤А╨░╤В╨╛╤А╨╛╨╝" while we're waiting for an address)
      if (currentSlot?.type === 'freetext' && this.globalKeywords.length > 0) {
        const globalMatch = await this.matcherService.match(
          text,
          this.globalKeywords,
          [],
        );
        if (globalMatch && globalMatch.confidence >= 0.7) {
          this.logger.log(
            `[Slot] Global keyword intercepted during slot filling: ` +
            `"${text}" тЖТ keyword ${globalMatch.keyword.uid} (confidence: ${globalMatch.confidence.toFixed(2)})`,
          );
          // Clear slot state тАФ global keyword takes priority
          this.slotFillingState = null;
          this.consecutiveNoMatchCount = 0;

          await this.writeLog(text, sttResult, sttDurationMs, globalMatch.keyword.uid, globalMatch.confidence, globalMatch.keyword.group_id);

          // Track tag
          const customTag = globalMatch.keyword.tag;
          if (customTag && !this.visitedTags.includes(customTag)) {
            this.visitedTags.push(customTag);
          }

          // Execute bot action
          const botAction = globalMatch.keyword.bot_action;
          if (botAction) {
            await this.executeBotAction(botAction, globalMatch, text);
          }
          return;
        }
      }

      await this.handleSlotInput(text, sttResult, sttDurationMs);
      return;
    }

    // тФАтФАтФА Keyword matching тФАтФАтФА
    const negativePhrases = this.activeKeywords
      .flatMap(k => k.negative_keywords || [])
      .filter(Boolean);

    const matchResult = await this.matcherService.match(
      text,
      this.activeKeywords,
      negativePhrases,
    );

    if (matchResult) {
      this.logger.log(
        `[Matcher] тЬЕ Matched keyword ${matchResult.keyword.uid} ` +
        `(confidence: ${matchResult.confidence.toFixed(2)}, method: ${matchResult.method})`,
      );

      await this.writeLog(text, sttResult, sttDurationMs, matchResult.keyword.uid, matchResult.confidence, matchResult.keyword.group_id);

      // Reset consecutive no-match counter on successful match
      this.consecutiveNoMatchCount = 0;

      // Track custom keyword tag (if set) or group name
      const customTag = matchResult.keyword.tag;
      if (customTag && !this.visitedTags.includes(customTag)) {
        this.visitedTags.push(customTag);
      } else if (!customTag) {
        // Fallback: use group name (only if no custom tag)
        const groupMeta = this.keywordGroupsDb.find(g => g.uid === matchResult.keyword.group_id);
        if (groupMeta?.name && !this.visitedTags.includes(groupMeta.name)) {
          this.visitedTags.push(groupMeta.name);
        }
      }

      // тФАтФАтФА Keyword Escalation (Repeat limit) тФАтФАтФА
      const kwUid = matchResult.keyword.uid;
      this.keywordHitCounts[kwUid] = (this.keywordHitCounts[kwUid] || 0) + 1;

      let botAction: IVoiceRobotBotAction | null = matchResult.keyword.bot_action;
      const maxRepeats = matchResult.keyword.max_repeats || 0;

      if (maxRepeats > 0 && this.keywordHitCounts[kwUid] > maxRepeats) {
        this.logger.warn(`[Escalation] Keyword ${kwUid} repeated ${this.keywordHitCounts[kwUid]} times (limit ${maxRepeats}). Executing escalation_action.`);
        botAction = matchResult.keyword.escalation_action || botAction;
      }

      if (botAction) {
        await this.executeBotAction(botAction, matchResult, text);
      } else {
        // тФАтФАтФА Legacy: exit to dialplan тФАтФАтФА
        await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'SUCCESS');
        await this.ariClient.continueInDialplan(
          this.channelId,
          `voicerobot_keyword_${matchResult.keyword.uid}`,
          's',
          1,
        );
      }
    } else {
      this.logger.log(`[Matcher] тЭМ No match for "${text}"`);
      await this.writeLog(text, sttResult, sttDurationMs, null, 0);

      this.consecutiveNoMatchCount++;
      const maxFallbackRetries = this.robotConfig.max_inactivity_repeats ?? 3;

      const fallbackAction = this.robotConfig.fallback_bot_action;
      if (fallbackAction && this.consecutiveNoMatchCount < maxFallbackRetries) {
        this.logger.log(`[Action] Executing fallback_bot_action (attempt ${this.consecutiveNoMatchCount}/${maxFallbackRetries})`);
        await this.executeBotAction(fallbackAction, {
          keyword: { uid: -1, keywords: '' } as any,
          confidence: 0,
          matchedPhrase: '',
          matchedWordCount: 0,
          method: 'fallback'
        }, text);
      } else {
        if (this.consecutiveNoMatchCount >= maxFallbackRetries) {
          this.logger.warn(`[Action] Max consecutive no-match retries (${maxFallbackRetries}) reached. Executing max_retries_bot_action or exiting.`);
          const maxRetriesAction = this.robotConfig.max_retries_bot_action;
          if (maxRetriesAction) {
            await this.executeBotAction(maxRetriesAction, {
              keyword: { uid: -1, keywords: '' } as any,
              confidence: 0,
              matchedPhrase: '',
              matchedWordCount: 0,
              method: 'max_retries'
            });
          } else {
            await this.exitToFallback('MAX_RETRIES');
          }
        } else {
          this.logger.log(`[Action] No fallback_bot_action defined, exiting to fallback dialplan`);
          await this.exitToFallback('NO_MATCH');
        }
      }
    }
  }

  // тФАтФАтФА Bot Action Execution Engine тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Execute a bot action: response тЖТ optional slot filling тЖТ next state.
   */
  private async executeBotAction(
    action: IVoiceRobotBotAction,
    matchResult: MatchResult,
    triggeringUtterance?: string,
  ): Promise<void> {
    // 1. Play response (TTS or prompt) тАФ interpolate {{variables}} from dialogueContext
    if (action.response && action.response.type !== 'none') {
      const interpolatedResponse = action.response.value
        ? { ...action.response, value: this.interpolateTemplateString(action.response.value, this.dialogueContext) }
        : action.response;
      await this.speakResponse(interpolatedResponse);

      // Mark information as delivered if this is a successful keyword match
      // (not a fallback or max_retries action)
      if (matchResult.keyword?.uid > 0 && matchResult.confidence > 0) {
        this.informationDelivered = true;
      }
    }

    // 2. If slots are defined, enter slot filling mode
    if (action.slots && action.slots.length > 0) {
      this.slotFillingState = {
        action,
        keyword: matchResult.keyword,
        slots: action.slots,
        filledSlots: {},
        currentSlotIndex: 0,
        retryCount: 0,
      };
      const firstSlot = action.slots[0];
      const utterance = triggeringUtterance?.trim();
      if (
        utterance &&
        firstSlot.type === 'freetext' &&
        firstSlot.prompt?.type === 'none'
      ) {
        this.logger.log(`[Slot] Prefilling "${firstSlot.name}" from triggering utterance`);
        await this.handleSlotInput(utterance, null, 0);
        return;
      }
      await this.askForSlot(firstSlot);
      return;
    }

    // 3. Execute next state immediately (no slots)
    await this.executeNextState(action, {});
  }

  /**
   * Ask the caller for a slot value via TTS.
   */
  private async askForSlot(slot: ISlotDefinition): Promise<void> {
    if (slot.prompt && slot.prompt.type !== 'none' && slot.prompt.value) {
      await this.speakResponse(slot.prompt);
    }
  }

  /**
   * Handle STT input during slot filling.
   */
  private async handleSlotInput(
    text: string,
    sttResult: any,
    sttDurationMs: number,
  ): Promise<void> {
    if (!this.slotFillingState) return;

    const { action, slots, currentSlotIndex, retryCount } = this.slotFillingState;
    const currentSlot = slots[currentSlotIndex];
    const maxRetries = currentSlot.maxRetries || 3;

    // Extract slot value
    const result = this.slotExtractor.extract(text, currentSlot);

    this.logger.log(
      `[Slot] ${currentSlot.name} (${currentSlot.type}): ` +
      `"${text}" тЖТ ${result.success ? result.value : 'FAIL'} ` +
      `(confidence: ${result.confidence.toFixed(2)})`,
    );

    await this.writeLog(text, sttResult, sttDurationMs, this.slotFillingState.keyword.uid, result.confidence);

    if (result.success && result.value !== undefined) {
      // Slot extracted successfully
      this.slotFillingState.filledSlots[currentSlot.name] = result.value;
      // Persist in session-level dialogue context for cross-step memory
      this.dialogueContext[currentSlot.name] = result.value;
      this.slotFillingState.retryCount = 0;

      // Move to next slot
      const nextIndex = currentSlotIndex + 1;
      if (nextIndex < slots.length) {
        this.slotFillingState.currentSlotIndex = nextIndex;
        await this.askForSlot(slots[nextIndex]);
      } else {
        // All slots filled тЖТ execute next state
        const filledSlots = { ...this.slotFillingState.filledSlots };
        const savedAction = this.slotFillingState.action;
        this.slotFillingState = null;
        await this.executeNextState(savedAction, filledSlots);
      }
    } else {
      // Extraction failed тЖТ retry
      this.slotFillingState.retryCount = retryCount + 1;

      if (this.slotFillingState.retryCount >= maxRetries) {
        this.logger.warn(`[Slot] Max retries (${maxRetries}) for slot "${currentSlot.name}"`);
        this.slotFillingState = null;
        this.exitToFallback('SLOT_EXTRACTION_FAILED');
        return;
      }

      // Retry prompt
      if (currentSlot.retryPrompt && currentSlot.retryPrompt.type !== 'none') {
        await this.speakResponse(currentSlot.retryPrompt);
      } else {
        await this.askForSlot(currentSlot);
      }
    }
  }

  /**
   * Execute the next state of a bot action.
   */
  private async executeNextState(
    action: IVoiceRobotBotAction,
    filledSlots: Record<string, string | boolean>,
  ): Promise<void> {
    // Guard: don't execute actions after session cleanup
    if (this.cleanedUp) return;
    const { nextState } = action;
    const target = String(nextState.target || '');

    this.logger.log(`[Action] Executing nextState: ${nextState.type} тЖТ ${target || '(none)'}`);

    try {
      switch (nextState.type) {
        case 'listen':
          // Stay in session, listen for next utterance
          break;

        case 'switch_group': {
          // In-session group switch: filter keywords by group_id + always include globals
          const groupId = Number(target);
          if (groupId) {
            const groupKeywords = this.keywordsDb.filter(k => k.group_id === groupId);
            if (groupKeywords.length > 0) {
              // Push current group to stack for potential "go back"
              const currentGroupId = this.activeKeywords.find(k => !this.globalKeywords.some(g => g.uid === k.uid))?.group_id;
              if (currentGroupId) this.groupStack.push(currentGroupId);
              this.activeKeywords = [...groupKeywords, ...this.globalKeywords];
              this.logger.log(`[FSM] Switched to group ${groupId} (${groupKeywords.length} keywords + ${this.globalKeywords.length} global, stack depth: ${this.groupStack.length})`);
              // Track group name as tag
              const groupMeta = this.keywordGroupsDb.find(g => g.uid === groupId);
              if (groupMeta?.name && !this.visitedTags.includes(groupMeta.name)) {
                this.visitedTags.push(groupMeta.name);
              }
            } else {
              this.logger.warn(`[FSM] Group ${groupId} has no keywords, keeping current set`);
            }
          }
          break;
        }

        case 'transfer_exten': {
          // Transfer call to extension in the tenant dialplan.
          // Format: "700" or "700@sip-out1" тАФ context tenantId appended if missing.
          const [exten, rawContext] = target.includes('@')
            ? target.split('@')
            : [target, undefined];

          if (!exten) {
            this.logger.error(
              `[Action] transfer_exten: extension is empty (target="${target}"). ` +
              `Check onFoundNextState config тАФ extension field must not be blank.`,
            );
            break;
          }

          const resolvedContext = this.resolveContext(rawContext);
          this.lastActionType = 'transfer_exten';
          this.lastTransferTarget = `${exten}@${resolvedContext}`;
          this.cdrDisposition = 'completed';
          await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'TRANSFER_EXTEN');
          this.logger.log(`[Action] Transfer to ${exten}@${resolvedContext}`);
          await this.ariClient.continueInDialplan(this.channelId, resolvedContext, exten, 1);
          break;
        }

        case 'webhook':
          await this.executeWebhook(action, filledSlots);
          break;

        case 'hangup':
          this.lastActionType = 'hangup';
          this.cdrDisposition = 'completed';
          await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'HANGUP');
          await this.ariClient.hangupChannel(this.channelId).catch(() => {});
          break;

        case 'search_data_list':
          // Don't search immediately тАФ wait for the NEXT utterance from the user.
          // The response (╨и╨░╨│ 1) has already been spoken; now enter listen mode
          // and mark pendingDataListSearch so the next STT result triggers the search.
          this.pendingDataListSearch = { action, filledSlots };
          this.logger.log('[DataListSearch] Waiting for next utterance to use as search query...');
          break;

        default:
          this.logger.warn(`[Action] Unknown nextState type: ${nextState.type}`);
      }
    } catch (e: any) {
      this.logger.error(`[Action] executeNextState(${nextState.type}) failed: ${e.message}`);
      this.cdrDisposition = 'error';
      // Attempt graceful cleanup тАФ don't crash the process
      this.cleanup();
    }
  }

  /**
   * Execute webhook: HTTP POST with slot data, then speak template response.
   */
  private async executeWebhook(
    action: IVoiceRobotBotAction,
    filledSlots: Record<string, string | boolean>,
  ): Promise<void> {
    const url = String(action.nextState.target || '');
    if (!url) {
      this.logger.error('[Webhook] No URL configured');
      return;
    }

    // Build payload from template or raw slots
    const payload = action.webhookPayload
      ? this.interpolateTemplate(action.webhookPayload, filledSlots)
      : filledSlots;

    this.logger.log(`[Webhook] POST ${url} with ${Object.keys(payload).length} fields`);

    const headers: Record<string, string> = { 'Content-Type': 'application/json' };

    if (action.webhookAuth) {
      if (action.webhookAuth.mode === 'bearer' && action.webhookAuth.token) {
        headers['Authorization'] = `Bearer ${action.webhookAuth.token}`;
      } else if (action.webhookAuth.mode === 'custom' && action.webhookAuth.customHeaders) {
        for (const h of action.webhookAuth.customHeaders) {
          if (h.key && h.value) {
            headers[h.key] = h.value;
          }
        }
      }
    }

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          robot_id: this.robotConfig.uid,
          robot_name: this.robotConfig.name || null,
          user_uid: this.robotConfig.user_uid || 0,
          channel_id: this.channelId,
          caller_id: this.callerInfo.callerId || null,
          caller_name: this.callerInfo.callerName || null,
          slots: payload,
          context: this.dialogueContext,
          utterance: this.lastRecognizedText,
          timestamp: new Date().toISOString(),
        }),
        signal: AbortSignal.timeout(10000),
      });

      const data = (await response.json().catch(() => ({}))) as Record<string, any>;
      this.logger.log(`[Webhook] Response: ${response.status}, action: ${data.action || 'none'}`);

      // Log PHP exceptions / errors from webhook
      if (data.error) {
        this.logger.error(`[Webhook] Error from webhook: ${data.error}`);
      }

      // тФАтФАтФА Handle non-200 responses (403, 500, etc.) тЖТ treat as fallback тФАтФАтФА
      if (!response.ok) {
        this.logger.warn(`[Webhook] Non-OK status ${response.status} тАФ treating as fallback`);
        this.consecutiveNoMatchCount++;

        const maxRetries = this.robotConfig.max_inactivity_repeats ?? 3;
        if (this.consecutiveNoMatchCount >= maxRetries) {
          this.logger.warn(`[Webhook] Max retries (${maxRetries}) reached after webhook errors`);
          const maxRetriesAction = this.robotConfig.max_retries_bot_action;
          if (maxRetriesAction?.response?.value || maxRetriesAction?.nextState?.type) {
            if (maxRetriesAction.response?.type !== 'none' && maxRetriesAction.response?.value) {
              await this.speakResponse(maxRetriesAction.response);
            }
            if (maxRetriesAction.nextState) {
              await this.executeNextState({ response: { type: 'none' }, nextState: maxRetriesAction.nextState }, {});
            }
          } else {
            this.exitToFallback('MAX_RETRIES');
          }
          return;
        }

        // Execute fallback_bot_action
        const fallbackAction = this.robotConfig.fallback_bot_action;
        if (fallbackAction?.response?.value) {
          this.logger.log(`[Action] Executing fallback_bot_action after webhook error (attempt ${this.consecutiveNoMatchCount}/${maxRetries})`);
          await this.speakResponse(fallbackAction.response);
        }
        this.startInactivityTimer();
        return;
      }

      // тФАтФАтФА 1. Merge context_update from webhook into session memory тФАтФАтФА
      if (data.context_update && typeof data.context_update === 'object') {
        Object.assign(this.dialogueContext, data.context_update);
        this.logger.log(`[Webhook] Context updated: ${Object.keys(data.context_update).join(', ')}`);

        // Log webhook DB errors for diagnostics
        if (data.context_update.db_error) {
          this.logger.error(`[Webhook] DB error from webhook: ${data.context_update.db_error}`);
        }
        if (data.context_update.request_created !== undefined) {
          this.logger.log(`[Webhook] Service request created: ${data.context_update.request_created}, id: ${data.context_update.request_id ?? 'null'}`);
        }
      }

      // Log search debug data from webhook (address lookup diagnostics)
      if (data._search_debug) {
        const sd = data._search_debug;
        this.logger.debug(`[Webhook] Search: query=${JSON.stringify(sd.query_parsed)}, strategy=${sd.strategy}, candidates=${sd.candidates}, scored=${sd.scored}`);
        if (sd.top5?.length) {
          for (const t of sd.top5.slice(0, 3)) {
            this.logger.debug(`[Webhook] Top: "${t.address}" score=${t.total} (street=${t.street_sc}, house=${t.house_sc}, apt=${t.apt_sc})`);
          }
        }
      }

      // Log _debug data from webhook (address not-found diagnostics)
      if (data._debug) {
        const d = data._debug;
        this.logger.debug(`[Webhook] Debug: input="${d.input}", normalized="${d.normalized}", parsed=${JSON.stringify(d.parsed)}, mode=${d.search_mode ?? 'local'}, retries=${d.address_retries ?? 0}`);
      }

      // тФАтФАтФА 2. Speak say_text if webhook provides it (dynamic TTS) тФАтФАтФА
      // Clear inactivity timer first тАФ webhook TTS can take seconds to play,
      // and we don't want the old timer to repeat the greeting during playback
      this.clearInactivityTimer();

      let webhookBotResponse: string | null = null;
      if (data.say_text) {
        // Interpolate {{variables}} in say_text with dialogue context + webhook response data
        const interpolatedSayText = this.interpolateTemplateString(
          data.say_text,
          { ...this.dialogueContext, ...data },
        );
        webhookBotResponse = interpolatedSayText;
        await this.speakResponse({ type: 'tts', value: interpolatedSayText });
        // Mark information as delivered for CDR disposition
        this.informationDelivered = true;
      } else if (action.webhookResponseTemplate) {
        // Fallback: use configured response template
        const responseText = this.interpolateTemplateString(
          action.webhookResponseTemplate,
          { ...filledSlots, ...data },
        );
        webhookBotResponse = responseText;
        await this.speakResponse({ type: 'tts', value: responseText });
        // Mark information as delivered for CDR disposition
        this.informationDelivered = true;
      }

      // тФАтФАтФА 2b. Log webhook interaction in transcript & voice_robot_logs тФАтФАтФА
      {
        const slotSummary = Object.entries(filledSlots)
          .map(([k, v]) => `${k}=${v}`)
          .join(', ');
        const kwUid = this.slotFillingState?.keyword?.uid ?? null;
        const groupId = this.slotFillingState?.keyword?.group_id ?? null;
        this.transcript.push(`[Webhook] POST ${url} (${slotSummary})`);
        if (webhookBotResponse) {
          this.transcript.push(`[╨а╨╛╨▒╨╛╤В] ${webhookBotResponse}`);
        }
        if (data.found !== undefined) {
          this.transcript.push(`[Webhook] found=${data.found}, action=${data.action || 'none'}`);
        }
        // Write log entry for webhook step
        await this.writeLog(
          slotSummary || null,    // recognizedText тАФ slot values sent
          null,                    // sttResult
          0,                       // sttDurationMs
          kwUid,                   // matchedKeywordId
          data.confidence || data.fio_score || 0, // confidence
          groupId,                 // matchedGroupId
          webhookBotResponse,      // botResponse
          { type: 'webhook', url, response: { action: data.action, found: data.found, verified: data.verified } },
        );
      }

      await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'WEBHOOK_OK').catch(() => {});
      await this.ariClient.setChannelVar(this.channelId, 'WEBHOOK_DATA', JSON.stringify(data)).catch((e: any) => {
        this.logger.warn(`[Webhook] Failed to set WEBHOOK_DATA channel var: ${e.message}`);
      });

      // тФАтФАтФА 3. Dynamic Routing via Webhook Response тФАтФАтФА

      // 3a. Terminal: transfer to extension (also handles legacy transfer_queue)
      if ((data.action === 'transfer_exten' || data.action === 'transfer_queue') && data.target) {
        const [whExten, whRawCtx] = String(data.target).includes('@')
          ? String(data.target).split('@')
          : [String(data.target), undefined];
        const whCtx = this.resolveContext(whRawCtx);
        this.logger.log(`[Webhook] Dynamic transfer to ${whExten}@${whCtx}`);
        await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'TRANSFER_EXTEN');
        await this.ariClient.continueInDialplan(this.channelId, whCtx, whExten, 1);
        return;
      }

      // 3c. Terminal: hangup
      if (data.action === 'hangup') {
        this.logger.log(`[Webhook] Dynamic hangup requested`);
        await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'HANGUP');
        await this.ariClient.hangupChannel(this.channelId).catch(() => {});
        return;
      }
      // 3d. Terminal: exit to fallback dialplan (configured by PBX admin)
      if (data.action === 'fallback') {
        this.logger.log(`[Webhook] Fallback requested тАФ exiting to fallback dialplan`);
        // NOTE: say_text is already spoken above (step 2), no need to speak again
        await this.exitToFallback('WEBHOOK_FALLBACK');
        return;
      }

      // 3e. Non-terminal: continue_dialogue тАФ webhook returns control to the robot
      //     with optional new slots to collect or a group to switch to
      if (data.action === 'continue_dialogue') {
        this.logger.log(`[Webhook] continue_dialogue тАФ extending conversation`);
        this.stepCount++;

        // тФАтФАтФА Safety: detect infinite webhook loops тФАтФАтФА
        // Track consecutive continue_dialogue calls to the same URL WITHOUT progress.
        // Reset the counter when the webhook indicates forward progress (found=true,
        // verified=true), so normal multi-step dialogues aren't interrupted.
        // Only loops where the webhook keeps asking the same thing (e.g. apartment
        // not found тЖТ ask again тЖТ not found) will trigger the limit.
        if (data.found === true || data.verified === true) {
          // Webhook made progress тАФ reset loop counter
          this.webhookContinueCounts[url] = 0;
        } else {
          this.webhookContinueCounts[url] = (this.webhookContinueCounts[url] || 0) + 1;
        }

        const webhookLoopLimit = (this.robotConfig.max_inactivity_repeats ?? 3) + 2; // generous limit
        if (this.webhookContinueCounts[url] > webhookLoopLimit) {
          this.logger.warn(
            `[Webhook] Loop detected: ${url} returned continue_dialogue without progress ${this.webhookContinueCounts[url]} times (limit ${webhookLoopLimit}). Breaking loop.`,
          );
          const maxRetriesAction = this.robotConfig.max_retries_bot_action;
          if (maxRetriesAction?.response?.value || maxRetriesAction?.nextState?.type) {
            if (maxRetriesAction.response?.type !== 'none' && maxRetriesAction.response?.value) {
              await this.speakResponse(maxRetriesAction.response);
            }
            if (maxRetriesAction.nextState) {
              await this.executeNextState({ response: { type: 'none' }, nextState: maxRetriesAction.nextState }, {});
            }
          } else {
            this.exitToFallback('WEBHOOK_LOOP');
          }
          return;
        }

        // Check step limit to prevent infinite loops
        if (this.stepCount >= this.maxSteps) {
          this.logger.warn(`[Webhook] Max steps (${this.maxSteps}) reached during continue_dialogue`);
          const maxRetriesAction = this.robotConfig.max_retries_bot_action;
          if (maxRetriesAction?.response?.value || maxRetriesAction?.nextState?.type) {
            if (maxRetriesAction.response?.type !== 'none' && maxRetriesAction.response?.value) {
              await this.speakResponse(maxRetriesAction.response);
            }
            if (maxRetriesAction.nextState) {
              await this.executeNextState({ response: { type: 'none' }, nextState: maxRetriesAction.nextState }, {});
            }
          } else {
            this.exitToFallback('MAX_STEPS');
          }
          return;
        }

        // Option A: webhook provides new slots тЖТ enter slot filling with next_webhook
        const dynamicSlots: ISlotDefinition[] = (data.slots || []).map((s: any) => ({
          name: s.name || 'input',
          type: s.type || 'freetext',
          prompt: s.prompt || { type: 'none' },
          choices: s.choices,
          maxRetries: s.maxRetries || 3,
          retryPrompt: s.retryPrompt,
        }));

        if (dynamicSlots.length > 0) {
          // Build a continuation action that points to next_webhook (or same webhook)
          const continuationAction: IVoiceRobotBotAction = {
            response: { type: 'none' },
            nextState: { type: 'webhook', target: data.next_webhook || url },
            slots: dynamicSlots,
            webhookAuth: action.webhookAuth,
            webhookResponseTemplate: data.response_template,
          };

          // Preserve original keyword/group info for CDR logging
          const originalKeyword = this.slotFillingState?.keyword || { uid: -1, group_id: null } as any;
          this.slotFillingState = {
            action: continuationAction,
            keyword: originalKeyword,
            slots: dynamicSlots,
            filledSlots: {},
            currentSlotIndex: 0,
            retryCount: 0,
          };

          // Reset inactivity timer тАФ new conversation step, fresh timer
          this.inactivityRepeatCount = 0;
          this.clearInactivityTimer();

          // Ask for first slot if it has a prompt
          if (dynamicSlots[0].prompt?.type !== 'none' && dynamicSlots[0].prompt?.value) {
            await this.askForSlot(dynamicSlots[0]);
          } else {
            // No prompt тАФ just start listening with fresh inactivity timer
            this.startInactivityTimer();
          }
          return;
        }

        // Option B: webhook says switch_group тЖТ return to keyword matching in a different group
        if (data.switch_group) {
          const groupId = Number(data.switch_group);
          const groupKeywords = this.keywordsDb.filter(k => k.group_id === groupId);
          if (groupKeywords.length > 0) {
            const currentGroupId = this.activeKeywords[0]?.group_id;
            if (currentGroupId) this.groupStack.push(currentGroupId);
            this.activeKeywords = groupKeywords;
            this.logger.log(`[Webhook] Switched to group ${groupId} via continue_dialogue`);
          } else {
            this.logger.warn(`[Webhook] continue_dialogue switch_group ${groupId}: no keywords found`);
          }
          return;
        }

        // Option C: no slots, no switch тЖТ just return to listening with current keywords
        this.logger.log(`[Webhook] continue_dialogue тАФ returning to listening mode`);
        this.inactivityRepeatCount = 0;
        this.startInactivityTimer();
        return;
      }

      // тФАтФАтФА 3e. No recognized action тАФ terminal response тФАтФАтФА
      // Webhook returned data without action тЖТ response already spoken, slot flow complete
      this.logger.log(`[Webhook] Terminal response (no action) тАФ clearing slot state, returning to listening`);
      this.slotFillingState = null;
      this.inactivityRepeatCount = 0;
      this.startInactivityTimer();

    } catch (e: any) {
      this.logger.error(`[Webhook] Failed: ${e.message}`);
      await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'WEBHOOK_ERROR').catch(() => {});
    }
  }

  // тФАтФАтФА Data List Search тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Execute a data list search: find a row by query, extract a field,
   * store in dialogueContext, then execute onFoundNextState.
   */
  private async executeDataListSearch(
    action: IVoiceRobotBotAction,
    filledSlots: Record<string, string | boolean>,
    forcedQuery?: string,  // when provided, overrides querySource (used from pending search)
  ): Promise<void> {
    const config = action.dataListSearch;
    if (!config) {
      this.logger.warn('[DataListSearch] No dataListSearch config on action');
      return;
    }

    // Default resultVariable to 'result' if not set
    if (!config.resultVariable) {
      config.resultVariable = 'result';
    }

    if (!this.dataListSearchService) {
      this.logger.warn('[DataListSearch] DataListSearchService not available');
      return;
    }

    // Find the data list by ID
    const list = this.dataListsDb.find(dl => dl.uid === config.listId);
    if (!list) {
      this.logger.warn(`[DataListSearch] Data list ${config.listId} not found in session`);
      return;
    }

    // Determine query text
    let query = '';
    if (forcedQuery !== undefined) {
      // Called from pending search тАФ use the utterance that was just spoken
      query = forcedQuery;
    } else if (config.querySource === 'slot' && config.querySlotName) {
      const slotValue = filledSlots[config.querySlotName] ?? this.dialogueContext[config.querySlotName];
      query = String(slotValue || '');
    } else {
      // last_utterance: use the last recognized text from transcript
      query = this.transcript.length > 0 ? this.transcript[this.transcript.length - 1] : '';
    }

    if (!query.trim()) {
      this.logger.warn('[DataListSearch] Empty query, nothing to search');
      if (config.notFoundResponse && config.notFoundResponse.type !== 'none') {
        await this.speakResponse(config.notFoundResponse);
      }
      return;
    }

    this.logger.log(`[DataListSearch] Searching list "${list.name}" for "${query}", return field="${config.returnField}"`);

    // Preload embeddings for this list (cached, fast if already loaded)
    await this.dataListSearchService.preloadList(list);

    // Perform hybrid search (strategy-aware)
    let result;
    if (config.multiMatchStrategy === 'random') {
      const allMatches = await this.dataListSearchService.searchAll(query, list, config.returnField);
      if (allMatches.length > 0) {
        const randomIndex = Math.floor(Math.random() * allMatches.length);
        result = allMatches[randomIndex];
        this.logger.log(
          `[DataListSearch] Random pick: ${randomIndex + 1}/${allMatches.length} matches`,
        );
      } else {
        result = null;
      }
    } else {
      result = await this.dataListSearchService.search(query, list, config.returnField);
    }

    if (result) {
      this.logger.log(
        `[DataListSearch] тЬЕ Found: ${config.resultVariable}="${result.value}" ` +
        `(confidence: ${result.confidence.toFixed(3)}, method: ${result.method})`,
      );

      // Reset not-found counter on success
      this.dataListNotFoundCounts[config.listId] = 0;

      // Reset no-match counter тАФ successful search = valid interaction
      this.consecutiveNoMatchCount = 0;

      // Mark information as delivered for CDR disposition
      this.informationDelivered = true;

      // Store result in dialogueContext for use in TTS templates and subsequent actions
      this.dialogueContext[config.resultVariable] = result.value;

      // Store full row as well for multi-field access
      for (const [key, val] of Object.entries(result.row)) {
        this.dialogueContext[`${config.resultVariable}_${key}`] = val;
      }

      // Set channel variable for dialplan access
      await this.ariClient.setChannelVar(this.channelId, 'DATA_LIST_RESULT', result.value).catch(() => {});

      // Speak onFoundResponse if configured (supports {{variable}} interpolation)
      if (config.onFoundResponse && config.onFoundResponse.type !== 'none' && config.onFoundResponse.value) {
        // Clear inactivity timer before speaking тАФ response can be long
        this.clearInactivityTimer();
        const interpolatedText = this.interpolateTemplateString(
          config.onFoundResponse.value,
          this.dialogueContext,
        );
        this.logger.log(`[DataListSearch] Speaking onFoundResponse: "${interpolatedText.substring(0, 80)}${interpolatedText.length > 80 ? '...' : ''}"`);
        await this.speakResponse({ type: config.onFoundResponse.type, value: interpolatedText });
      } else {
        // Auto-speak result value if no explicit onFoundResponse configured
        this.clearInactivityTimer();
        this.logger.log(`[DataListSearch] No onFoundResponse configured тАФ auto-speaking result`);
        await this.speakResponse({ type: 'tts', value: result.value });
      }

      // Execute onFoundNextState if configured
      if (config.onFoundNextState) {
        // Resolve target: interpolate {{variables}}, or fall back to resultVariable if ext part empty
        let rawTarget = config.onFoundNextState.target
          ? String(config.onFoundNextState.target)
          : '';

        // Handle case where user set context but left extension blank (e.g. '@sip-out')
        if (config.onFoundNextState.type === 'transfer_exten') {
          const atIdx = rawTarget.indexOf('@');
          const extPart = atIdx >= 0 ? rawTarget.slice(0, atIdx) : rawTarget;
          const ctxPart = atIdx >= 0 ? rawTarget.slice(atIdx + 1) : '';

          if (!extPart && config.resultVariable) {
            // Auto-use result variable as extension
            rawTarget = `{{${config.resultVariable}}}${ctxPart ? '@' + ctxPart : ''}`;
            this.logger.log(
              `[DataListSearch] Auto-filled empty extension with {{${config.resultVariable}}}`,
            );
          }
        }

        const interpolatedTarget = this.interpolateTemplateString(rawTarget, this.dialogueContext);

        this.logger.log(
          `[DataListSearch] onFoundNextState: type=${config.onFoundNextState.type}, ` +
          `rawTarget="${rawTarget}" тЖТ resolved="${interpolatedTarget}"`,
        );

        const syntheticAction: IVoiceRobotBotAction = {
          response: { type: 'none' },
          nextState: {
            type: config.onFoundNextState.type,
            target: interpolatedTarget,
          },
        };

        await this.executeNextState(syntheticAction, filledSlots);
      }
    } else {
      // тФАтФАтФА Not found logic with retries тФАтФАтФА
      const notFoundCount = (this.dataListNotFoundCounts[config.listId] || 0) + 1;
      this.dataListNotFoundCounts[config.listId] = notFoundCount;
      const maxRetries = config.maxNotFoundRetries ?? 1;

      this.logger.log(
        `[DataListSearch] тЭМ No match for "${query}" in list "${list.name}" ` +
        `(attempt ${notFoundCount}/${maxRetries})`,
      );

      if (notFoundCount >= maxRetries && config.notFoundNextState) {
        // Max retries exhausted тЖТ execute notFoundNextState
        this.logger.log(
          `[DataListSearch] Max not-found retries reached тЖТ executing notFoundNextState: ${config.notFoundNextState.type}`,
        );

        // Speak not-found response before executing the action
        if (config.notFoundResponse && config.notFoundResponse.type !== 'none') {
          await this.speakResponse(config.notFoundResponse);
        }

        // Reset counter
        this.dataListNotFoundCounts[config.listId] = 0;

        const syntheticAction: IVoiceRobotBotAction = {
          response: { type: 'none' },
          nextState: {
            type: config.notFoundNextState.type,
            target: config.notFoundNextState.target,
          },
        };

        await this.executeNextState(syntheticAction, filledSlots);
      } else {
        // Still have retries left тЖТ speak not-found response and return to listening
        if (config.notFoundResponse && config.notFoundResponse.type !== 'none') {
          await this.speakResponse(config.notFoundResponse);
        }
        // Robot returns to listen mode automatically (no explicit action needed)
      }
    }
  }

  // тФАтФАтФА TTS Playback тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Speak a bot response (TTS or prompt).
   */
  private async speakResponse(
    response: { type: string; value?: string },
  ): Promise<void> {
    if (!response.value) return;
    // Guard: don't speak after session cleanup (prevents zombie timers)
    if (this.cleanedUp) return;

    if (response.type === 'tts') {
      this.isBotSpeaking = true;
      this.pipelineAbort = new AbortController();
      try {
        if (!this.ttsEngine) {
          this.logger.warn('[TTS] No engine configured тАФ skipping synthesis');
          return;
        }
        const mode = this.robotConfig.tts_mode || 'batch';
        this.logger.log(`[TTS/${mode}] "${response.value.substring(0, 60)}${response.value.length > 60 ? '...' : ''}"`);

        if (mode === 'streaming') {
          await this.speakStreaming(response.value);
        } else {
          await this.speakBatch(response.value);
        }
      } catch (e: any) {
        if (e.name !== 'AbortError') {
          this.logger.error(`[TTS] Error: ${e.message}`);
        }
      } finally {
        const wasBargeIn = !this.pipelineAbort || this.pipelineAbort.signal.aborted;
        this.isBotSpeaking = false;
        this.pipelineAbort = null;

        if (wasBargeIn) {
          // тФАтФАтФА BARGE-IN PATH тФАтФАтФА
          // User interrupted TTS тАФ the OLD STT stream likely has the user's
          // speech in its pipeline (e.g. Yandex Final "╨╜╨╡╤В" pending delivery).
          // DON'T close the old stream тАФ let it deliver Final/EOU naturally.
          // Since isBotSpeaking is now false, the EOU handler will process it.
          this.logger.debug('[TTS] Barge-in тАФ keeping STT stream for pending user speech');
          // Only clear partial text to avoid echo, but preserve any Final
          // that may have already arrived
          this.sttStreamPartialText = '';

        } else {
          // тФАтФАтФА NORMAL TTS END PATH тФАтФАтФА
          // Check if STT captured user speech during TTS (not just echo).
          const capturedText = (this.sttStreamPartialText || this.sttStreamFinalText).trim();
          const ttsText = (response.value || '').toLowerCase();
          let preservedUserSpeech = '';

          if (capturedText && capturedText.length > 1) {
            const capturedWords = capturedText.toLowerCase().split(/\s+/).filter(w => w.length > 1);
            const ttsWords = new Set(ttsText.split(/\s+/).filter(w => w.length > 1));
            const matchCount = capturedWords.filter(w => ttsWords.has(w)).length;
            const isLikelyEcho = capturedWords.length > 0 && matchCount > capturedWords.length * 0.5;

            if (!isLikelyEcho) {
              preservedUserSpeech = capturedText;
              this.logger.log(`[TTS] Detected user speech during TTS: "${capturedText}"`);
            }
          }

          // Clear STT buffers (echo or already preserved above)
          this.sttStreamFinalText = '';
          this.sttStreamPartialText = '';

          // Close echo-contaminated stream, recreate fresh
          if (this.sttStream) {
            try { this.sttStream.end(); } catch {}
            this.sttStream = null;
          }
          if (!this.cleanedUp) {
            this.initStreamingStt();
          }

          // If we detected user speech during TTS, schedule processing
          if (preservedUserSpeech && !this.cleanedUp) {
            const textToProcess = preservedUserSpeech;
            setTimeout(() => {
              if (this.cleanedUp) return;
              this.logger.log(`[TTS] Processing preserved user speech: "${textToProcess}"`);
              this.enqueueUtterance(() => this.handleStreamingSttResult(textToProcess)).catch((err) => {
                this.logger.warn(`[TTS] Failed to process preserved speech: ${err.message}`);
              });
            }, 100);
          }
        }

        // Start inactivity timer after bot finishes speaking
        this.startInactivityTimer();
      }
    } else if (response.type === 'prompt' && response.value) {
      try {
        await this.ariClient.playMedia(this.channelId, `sound:${response.value}`);
      } catch (e: any) {
        this.logger.warn(`[Prompt] Failed to play "${response.value}": ${e.message}`);
      }
      // Start inactivity timer after prompt finishes
      this.startInactivityTimer();
    }

    // Remember last bot response for inactivity repeats
    this.lastBotResponse = response;
  }

  /**
   * Streaming TTS: send PCM16 chunks тЖТ A-law тЖТ RTP in real-time.
   * Low latency (~100-200ms first byte), no caching.
   * Best for: dynamic webhook responses, interpolated templates.
   */
  private async speakStreaming(text: string): Promise<void> {
    await this.ttsFactory.synthesize(
      this.ttsEngine!,
      text,
      (pcm16: Buffer) => {
        if (isTtsPipelineAborted(this.pipelineAbort)) return;
        const alaw = this.audioService.encodePcm16ToAlaw(pcm16);
        this.streamAudio.streamAudio(this.channelId, alaw);
      },
      this.pipelineAbort?.signal,
    );
  }

  /**
   * Batch TTS with MD5 cache: synthesize once тЖТ store as .alaw тЖТ reuse.
   * Zero latency on cache hits, ~1-2s on first synthesis.
   * Best for: greetings, FAQ responses, static prompts.
   */
  private async speakBatch(text: string): Promise<void> {
    // Yandex SpeechKit v3 limit is ~250 chars; split long texts into chunks
    const MAX_CHUNK_LEN = 230;
    const chunks = text.length > MAX_CHUNK_LEN
      ? this.splitTextIntoChunks(text, MAX_CHUNK_LEN)
      : [text];

    if (chunks.length > 1) {
      this.logger.log(`[TTS] Long text (${text.length} chars) тЖТ split into ${chunks.length} chunks`);
    }

    for (const chunk of chunks) {
      if (isTtsPipelineAborted(this.pipelineAbort)) return;

      const settings = this.ttsEngine!.settings || {};
      const cacheKey = this.ttsCache.getCacheKey(
        chunk,
        settings.voice || 'default',
        settings.speed || 1.0,
        this.ttsEngine!.type,
      );

      let alawBuffer: Buffer;

      if (this.ttsCache.has(cacheKey)) {
        alawBuffer = this.ttsCache.get(cacheKey);
        this.logger.debug(`[TTS] Cache HIT: ${cacheKey.substring(0, 8)}... (${alawBuffer.length} bytes)`);
      } else {
        const pcm16 = await this.ttsFactory.synthesizeBatch(this.ttsEngine!, chunk);
        alawBuffer = this.audioService.encodePcm16ToAlaw(pcm16);
        this.ttsCache.put(cacheKey, alawBuffer);
        this.logger.log(
          `[TTS] Cache MISS тЖТ saved: ${cacheKey.substring(0, 8)}... (${alawBuffer.length} bytes, ` +
          `~${(alawBuffer.length / 8000).toFixed(1)}s audio)`,
        );
      }

      if (isTtsPipelineAborted(this.pipelineAbort)) return;
      await this.streamAudio.streamAudio(this.channelId, alawBuffer);
      if (isTtsPipelineAborted(this.pipelineAbort)) return;
    }
  }

  /**
   * Split text into chunks that don't exceed maxLen.
   * Tries to split by sentence boundaries first, then by commas/semicolons.
   */
  private splitTextIntoChunks(text: string, maxLen: number): string[] {
    const chunks: string[] = [];
    let remaining = text.trim();

    while (remaining.length > maxLen) {
      // Try to split at sentence boundary (. ! ?)
      let splitIdx = -1;
      for (let i = maxLen - 1; i >= maxLen * 0.4; i--) {
        if ('.!?\n'.includes(remaining[i])) {
          splitIdx = i + 1;
          break;
        }
      }

      // Fallback: split at comma, semicolon, or closing paren
      if (splitIdx === -1) {
        for (let i = maxLen - 1; i >= maxLen * 0.4; i--) {
          if (',;)'.includes(remaining[i])) {
            splitIdx = i + 1;
            break;
          }
        }
      }

      // Last resort: split at last space
      if (splitIdx === -1) {
        splitIdx = remaining.lastIndexOf(' ', maxLen - 1);
        if (splitIdx <= 0) splitIdx = maxLen; // no space found тАФ hard cut
      }

      chunks.push(remaining.substring(0, splitIdx).trim());
      remaining = remaining.substring(splitIdx).trim();
    }

    if (remaining.length > 0) {
      chunks.push(remaining);
    }

    return chunks;
  }

  // тФАтФАтФА Template Interpolation тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Interpolate {{variable}} placeholders in an object's values.
   */
  private interpolateTemplate(
    template: Record<string, string>,
    data: Record<string, string | boolean>,
  ): Record<string, any> {
    const result: Record<string, any> = {};
    for (const [key, value] of Object.entries(template)) {
      result[key] = this.interpolateTemplateString(value, data);
    }
    return result;
  }

  /**
   * Interpolate {{variable}} placeholders in a string.
   */
  private interpolateTemplateString(
    template: string,
    data: Record<string, any>,
  ): string {
    return template.replace(/\{\{([\p{L}\p{N}_]+)\}\}/gu, (_, key) => {
      return data[key] !== undefined ? String(data[key]) : `{{${key}}}`;
    });
  }

  /**
   * Exit the session via Fallback dialplan.
   */
  private async exitToFallback(status: string = 'FALLBACK'): Promise<void> {
    try {
      await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', status);
      await this.ariClient.continueInDialplan(this.channelId);
    } catch (e: any) {
      this.logger.error(`Failed to exit to fallback: ${e.message}`);
    }
  }

  /**
   * Abort current TTS/pipeline for barge-in.
   */
  private abortPipeline(): void {
    // Keep the aborted controller тАФ speakBatch checks signal.aborted before
    // the next chunk. Nulling it made leftover chunks play after barge-in.
    abortTtsPipeline(this.pipelineAbort);
    this.isBotSpeaking = false;
  }

  /**
   * Write a log entry for this STT+match attempt.
   */
  private async writeLog(
    recognizedText: string | null,
    sttResult: any | null,
    sttDurationMs: number,
    matchedKeywordId: number | null,
    confidence: number,
    matchedGroupId?: number | null,
    botResponse?: string | null,
    flowAction?: any | null,
  ): Promise<void> {
    try {
      // Track transcript for CDR
      if (recognizedText) {
        this.transcript.push(`[╨Ъ╨╗╨╕╨╡╨╜╤В] ${recognizedText}`);
      }
      if (botResponse) {
        this.transcript.push(`[╨а╨╛╨▒╨╛╤В] ${botResponse}`);
      }

      // Track CDR stats
      if (matchedKeywordId) {
        this.totalMatches++;
        this.totalConfidence += confidence;
      } else {
        this.noMatchCount++;
      }

      const actionTaken = matchedKeywordId ? `voicerobot_keyword_${matchedKeywordId}` : 'no_match';

      await this.logModel.create({
        robot_id: this.robotConfig.uid,
        call_uniqueid: this.callerInfo.callUniqueId || this.channelId,
        session_id: this.sessionId,
        channel_id: this.channelId,
        caller_id: this.callerInfo.callerId,
        step_number: this.stepCount,
        matched_group_id: matchedGroupId || null,
        recognized_text: recognizedText,
        raw_stt_json: sttResult?.rawJson || { streaming: true },
        matched_keyword_id: matchedKeywordId,
        match_confidence: confidence,
        action_taken: actionTaken,
        stt_duration_ms: sttDurationMs,
        matching_score: sttResult?.matchingScore || null,
        ai_response: botResponse || null,
        flow_action: flowAction || null,
        user_uid: this.robotConfig.user_uid,
      });
    } catch (e: any) {
      this.logger.error(`Failed to write log: ${e.message}`);
    }
  }

  /**
   * Write CDR record (1 per call) тАФ called from cleanup().
   */
  private async writeCdr(): Promise<void> {
    try {
      const endedAt = new Date();
      const durationSeconds = Math.round((endedAt.getTime() - this.startedAt.getTime()) / 1000);

      // Smart disposition: determine actual call outcome from collected data
      const effectiveDisposition = this.resolveDisposition();

      await this.cdrModel.create({
        robot_id: this.robotConfig.uid,
        robot_name: this.robotConfig.name,
        call_uniqueid: this.callerInfo.callUniqueId || this.channelId,
        channel_id: this.channelId,
        session_id: this.sessionId,
        caller_id: this.callerInfo.callerId,
        caller_name: this.callerInfo.callerName,
        started_at: this.startedAt,
        ended_at: endedAt,
        duration_seconds: durationSeconds,
        disposition: effectiveDisposition,
        last_action: this.lastActionType,
        transfer_target: this.lastTransferTarget,
        total_steps: this.stepCount,
        matched_keywords_count: this.totalMatches,
        no_match_count: this.noMatchCount,
        avg_confidence: this.totalMatches > 0
          ? Math.round((this.totalConfidence / this.totalMatches) * 100) / 100
          : null,
        collected_slots: {
          ...(this.slotFillingState?.filledSlots || {}),
          ...this.dialogueContext,
        },
        transcript: this.transcript.join('\n') || null,
        tags: this.visitedTags.length > 0 ? this.visitedTags : null,
        user_uid: this.robotConfig.user_uid,
      });

      this.logger.log(
        `CDR written: ${this.sessionId} (${effectiveDisposition}, ${durationSeconds}s, ${this.stepCount} steps, ` +
        `action=${this.lastActionType || 'none'}, infoDelivered=${this.informationDelivered})`,
      );
    } catch (e: any) {
      this.logger.error(`Failed to write CDR: ${e.message}`);
    }
  }

  /**
   * Resolve final CDR disposition based on explicit status + collected data.
   *
   * Priority:
   *  1. Explicitly set dispositions (error, timeout, max_steps) тАФ always respected
   *  2. Bot executed a terminal action (transfer_exten, hangup) тАФ 'completed'
   *  3. Caller received information (data list found, webhook data) тАФ 'completed'
   *     even if the caller hung up (they got the info they needed)
   *  4. Some meaningful interaction but no data delivered тАФ 'caller_hangup'
   *  5. No interaction at all тАФ 'caller_hangup'
   */
  private resolveDisposition(): string {
    // 1. Explicit error/timeout/max_steps тАФ always take priority
    if (['error', 'timeout', 'max_steps'].includes(this.cdrDisposition)) {
      return this.cdrDisposition;
    }

    // 2. Bot executed a terminal action (transfer or hangup by scenario) тАФ success
    if (this.lastActionType === 'transfer_exten' || this.lastActionType === 'hangup') {
      return 'completed';
    }

    // 3. Transfer happened тАФ success
    if (this.lastTransferTarget) {
      return 'completed';
    }

    // 4. Check if caller received meaningful information during the session
    if (this.callerReceivedInformation()) {
      return 'completed';
    }

    // 5. Some interaction happened but no data found тАФ caller left mid-flow
    if (this.totalMatches > 0 && this.stepCount >= 2) {
      return 'caller_hangup';
    }

    // 6. Very short call, no interaction
    if (this.stepCount === 0 || this.totalMatches === 0) {
      return 'caller_hangup';
    }

    return this.cdrDisposition;
  }

  /**
   * Determine if the caller received meaningful information during the session.
   *
   * Checks multiple signals:
   * - Explicit informationDelivered flag (set by data list search / webhook)
   * - dialogueContext has any non-empty data values
   *   (webhook/data-list results are stored here)
   */
  private callerReceivedInformation(): boolean {
    // Explicit flag set by data list search or webhook success
    if (this.informationDelivered) {
      return true;
    }

    // Check dialogueContext for any data that was delivered to the caller
    const ctx = this.dialogueContext;
    const dataKeys = Object.keys(ctx).filter(k =>
      !k.startsWith('_') && ctx[k] !== undefined && ctx[k] !== null && ctx[k] !== '',
    );
    if (dataKeys.length > 0) {
      return true;
    }

    return false;
  }

  // тФАтФАтФА Inactivity Timer тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА

  /**
   * Start inactivity timer after bot finishes speaking.
   * If user doesn't respond within silence_timeout_seconds,
   * repeat the last question. After MAX_INACTIVITY_REPEATS,
   * execute fallback action.
   */
  private startInactivityTimer(): void {
    // Guard: don't start timers after session cleanup
    if (this.cleanedUp) return;
    this.clearInactivityTimer();

    const timeoutSec = this.robotConfig.silence_timeout_seconds || 15;
    const maxRepeats = this.robotConfig.max_inactivity_repeats ?? 3;
    this.logger.debug(`[Inactivity] Timer started: ${timeoutSec}s (repeat ${this.inactivityRepeatCount}/${maxRepeats})`);

    this.inactivityTimer = setTimeout(() => {
      this.handleInactivityTimeout();
    }, timeoutSec * 1000);
  }

  /**
   * Clear the inactivity timer (called when user starts speaking).
   */
  private clearInactivityTimer(): void {
    if (this.inactivityTimer) {
      clearTimeout(this.inactivityTimer);
      this.inactivityTimer = null;
    }
  }

  /**
   * Handle inactivity timeout:
   * 1. If repeats < MAX тЖТ repeat last bot response
   * 2. If repeats >= MAX тЖТ execute fallback action or exit
   */
  private async handleInactivityTimeout(): Promise<void> {
    // Guard: don't process timeout after session cleanup
    if (this.cleanedUp) return;
    this.inactivityRepeatCount++;
    const maxRepeats = this.robotConfig.max_inactivity_repeats ?? 3;

    if (this.inactivityRepeatCount > maxRepeats) {
      this.inactivityFallbackCycles++;
      this.logger.warn(
        `[Inactivity] Max repeats (${maxRepeats}) exceeded тАФ fallback cycle ${this.inactivityFallbackCycles}/${VoiceRobotSession.MAX_INACTIVITY_FALLBACK_CYCLES}`,
      );
      this.inactivityRepeatCount = 0;

      // Safety net: if fallback keeps returning to 'listen', stop after N cycles
      if (this.inactivityFallbackCycles >= VoiceRobotSession.MAX_INACTIVITY_FALLBACK_CYCLES) {
        this.logger.warn(`[Inactivity] Max fallback cycles reached тАФ hanging up`);
        this.cdrDisposition = 'timeout';
        await this.ariClient.setChannelVar(this.channelId, 'ROBOT_STATUS', 'INACTIVITY_HANGUP').catch(() => {});
        await this.ariClient.hangupChannel(this.channelId).catch(() => {});
        return;
      }

      const fallbackAction = this.robotConfig.fallback_bot_action;
      if (fallbackAction) {
        await this.executeBotAction(fallbackAction, {
          keyword: { uid: -1, keywords: '' } as any,
          confidence: 0,
          matchedPhrase: '',
          matchedWordCount: 0,
          method: 'fallback',
        });
      } else {
        await this.exitToFallback('INACTIVITY_TIMEOUT');
      }
      return;
    }

    this.logger.log(`[Inactivity] No response тАФ repeating last question (${this.inactivityRepeatCount}/${maxRepeats})`);

    // Repeat last bot response
    if (this.lastBotResponse && this.lastBotResponse.value) {
      await this.speakResponse(this.lastBotResponse);
    } else {
      // No last response to repeat тЖТ start timer again anyway
      this.startInactivityTimer();
    }
  }

  /**
   * Full cleanup тАФ idempotent, call on StasisEnd or error.
   */
  cleanup(): void {
    if (this.cleanedUp) return;
    this.cleanedUp = true;

    this.logger.log(`Cleaning up session for ${this.channelId}`);

    // Write CDR record (async, fire-and-forget)
    this.writeCdr().catch((e) => this.logger.error(`CDR write failed: ${e.message}`));

    // Cancel timers
    if (this.silenceTimer) clearTimeout(this.silenceTimer);
    if (this.maxDurationTimer) clearTimeout(this.maxDurationTimer);
    this.clearInactivityTimer();

    // Abort any TTS pipeline
    this.abortPipeline();

    // Destroy per-session VAD instance (release ONNX resources)
    if (this.vadInstance) {
      this.vadInstance.destroy();
      this.vadInstance = null;
    }

    // Destroy ARI bridge (removes all channels from it)
    if (this.bridge?.id) {
      this.ariClient.destroyBridge(this.bridge.id).catch(() => {});
    }

    // Hangup ExternalMedia channel
    if (this.externalChannel?.id) {
      this.ariClient.hangupChannel(this.externalChannel.id).catch(() => {});
    }

    // Close UDP socket and remove from RtpUdpServerService registry (prevents activeSessions leak)
    if (this.rtpSession) {
      this.udpServer.closeSession(this.rtpSession.port);
      this.rtpSession = null;
    }

    // Remove StreamAudio sender
    this.streamAudio.removeStream(this.channelId);

    // Close streaming STT session (if active)
    if (this.sttStream) {
      try { this.sttStream.end(); } catch { /* ignore */ }
      this.sttStream = null;
    }

    // Reset VAD state
    this.sttBuffer = [];
    this.preSpeechRingBuffer.length = 0;
  }

  /** Set CDR disposition (called before cleanup for specific exit reasons) */
  setDisposition(disposition: typeof this.cdrDisposition): void {
    this.cdrDisposition = disposition;
  }
}

